window.QUESTIONS_QZ_VI = {"PRM-001":{"q":"Điều nào sau đây là ví dụ tốt nhất về trường hợp bạn KHÔNG nên chọn Flutter và thay vào đó nên xây dựng nguyên gốc?","options":["Một ứng dụng đặt vé xem phim đơn giản","Ứng dụng thương mại điện tử có UI tiêu chuẩn","Trò chơi đồ họa thời gian thực đòi hỏi quyền truy cập phần cứng cấp thấp","Ứng dụng bảng điều khiển quản lý doanh nghiệp nội bộ"],"exp":"Một trò chơi thời gian thực, sử dụng nhiều đồ họa yêu cầu quyền truy cập phần cứng cấp thấp là ví dụ trong sách giáo khoa về 'Khi thích hợp cho việc phát triển bản địa'. A, B, D đều là những trường hợp trong đó Flutter rất phù hợp."},"PRM-002":{"q":"Trong Dart, `Set<int> s = {1, 2, 2, 3};` --- sau khi khởi tạo, `s.length` là gì?","options":["4","3","2","Lỗi biên dịch vì Set không cho phép các phần tử trùng lặp trong khai báo"],"exp":"Set xóa các bản sao: `{1,2,2,3}` trở thành `{1,2,3}` → length = 3. A đếm sai số trùng lặp; C thiếu một phần tử; D sai vì Set cho phép trùng lặp trong khai báo, nó chỉ tự động xóa chúng khi được lưu trữ."},"PRM-003":{"q":"Hãy xem xét mã hàm tạo có tên này: class Point { int x, y; Point(this.x, this.y); Point.origin() : x = 0, y = 0; } void main() { var p1 = Point(3, 4); var p2 = Point.origin(); print('${p1.x},${p1.y} - ${p2.x},${p2.y}'); } Cái gì được in?","options":["0,0 - 3,4","3,4 - 0,0","Lỗi vì Dart không hỗ trợ nhiều hàm tạo trong cùng một class","vô giá trị, vô giá trị - 0,0"],"exp":"`Point(3,4)` gán x=3,y=4; `Point.origin()` gán x=0,y=0 thông qua danh sách khởi tạo --- in \"3,4 - 0,0\". A đảo ngược đầu ra; C sai vì Dart hỗ trợ các hàm tạo được đặt tên; D sai vì các giá trị được gán chính xác chứ không phải rỗng."},"PRM-004":{"q":"Với hàm này: void greet({String name = \"Guest\", int age = 18}) { print(\"\\$name is \\$age\"); } Việc gọi `greet(name: \"Lan\");` sẽ in ra cái gì?","options":["Lỗi do thiếu tham số age","Lan is 18","Guest is 18","Lan is vô giá trị"],"exp":"`greet(name: \"Lan\")` chỉ vượt qua name; age sử dụng giá trị mặc định là 18 → \"Lan is 18\". is sai vì age có giá trị mặc định; C is sai vì name đã được thông qua; D is sai vì age rõ ràng có giá trị mặc định."},"PRM-005":{"q":"Hãy xem xét mã OOP này: class Animal { String sound() => \"Some sound\"; } class Dog extends Animal { @override String sound() => \"Woof\"; } void main() { Animal a = Dog(); print(a.sound()); } Cái gì được in và nó minh họa khái niệm OOP nào?","options":["Some sound\" --- minh họa Đóng gói","Woof\" --- minh họa tính đa hình thông qua phương thức override","Lỗi biên dịch vì không thể gán Dog cho biến có kiểu Animal","Woof Some sound\" --- cả hai hàm đều được gọi"],"exp":"Điều này minh họa Tính đa hình: một biến được nhập dưới dạng Animal gọi phương thức được ghi đè của Dog khi chạy, in \"Woof\". A dán nhãn sai cho khái niệm; C sai vì việc cập nhật là hợp lệ; D sai vì chỉ có một phương thức được gọi."},"PRM-006":{"q":"Cho mã nội suy chuỗi này: String name = \"FPT University\"; print(\"Hello \\$name\"); print(\"Length: \\${name.length}\"); print(\"Upper: \\${name.toUpperCase()[0]}\"); Dòng thứ ba in ký tự gì?","options":["f","F","FPT","Lỗi vì bạn không thể lập chỉ mục trực tiếp vào kết quả hàm bên trong phép nội suy chuỗi"],"exp":"`name.toUpperCase()` = \"FPT ĐẠI HỌC\", chỉ số [0] = 'F'. A có trường hợp sai; C không phải là một ký tự đơn lẻ; D sai vì Dart cho phép lập chỉ mục kết quả hàm trực tiếp bên trong phép nội suy chuỗi."},"PRM-007":{"q":"Trong Dart, vai trò của hàm `main()` là gì?","options":["Đó là lệnh gọi lại được gọi lần cuối khi ứng dụng đóng","Đây là điểm bắt đầu thực thi của mọi chương trình Dart","Chỉ được sử dụng trong Flutter, không được sử dụng trong Dart thuần túy","Một hàm dùng để định nghĩa các lớp"],"exp":"`main()` là điểm bắt đầu thực thi cho mọi chương trình Dart. A, C, D mô tả sai vai trò của hàm main."},"PRM-008":{"q":"Trong `List<int> nums = [1,2,3]; for(var x in nums) print(x);`, mục đích chính của việc sử dụng `var` thay vì `int` cho biến `x` là gì?","options":["Phải sử dụng `var` vì `int` sẽ gây ra lỗi","Kiểu suy luận --- Dart tự động suy ra dữ liệu type (int) dựa trên các phần tử của List, giữ cho mã ngắn gọn trong khi vẫn được gõ mạnh","`var` tạo biến x hoàn toàn dynamic mà không cần kiểm tra loại nào cả","Không có gì khác biệt cả, đó chỉ là thói quen viết mã"],"exp":"`var` cho phép Dart suy ra type (int) từ các phần tử của List, giữ cho mã ngắn gọn trong khi vẫn được gõ mạnh. A sai vì int có giá trị như nhau; C sai vì var khác với dynamic; D sai vì có sự suy luận kiểu in khác biệt ngay cả khi kết quả thời gian chạy trông giống nhau."},"PRM-009":{"q":"Với mã này, hãy dự đoán kết quả của việc gọi `Eagle().fly()`: class Bird { void fly() => print(\"Bird flying\"); } class Eagle implements Bird { @override void fly() => print(\"Eagle gliding\"); }","options":["Bird flying\" vì implements cũng kế thừa phần thân phương thức","Eagle gliding\" --- vì implements chỉ lấy interface (chữ ký), nên Eagle phải tự xác định lại hoàn toàn fly()","Lỗi biên dịch vì Eagle chưa xác định hàm tạo","Cả \"Bird flying\" và \"Eagle gliding\" đều được in"],"exp":"Vì `implements` chỉ lấy chữ ký nên Eagle phải xác định lại hoàn toàn fly() → in \"Eagle gliding\". A sai vì implements không kế thừa phần thân phương thức; C sai vì ở đây không cần hàm tạo nào; D sai vì chỉ có một phương thức được gọi."},"PRM-010":{"q":"Với ràng buộc chung này: abstract class Animal { String sound(); } class Cat extends Animal { sound() => \"Meow\"; } class Box`<T extends Animal>` { T pet; Box(this.pet); void play() => print(pet.sound()); } Cú pháp `<T extends Animal>` có nghĩa là gì?","options":["Box chỉ có thể chứa loại Animal chính xác, không có lớp con nào được chấp nhận","Hạn chế loại chung T là Animal hoặc lớp con của Animal, đảm bảo T luôn có phương thức sound()","Đây là cú pháp không hợp lệ, Dart không hỗ trợ các ràng buộc chung","`extends` ở đây có nghĩa là Box kế thừa từ Animal"],"exp":"`<T extends Animal>` giới hạn T chung ở Animal hoặc các lớp con của nó, đảm bảo T có phương thức sound(). A sai vì các lớp con vẫn được chấp nhận; C sai vì this là cú pháp hợp lệ; D nhầm lẫn ràng buộc chung `extends` với kế thừa class."},"PRM-011":{"q":"Cho trước: var base = [1, 2, 3]; var list = [ ...base, if (true) 99, for (var x in base) x * 10 ]; print(list); Cái gì được in?","options":["[1, 2, 3, 99, 10, 20, 30]","[1, 2, 3, 10, 20, 30, 99]","[99, 1, 2, 3, 10, 20, 30]","Lỗi biên dịch vì bạn không thể kết hợp spread, if và for in giống nhau List"],"exp":"`[...base, if(true) 99, for(x in base) x*10]` = [1,2,3, 99, 10,20,30]. B, C sai thứ tự; D sai vì Dart cho phép trộn lẫn các cú pháp này."},"PRM-012":{"q":"Trong ví dụ `AnimationController implements Listenable` được đề cập trong bài giảng, việc sử dụng `implements` thay vì `extends` thể hiện điều gì?","options":["AnimationController sao chép tất cả mã hiện có của Listenable","AnimationController chỉ tuân theo hợp đồng của Listenable và hành vi của chính implements mà không kế thừa cách triển khai hiện có","AnimationController và Listenable không liên quan với nhau","Đây là lỗi cú pháp, phải sử dụng `extends`"],"exp":"`implements` có nghĩa là AnimationController chỉ tuân theo hợp đồng và implements hành vi của chính nó mà không kế thừa cách triển khai hiện có từ Listenable. A sai vì implements không sao chép mã; C sai vì có mối quan hệ rõ ràng qua implements; D sai vì đây là cú pháp Dart hợp lệ."},"PRM-013":{"q":"Theo đề xuất chung, `BottomNavigationBar` ứng dụng phù hợp nhất với bao nhiêu tab điều hướng chính?","options":["1 tab","2-5 tab","10-15 tab","Không có giới hạn về số lượng"],"exp":"BottomNavigationBar phù hợp nhất với 2-5 tab cho mỗi đề xuất chung. A, C, D không khớp với số được đề xuất."},"PRM-014":{"q":"Theo phần “Sử dụng điểm dừng” trong bài giảng, quy tắc phân chia bố cục dựa trên chiều rộng được đề xuất là gì?","options":["< 400px: Nhỏ, 400-800px: Trung bình, > 800px: Lớn","< 100px: Nhỏ, 100-300px: Trung bình, > 300px: Lớn","Chỉ có 2 cấp độ: Mobile và Desktop, không có trình độ trung cấp","Điểm dừng luôn được cố định ở 1024px trong mọi trường hợp"],"exp":"Quy tắc điểm dừng được đề xuất: <400px Nhỏ, 400-800px Trung bình, >800px Lớn --- khớp với trang trình bày. B, C, D không trùng với số đã nêu."},"PRM-015":{"q":"`AutovalidateMode` có ba chế độ: `disabled`, `always` và `onUserInteraction`. Theo bài giảng, chế độ nào được khuyến khích và tại sao?","options":["`always` --- vì hiện lỗi ngay giúp người dùng cẩn thận hơn","`disabled` --- vì không bao giờ hiển thị lỗi sẽ giữ cho UI always luôn sạch sẽ","`onUserInteraction` --- vì nó tránh hiển thị lỗi màu đỏ ngay từ start (khó chịu) trong khi vẫn phản hồi kịp thời khi người dùng bắt đầu tương tác với trường đó, cân bằng \"quá sớm\" và \"quá muộn\"","Không có chế độ nào được khuyến nghị, nó tùy ý"],"exp":"`onUserInteraction` được khuyên dùng vì nó cân bằng giữa việc không hiển thị lỗi quá early (khó chịu) và không quá late (khó hiểu). A, B, D không phù hợp với chế độ/lý do được đề xuất."},"PRM-016":{"q":"Theo phần \"Thông báo lỗi & UX\", thông báo lỗi nào sau đây là ví dụ UX TỐT?","options":["ERROR_400_INVALID_FIELD","Nhập email hợp lệ","Không hợp lệ!!!","Đã xảy ra lỗi ở đâu đó"],"exp":"Nhập email hợp lệ\" là một ví dụ UX tốt: ngắn gọn, rõ ràng, cụ thể. A, C, D tệ examples (mã lỗi kỹ thuật, mơ hồ, không cụ thể)."},"PRM-017":{"q":"Xác thực Firebase mang lại lợi ích chính gì khi xây dựng hệ thống xác thực của riêng bạn từ đầu?","options":["Nó yêu cầu viết một chương trình phụ trợ tùy chỉnh phức tạp hơn","Cung cấp giải pháp đăng nhập an toàn, có thể mở rộng, hỗ trợ nhiều methods (Google, Apple, Facebook, Email/Mật khẩu) cùng với khả năng duy trì phiên tự động và làm mới mã thông báo, giảm nỗ lực xây dựng chương trình phụ trợ nhận dạng","Chỉ hoạt động với các ứng dụng không cần đăng nhập","Không tương thích với Flutter"],"exp":"Firebase Auth cung cấp khả năng đăng nhập đa phương thức, an toàn, có thể mở rộng với khả năng duy trì/làm mới phiên tự động, giảm nỗ lực nhận dạng phụ trợ. A, C, D không khớp với lợi ích thực sự của Xác thực Firebase."},"PRM-018":{"q":"Trong luồng Đăng nhập bằng Google: \"Người dùng nhấn vào Đăng nhập bằng Google → Trình chọn tài khoản Google → Google phát hành mã thông báo OAuth → Chuyển đổi sang thông tin xác thực Firebase → Dấu hiệu Firebase trong người dùng → Ứng dụng nhận được đối tượng Người dùng Firebase.\" Ý nghĩa cốt lõi của câu lệnh \"Firebase xử lý danh tính → ứng dụng của chúng tôi chỉ xử lý UI + điều hướng\" là gì?","options":["Ứng dụng Flutter phải tự viết tất cả logic xác thực OAuth từ đầu","Firebase xử lý tất cả các phần phức tạp của xác minh danh tính và quản lý mã thông báo OAuth; nhà phát triển Flutter chỉ cần tập trung vào việc xây dựng UI và xử lý điều hướng sau khi đăng nhập thành công","Đăng nhập bằng Google hoàn toàn không liên quan đến Firebase","UI và điều hướng phải được xử lý hoàn toàn ở phía máy chủ"],"exp":"Firebase xử lý tất cả xác minh danh tính/OAuth phức tạp, cho phép nhà phát triển Flutter chỉ tập trung vào UI và điều hướng. A, C, D không phù hợp với ý nghĩa của câu này."},"PRM-019":{"q":"Theo phần \"Tìm hiểu phiên của người dùng\", một phiên thông thường thường bao gồm những thành phần nào?","options":["Chỉ có mật khẩu của người dùng","Mã thông báo truy cập, thông tin profile của người dùng và dấu thời gian hết hạn của mã thông báo","Chỉ tên ứng dụng và phiên bản Flutter","Toàn bộ lịch sử thao tác của người dùng trên thiết bị"],"exp":"Một phiên thông thường bao gồm: mã thông báo truy cập, người dùng profile và dấu thời gian hết hạn mã thông báo. A, C, D chưa đầy đủ/sai về nội dung phần \"Tìm hiểu phiên người dùng."},"PRM-020":{"q":"Ngôn ngữ nào chủ yếu được sử dụng để viết ứng dụng Flutter?","options":["Dart","Kotlin","JavaScript","Swift"],"exp":"Tùy chọn A đúng: Dart. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-021":{"q":"Tại sao Flutter đặc biệt phù hợp với MVP và công ty khởi nghiệp?","options":["Nó chỉ chạy trên các thiết bị cao cấp","Nó yêu cầu hai cơ sở mã riêng biệt","Nó loại bỏ sự cần thiết phải thử nghiệm","Nó rút ngắn thời gian tiếp thị và duy trì một cơ sở mã"],"exp":"Tùy chọn D đúng: Nó rút ngắn thời gian tiếp thị và duy trì một cơ sở mã. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-022":{"q":"Trong mô hình tích hợp Flutter-và gốc, phần nào thường được Flutter xử lý?","options":["UI và logic nghiệp vụ","Hạt nhân của hệ điều hành","Biên soạn trình điều khiển","Phần mềm thiết bị"],"exp":"Tùy chọn A đúng: UI và logic nghiệp vụ. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-023":{"q":"Lớp Công cụ Flutter chủ yếu được viết bằng ngôn ngữ nào?","options":["Dart","Kotlin","Mục tiêu-C","C++"],"exp":"Lựa chọn D đúng: C++. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-024":{"q":"Dart kết hợp hai phương pháp biên dịch nào?","options":["JIT và AOT","SQL và NoSQL","HTML và CSS","JVM và CLR"],"exp":"Tùy chọn A đúng: JIT và AOT. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-025":{"q":"Mọi chương trình Dart đều bắt đầu thực thi từ hàm nào?","options":["run()","start()","init()","main()"],"exp":"Tùy chọn D đúng: main(). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-026":{"q":"Hàm nào in một dòng ra bảng điều khiển trong Dart?","options":["print()","console.log()","echo()","Java của println()"],"exp":"Tùy chọn A đúng: print(). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-027":{"q":"Loại Dart nào được sử dụng cho số nguyên?","options":["bool","String","int","double"],"exp":"Tùy chọn C đúng: int. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-028":{"q":"Loại Dart nào được sử dụng cho số phân số?","options":["Never","Set","int","double"],"exp":"Tùy chọn D đúng: double. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-029":{"q":"Kiểu dữ liệu nào đại diện cho một bộ sưu tập có thứ tự?","options":["List","enum","Map","Set"],"exp":"Tùy chọn A đúng: List. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-030":{"q":"Toán tử logic AND trong Dart là gì?","options":["!","\\|\\|","&&","??"],"exp":"Lựa chọn C đúng: &&. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-031":{"q":"Theo ví dụ về trang trình bày, điểm khác biệt chính giữa động và var là gì?","options":["dynamic được phân giải trong thời gian chạy và có thể chứa các giá trị thuộc nhiều loại khác nhau","dynamic luôn là số nguyên","dynamic là một hằng số","dynamic không thể được gán giá trị"],"exp":"Tùy chọn A đúng: dynamic được giải quyết trong thời gian chạy và có thể chứa các giá trị thuộc các loại khác nhau. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-032":{"q":"Khi nào final thích hợp?","options":["Khi hàm không trả về giá trị","Khi giá trị phải được biết tại thời điểm biên dịch","Khi một biến phải liên tục thay đổi loại","Khi một giá trị được gán một lần nhưng có thể được xác định khi chạy"],"exp":"Tùy chọn D đúng: Khi một giá trị được gán một lần nhưng có thể được xác định khi chạy. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-033":{"q":"Trong lập trình hướng đối tượng, đối tượng là gì?","options":["Một nhà điều hành","Một tập tin cấu hình","Một loại vòng lặp","Một thể hiện của một lớp"],"exp":"Tùy chọn D đúng: Một thể hiện của một lớp. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-034":{"q":"cái gì vậy?? toán tử thường được sử dụng để đảm bảo an toàn không?","options":["Cung cấp giá trị dự phòng khi phía bên trái là null","Khẳng định rằng một giá trị chắc chắn là không null","Khai báo một biến null","So sánh hai số"],"exp":"Tùy chọn A đúng: Cung cấp giá trị dự phòng khi phía bên trái rỗng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-035":{"q":"Khi một lớp sử dụng dụng cụ, nó phải làm gì?","options":["Có đầy đủ override thành viên giao diện được yêu cầu","Được tuyên bố là trừu tượng","Chỉ sử dụng một phương pháp","Kế thừa tất cả các hành vi hiện có mà không cần viết lại nó"],"exp":"Tùy chọn A đúng: Có đầy đủ override thành viên giao diện được yêu cầu. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-036":{"q":"Một học sinh tạo một emulator trên một PC có cấu hình thấp. Theo đề xuất của bài giảng, cấu hình emulator nào phù hợp hơn để giảm tải cho máy?","options":["Pixel 8, API 33+","Pixel 3a, API 30","Máy tính bảng Pixel, API 34","Pixel Fold, API 35"],"exp":"Bài giảng khuyên dùng Pixel 3a / API 30 cho các máy có cấu hình thấp. A, C, D là cấu hình nặng hơn, không phù hợp với máy yếu."},"PRM-037":{"q":"DartPad khác với VS Code/Android Studio khi phát triển Flutter như thế nào?","options":["DartPad yêu cầu cài đặt SDK đầy đủ giống như Android Studio","DartPad là môi trường trực tuyến, không cần cài đặt và chạy trực tiếp trong trình duyệt","DartPad không hỗ trợ các widgets cơ bản như Văn bản, Cột","DartPad chỉ có thể được sử dụng cho ngôn ngữ Kotlin"],"exp":"DartPad là môi trường trực tuyến không cần cài đặt. A sai vì DartPad không cần SDK đầy đủ; C sai vì DartPad hỗ trợ Văn bản, Cột; D sai vì đây là Dart/Flutter, không phải Kotlin."},"PRM-038":{"q":"Trong ví dụ 'Hello World' chạy trên ba environments (DartPad, VS Code, Android Studio), điểm chung quan trọng nhất được nhấn mạnh là gì?","options":["Mỗi môi trường sử dụng một ngôn ngữ lập trình khác nhau","Tất cả công cụ biên dịch về cùng thời gian chạy Flutter, tạo ra kết quả giống nhau","Chỉ Android Studio mới có thể chạy ứng dụng thực","DartPad không thể hiển thị TextStyle"],"exp":"Điểm chung chính: tất cả các công cụ biên dịch theo cùng một thời gian chạy Flutter, cho kết quả giống hệt nhau trên DartPad/VS Code/Android Studio. A, C, D đều sai trong bài giảng."},"PRM-039":{"q":"Theo bài giảng, macOS cần công cụ gì để xây dựng ứng dụng Flutter cho iOS?","options":["Android Studio","Xcode","Studio trực quan","Ý tưởng IntelliJ"],"exp":"macOS cần Xcode để xây dựng cho iOS, theo ghi chú 'macOS người dùng cần Xcode cho các bản dựng iOS.' A, C, D không phải là công cụ được nêu cho mục đích này."},"PRM-040":{"q":"So sánh `TimePicker` (`showTimePicker`) và `DatePicker` (`showDatePicker`) trong bối cảnh xây dựng quy trình đăng ký kết hợp cả ngày và giờ: cách tiếp cận chính xác cho mỗi bài giảng là gì?","options":["Chỉ gọi một trong hai, Flutter sẽ tự động suy ra giá trị còn lại","Gọi hai hàm async riêng biệt sequentially (`pickDate()` và `pickTime()`), lưu trữ kết quả trong hai State variables (`DateTime? d`, `TimeOfDay? t` riêng biệt), sau đó hiển thị chúng kết hợp trong UI","Sử dụng một `DateTimePicker` widget tích hợp sẵn trong Flutter SDK","Không thể kết hợp DatePicker và TimePicker trên cùng một màn hình"],"exp":"Gọi `pickDate()` và `pickTime()` theo tuần tự, lưu trữ kết quả trong hai biến State riêng biệt, sau đó hiển thị kết hợp --- phù hợp với cách tiếp cận của bản demo Đặt trước. A, C, D không phản ánh việc thực hiện được dạy."},"PRM-041":{"q":"Đưa ra: ElevatedButton( onPressed: () { Navigator.push( context, MaterialPageRoute(builder: (_) => SecondPage()), ); }, child: Text('Go to Second Page'), ) Theo lời giải thích của bài giảng tại sao mã gốc này không chạy trực tiếp trên DartPad, nguyên nhân chính là gì?","options":["DartPad không hỗ trợ ElevatedButton","Thiếu cấu trúc chương trình hoàn chỉnh: DartPad yêu cầu `main()`, `runApp()` và gốc `MaterialApp`; chỉ cung cấp một widget đơn độc như thế này mà không có Navigator context hợp lệ (e.g. SecondPage không xác định hoặc thiếu MaterialApp xung quanh) sẽ gây ra lỗi","Navigator.push chỉ hoạt động trên thiết bị thực chứ không phải trên DartPad","MaterialPageRoute là một API đã bị xóa khỏi Flutter"],"exp":"DartPad cần một structure hoàn chỉnh (main, runApp, MaterialApp); thiếu những thứ này hoặc tham chiếu không xác định classes (như SecondPage) gây ra lỗi. A, C, D không phù hợp với lời giải thích của bài giảng."},"PRM-042":{"q":"Lý do chính khiến \"URL mã hóa cứng ở mọi nơi trong mã\" được liệt kê là một cạm bẫy là gì?","options":["URL được mã hóa cứng khiến ứng dụng chạy chậm hơn đáng kể","Điều này gây khó khăn cho việc thay đổi cơ sở URL (e.g. chuyển đổi môi trường dev/production), dễ dẫn đến lỗi và mã trùng lặp khi phải chỉnh sửa ở nhiều nơi","Dart không cho phép khai báo chuỗi URL trực tiếp trong mã","Chỉ ảnh hưởng đến bảo mật, không liên quan đến bảo trì mã"],"exp":"Các URL được mã hóa cứng khiến việc thay đổi URL cơ sở trở nên khó khăn và gây ra sự trùng lặp/lỗi trên cơ sở mã. A, C, D không phù hợp với lý do thực tế đã nêu."},"PRM-043":{"q":"Với mã FakePrefs này mô phỏng SharedPreferences trong DartPad: class FakePrefs { static final Map<String, Object> _store = {}; Future`<void>` setBool(String key, bool value) async { _store[key] = value; } bool getBool(String key) { final value = _store[key]; if (value is bool) return value; return false; } } Tại sao `_store` được khai báo là `static`?","options":["Để giới hạn ứng dụng chỉ có một đối tượng FakePrefs hiện có","Vì vậy, dữ liệu được lưu trữ is được chia sẻ trên tất cả các phiên bản của FakePrefs (bắt chước hành vi đơn lẻ của SharedPreferences thực), thay vì mỗi phiên bản có bản sao dữ liệu riêng","`static` không có hiệu lực trong ngữ cảnh này","Để tự động lưu dữ liệu vĩnh viễn ngay cả sau khi đóng ứng dụng is"],"exp":"`static` làm cho dữ liệu được lưu trữ được chia sẻ trên tất cả các phiên bản FakePrefs, bắt chước hành vi đơn lẻ của SharedPreferences' thực tế. A, C, D không khớp với vai trò thực tế của static ở đây."},"PRM-044":{"q":"Ghi chú trang trình bày \"Lưu ý: đặt lại dữ liệu trên reload (không liên tục)\" khi sử dụng FakePrefs trên DartPad gợi ý về hạn chế nào?","options":["Dữ liệu được lưu trữ trong FakePrefs sẽ tồn tại mãi mãi ngay cả sau khi tải lại trang","Vì FakePrefs chỉ lưu trữ dữ liệu trong RAM của phiên hiện tại nên dữ liệu sẽ bị mất khi khởi động lại nóng hoặc tải lại trang --- không giống như SharedPreferences thực, tồn tại lâu dài trên thiết bị","FakePrefs chỉ hoạt động với kiểu dữ liệu String","Đây là lỗi Flutter cần được vá"],"exp":"FakePrefs chỉ lưu trữ dữ liệu trong bộ nhớ cho phiên hiện tại, do đó dữ liệu sẽ bị mất khi khởi động lại/tải lại nóng, không giống như SharedPreferences thực sự bền bỉ. A, C, D không phù hợp với giới hạn đã nêu này."},"PRM-045":{"q":"Trong Luồng xác thực cấp cao, sau khi phần phụ trợ xác minh thông tin đăng nhập hợp lệ, hệ thống thường quay lại ứng dụng những gì?","options":["Mật khẩu của người dùng ở dạng mã hóa","token (thường là JWT) để ứng dụng lưu trữ và sử dụng cho các yêu cầu tiếp theo","Toàn bộ cơ sở dữ liệu người dùng","Danh sách các ứng dụng khác mà người dùng đã cài đặt"],"exp":"Phần phụ trợ trả về token (thường là JWT) để ứng dụng lưu trữ và sử dụng cho các yêu cầu tiếp theo. A, C, D không khớp với quy trình xác thực tiêu chuẩn."},"PRM-046":{"q":"Trong Bản demo 10.5, thông báo cục bộ được kích hoạt tại thời điểm nào trong quy trình thực tế của ứng dụng?","options":["Ngay khi mở ứng dụng, trước khi đăng nhập","Ngay sau khi đăng nhập thành công","Chỉ khi ứng dụng chạy hoàn toàn ở chế độ nền","Khi ứng dụng được gỡ cài đặt"],"exp":"Thông báo cục bộ được kích hoạt ngay sau khi đăng nhập thành công, theo Bản demo 10.5. A, C, D không khớp với luồng thực được mô tả."},"PRM-047":{"q":"Mô tả nào xác định rõ nhất Flutter?","options":["Bộ công cụ UI của Google để xây dựng các ứng dụng được biên dịch nguyên bản từ một cơ sở mã duy nhất","Ngôn ngữ lập trình thay thế hoàn toàn Dart","Một Android emulator","Hệ thống quản lý cơ sở dữ liệu của Google"],"exp":"Tùy chọn A đúng: Bộ công cụ UI của Google để xây dựng các ứng dụng được biên dịch nguyên bản từ một cơ sở mã duy nhất. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-048":{"q":"Mẫu Repository tách biệt với mẫu UI là gì?","options":["Android emulator","Truy cập dữ liệu, API và logic cơ sở dữ liệu","Màu sắc dữ liệu chủ đề","Bố cục hàng và cột"],"exp":"Tùy chọn B đúng: Truy cập dữ liệu, API và logic cơ sở dữ liệu. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-049":{"q":"setState() làm gì?","options":["Thông báo cho khung để xây dựng lại State UI có liên quan","Chạy flutter doctor","Tạo di chuyển cơ sở dữ liệu","Lưu trữ mã thông báo trên máy chủ"],"exp":"Tùy chọn A đúng: Thông báo cho khung để xây dựng lại State UI có liên quan. Đây là khái niệm quản lý state: các thay đổi state phải thông báo hoặc kích hoạt phần có liên quan của UI để xây dựng lại."},"PRM-050":{"q":"Tại sao DartPad không thể sử dụng SharedPreferences plugin thực sự?","options":["Môi trường của nó không cung cấp hỗ trợ gốc plugin hoặc lưu trữ liên tục","Nó yêu cầu JWT","SharedPreferences chỉ hoạt động trên iOS","DartPad chỉ chạy Java"],"exp":"Tùy chọn A đúng: Môi trường của nó không cung cấp hỗ trợ gốc plugin hoặc lưu trữ liên tục. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-051":{"q":"FakePrefs trong DartPad lưu trữ dữ liệu ở đâu?","options":["Một tập tin cơ sở dữ liệu thực","Lưu trữ an toàn","Một máy chủ đám mây","Map trong bộ nhớ sẽ đặt lại khi tải lại"],"exp":"Tùy chọn D đúng: Map trong bộ nhớ sẽ đặt lại khi tải lại. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-052":{"q":"Mã thông báo truy cập thường được sử dụng như thế nào?","options":["Để lưu trữ mật khẩu","Để tạo chủ đề UI","Chỉ một lần trong quá trình cài đặt ứng dụng","Nó được gửi cùng với mọi yêu cầu API yêu cầu xác thực"],"exp":"Tùy chọn D đúng: Nó được gửi cùng với mọi yêu cầu API yêu cầu xác thực. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-053":{"q":"Nên sử dụng chế độ nào để đo hiệu suất chính xác hơn?","options":["Chỉ chế độ kiểm tra","Chế độ gỡ lỗi","chế độ DartPad","Chế độ hồ sơ"],"exp":"Tùy chọn D đúng: Chế độ hồ sơ. Hiệu suất Flutter phải được đánh giá ở chế độ profile, tốt nhất là trên thiết bị vật lý vì thời gian ở chế độ debug không mang tính đại diện."},"PRM-054":{"q":"ListView.builder là tốt nhất cho?","options":["Một danh sách cố định nhỏ","Danh sách lớn hoặc dynamic","Hình ảnh tĩnh","Thiết lập chủ đề"],"exp":"Tùy chọn B đúng: Danh sách lớn hoặc dynamic. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-055":{"q":"Lệnh nào kiểm tra thiết lập môi trường?","options":["flutter doctor","flutter inspect","flutter env","flutter config"],"exp":"Tùy chọn A đúng: flutter doctor. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-056":{"q":"Lệnh nào liệt kê các thiết bị được kết nối?","options":["flutter devices","flutter emulators","flutter targets","flutter doctor"],"exp":"Tùy chọn A đúng: flutter devices. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-057":{"q":"Lệnh nào hiển thị các trình mô phỏng có sẵn?","options":["flutter devices","flutter emulators","flutter doctor","flutter list"],"exp":"Tùy chọn B đúng: flutter emulators. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-058":{"q":"Mục đích của pub.dev là gì?","options":["kho lưu trữ Flutter package","Thiết bị emulator","Công cụ kết xuất","IDE đám mây"],"exp":"Tùy chọn A đúng: kho lưu trữ Flutter package. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-059":{"q":"Công cụ nào được sử dụng để kiểm tra cây và hiệu suất widget?","options":["Flutter DevTools","Android Sơn","Chỉ tổ chức Xcode","Thanh tra quán rượu"],"exp":"Lựa chọn A đúng: Flutter DevTools. Hiệu suất Flutter phải được đánh giá ở chế độ profile, tốt nhất là trên thiết bị vật lý vì thời gian ở chế độ debug không mang tính đại diện."},"PRM-060":{"q":"Môi trường phát triển nào được mô tả là trình soạn thảo trực tuyến lý tưởng để trình diễn nhanh và học cú pháp mà không cần cài đặt?","options":["Mã VS","Android Studio","DartPad","Xcode"],"exp":"Tùy chọn C đúng: DartPad. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-061":{"q":"Nhà phát triển nên sử dụng lệnh nào để xác minh cài đặt Flutter và xem bản tóm tắt về trạng thái môi trường?","options":["flutter run","flutter create","flutter doctor","flutter build"],"exp":"Tùy chọn C đúng: flutter doctor. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-062":{"q":"Khi nào nhà phát triển nên chọn sử dụng JSON files cục bộ (dart:io) thay vì SharedPreferences?","options":["Khi lưu trữ một boolean duy nhất cho chế độ tối.","Khi dữ liệu lớn hơn các cặp khóa-giá trị đơn giản hoặc cần được xuất/nhập.","Khi ứng dụng yêu cầu dữ liệu quan hệ phức tạp với tính năng sắp xếp và lọc.","Chỉ khi ứng dụng đang chạy trong môi trường DartPad."],"exp":"Tùy chọn B đúng: Khi dữ liệu lớn hơn các cặp khóa-giá trị đơn giản hoặc cần được xuất/nhập.. Câu trả lời khớp với hành vi loại hệ thống hoặc an toàn rỗng của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-063":{"q":"Trong quá trình thiết lập SQFlite, phương pháp nào được sử dụng để xác định cấu trúc bảng ban đầu khi cơ sở dữ liệu được tạo lần đầu tiên?","options":["openDatabase()","onCreate","insert()","query()"],"exp":"Tùy chọn B đúng: onCreate. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-064":{"q":"Trong dự án Flutter, tệp nào là điểm truy cập của ứng dụng?","options":["pubspec.yaml","lib/main.dart","android/build.gradle","web/index.html"],"exp":"`lib/main.dart` là điểm vào, như đã nêu trong bảng cấu trúc dự án. A là tệp cấu hình phụ thuộc; C, D là các tệp cấu hình nền tảng, không phải điểm vào."},"PRM-065":{"q":"Hãy xem đoạn mã sau đang chạy trong main.dart: import 'package:flutter/material.dart'; void main() => runApp(const MaterialApp( home: Scaffold( body: Center( child: Text('Hello, World', style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold)), ), ), )); Nếu từ khóa `const` trước `MaterialApp` bị xóa, điều gì sẽ xảy ra với hành vi của ứng dụng?","options":["Ứng dụng sẽ không biên dịch được ngay lập tức","Ứng dụng vẫn chạy chính xác, chỉ mất lợi ích tối ưu hóa hiệu suất vì Flutter không thể sử dụng lại cùng một phiên bản widget bất biến","Text sẽ không hiển thị \"Hello, World","Sau này Scaffold sẽ không thể có AppBar nữa"],"exp":"`const` giúp Flutter tối ưu hóa việc phân biệt cây; gỡ bỏ nó vẫn chạy chính xác nhưng làm mất đi lợi ích hiệu suất đó. A sai vì nó không gây ra lỗi biên dịch; C sai vì Text vẫn hiển thị bình thường; D không liên quan."},"PRM-066":{"q":"Người hướng dẫn tạo dự án Flutter mới với ID tổ chức `com.fptu.movies` và tên dự án `movies`. Mục đích chính của ID tổ chức trong quá trình tạo dự án là gì?","options":["Chỉ dùng để đặt tên hiển thị trên màn hình chính của thiết bị","Xác định tên/giá trị nhận dạng gói package duy nhất cho ứng dụng khi được đóng gói cho Android/iOS","Không có tác dụng thực sự, chỉ mang tính minh họa","Được sử dụng để đặt chủ đề màu của ứng dụng"],"exp":"ID tổ chức xác định tên/số nhận dạng gói package duy nhất khi đóng gói ứng dụng. A, C, D mô tả sai vai trò kỹ thuật của nó."},"PRM-067":{"q":"Bài giảng có đoạn này: Widget tile(String t, String s) => Card( margin: const EdgeInsets.symmetric(vertical: 6), child: ListTile(title: Text(t), subtitle: Text(s)), ); Lợi ích chính của việc trích xuất UI lặp lại thành một hàm riêng biệt/widget như `tile()`, theo tinh thần \"Mọi thứ đều là một Widget\"?","options":["Làm cho Flutter chạy nhanh hơn về mặt CPU tuyệt đối","Tái sử dụng và sắp xếp UI thành blocks (khối LEGO), làm cho mã dễ đọc hơn, dễ bảo trì hơn và nhất quán về khoảng cách","Đây là điều bắt buộc nếu không Flutter sẽ báo lỗi","Không có lợi ích thực sự, chỉ là một phong cách mã hóa"],"exp":"Việc trích xuất các khối UI lặp lại sẽ hỗ trợ việc tái sử dụng, tổ chức, khả năng đọc, khả năng bảo trì và tính nhất quán về khoảng cách. A, C, D không phù hợp với lợi ích thực tế đã nêu."},"PRM-068":{"q":"Sự khác biệt giữa `Image.network` và `Image.asset` là gì?","options":["`Image.network` tải hình ảnh từ một URL trên internet, `Image.asset` tải một gói hình ảnh trong project (được khai báo trong pubspec.yaml)","Cả hai chỉ tải hình ảnh từ bộ nhớ cục bộ","`Image.asset` chỉ hoạt động trên Web","`Image.network` không hỗ trợ BoxFit"],"exp":"`Image.network` tải từ một URL, `Image.asset` tải các hình ảnh dự án được nhóm. B, C, D mô tả sai hai chức năng của hình ảnh widgets'."},"PRM-069":{"q":"Trong cấu hình Android deep link, đoạn mã XML sau thuộc về đâu và nó có ý nghĩa gì? `<intent-filter>` `<action android:name=\"android.intent.action.VIEW\" />` `<category android:name=\"android.intent.category.DEFAULT\" />` `<category android:name=\"android.intent.category.BROWSABLE\" />` `<data android:scheme=\"movieapps\" android:host=\"movies\" />` `</intent-filter>`","options":["Trong `pubspec.yaml`, dùng để khai báo phần phụ thuộc","Trong `AndroidManifest.xml`, khai báo intent-filter để hệ điều hành Android nhận dạng và định tuyến các liên kết như `movieapps://movies` tới đúng ứng dụng","Trong `main.dart`, được sử dụng để xác định tuyến đường Flutter","Ở `Info.plist`, chỉ áp dụng cho iOS"],"exp":"Đoạn mã này thuộc về `AndroidManifest.xml`, khai báo intent-filter để Android định tuyến các liên kết phù hợp tới ứng dụng này. A, C, D là vị trí tệp sai."},"PRM-070":{"q":"Trên iOS, để hỗ trợ URL tùy chỉnh scheme (e.g. `movieapps://`), cần thêm cấu hình ở đâu?","options":["AndroidManifest.xml","build.gradle","Info.plist (thêm Loại URL → Lược đồ URL)","pubspec.yaml"],"exp":"Cấu hình lược đồ URL tùy chỉnh trên iOS nằm trong Info.plist (Loại URL → Lược đồ URL). A, B, D không phải là vị trí chính xác cho cấu hình này."},"PRM-071":{"q":"So sánh việc sử dụng `http` package đơn giản với quản lý HTTP nâng cao hơn package (e.g. Dio, không có trong các trang trình bày nhưng có thể hỏi được ở cấp độ phân tích): theo tinh thần \"Mẫu lớp dịch vụ\" của Mô-đun 8, tại sao việc gói logic HTTP trong `ApiService` lại giúp việc chuyển đổi các thư viện HTTP later (nếu cần) dễ dàng hơn?","options":["Bởi vì mọi HTTP package đều có một API hoàn toàn giống nhau","Bởi vì tất cả logic mạng được tách biệt trong một lớp duy nhất; nếu thư viện cần thay đổi, bạn chỉ chỉnh sửa bên trong `ApiService` mà không chạm vào mọi widget tiêu thụ dữ liệu, giảm thiểu rủi ro và công sức","Không có lợi ích gì cả, việc chuyển đổi thư viện luôn yêu cầu viết lại toàn bộ ứng dụng","Mẫu lớp dịch vụ chỉ áp dụng cho `http` package, không áp dụng cho các gói khác"],"exp":"Việc tách biệt logic mạng trong một lớp có nghĩa là việc chuyển đổi thư viện chỉ yêu cầu chỉnh sửa ApiService chứ không phải tiêu tốn hết widget, giảm thiểu rủi ro/công sức. A, C, D không phù hợp với nguyên tắc kiến ​​trúc phần mềm này."},"PRM-072":{"q":"package nào được đề cập để xác định thư mục lưu trữ của ứng dụng khi làm việc với các tệp JSON cục bộ?","options":["shared_preferences","path_provider","sqflite","http"],"exp":"`path_provider` được sử dụng để xác định thư mục lưu trữ ứng dụng cho các tệp JSON cục bộ. A, C, D không phải là package cho mục đích này."},"PRM-073":{"q":"Theo bảng \"Lỗi thường gặp và cách sửa lỗi\" khi đăng nhập vào Google, \"DEVELOPER_ERROR\" thường do nguyên nhân gì?","options":["Thiếu kết nối Internet","Tên package sai không khớp với cấu hình Firebase","Thiếu tệp pubspec.yaml","Phiên bản Flutter quá mới"],"exp":"DEVELOPER_ERROR\" thường do tên package sai không khớp với cấu hình Firebase. A, C, D không khớp với nguyên nhân chung đã nêu."},"PRM-074":{"q":"Trong `flutter_bloc` package, mối quan hệ luồng dữ liệu chính xác giữa Sự kiện, Bloc và State là gì?","options":["State → Bloc → Sự kiện","UI gửi Sự kiện vào các quy trình Bloc → Bloc và ánh xạ Sự kiện vào một State → Bloc mới phát ra State → UI lắng nghe State để xây dựng lại","Sự kiện và State là cùng một khái niệm, có thể hoán đổi cho nhau","Bloc chỉ nhận được State, không nhận được Sự kiện"],"exp":"Luồng chính xác: UI gửi Sự kiện → Bloc quy trình/bản đồ tới State mới → phát ra State → UI lắng nghe và xây dựng lại. A đảo ngược điều này; C, D mô tả sai mối quan hệ giữa Sự kiện/State/Bloc."},"PRM-075":{"q":"`Cubit` trong `flutter_bloc` package khác với `Bloc` truyền thống như thế nào?","options":["Cubit không thể quản lý state, chỉ Bloc mới có thể","Cubit là phiên bản đơn giản hóa của Bloc --- nó không cần xác định lớp Sự kiện riêng biệt, thay vào đó gọi trực tiếp các phương thức để phát ra các Trạng thái mới, giảm bản mẫu so với một Bloc đầy đủ","Cubit chỉ hoạt động với dữ liệu int","Cubit và Bloc hoàn toàn giống nhau ở API, không có sự khác biệt"],"exp":"Cubit là một Bloc được đơn giản hóa --- không cần lớp Sự kiện riêng biệt, các phương thức trực tiếp phát ra State mới, giảm bớt bản soạn sẵn. A, C, D mô tả sai đặc điểm của Cubit."},"PRM-076":{"q":"Tệp nào khai báo các phần phụ thuộc và nội dung của dự án Flutter?","options":["chỉ build.gradle.kts","package.json","settings.xml","pubspec.yaml"],"exp":"Tùy chọn D đúng: pubspec.yaml. pubspec.yaml là tệp kê khai dự án dùng để khai báo các gói và cấu hình nội dung."},"PRM-077":{"q":"Trên Android, phần tử nào thường được sử dụng để định cấu hình deep links?","options":["Dữ liệu chủ đề trong main.dart","Trình kích hoạt SQLite","Bộ lọc ý định trong AndroidManifest","pubspec.lock"],"exp":"Tùy chọn C là chính xác: Bộ lọc ý định trong AndroidManifest. API điều hướng Flutter quản lý quá trình chuyển đổi tuyến đường hoặc ánh xạ thông tin URL/tuyến đường đến tới ứng dụng state, tùy thuộc vào API được sử dụng."},"PRM-078":{"q":"DEVELOPER_ERROR thường liên quan đến điều gì?","options":["Câu lệnh SELECT SQL không chính xác","Tên package hoặc cấu hình Firebase không chính xác","Thiếu Khu vực an toàn","Thiếu ListView"],"exp":"Tùy chọn B đúng: Tên package hoặc cấu hình Firebase không chính xác. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-079":{"q":"CPU Profiler giúp xác định điều gì?","options":["Tên Firebase package","Một notch màn hình","Điểm nóng tại thời điểm thực thi","Văn bản lỗi biểu mẫu"],"exp":"Tùy chọn C đúng: Điểm nóng tại thời điểm thực thi. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-080":{"q":"Vòng lặp for-in chủ yếu được sử dụng để làm gì?","options":["Arithmetic","Lặp lại bộ sưu tập","Đang tạo widgets","Nhập gói"],"exp":"Tùy chọn B đúng: Lặp lại các bộ sưu tập. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-081":{"q":"Một lớp định nghĩa?","options":["Một vòng lặp","Một cấu trúc hoặc bản thiết kế","Một package","Nhập khẩu"],"exp":"Lựa chọn B đúng: Một công trình hoặc bản thiết kế. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-082":{"q":"pubspec.yaml dùng để làm gì?","options":["Ảnh chụp màn hình ứng dụng","Sự phụ thuộc và tài sản","SQL bảng","Cây định tuyến"],"exp":"Tùy chọn B đúng: Phụ thuộc và tài sản. pubspec.yaml là tệp kê khai dự án dùng để khai báo các gói và cấu hình nội dung."},"PRM-083":{"q":"Tài sản có phải kê khai?","options":["main.dart","pubspec.yaml","analysis_options.yaml","androidmanifest.xml"],"exp":"Tùy chọn B đúng: pubspec.yaml. pubspec.yaml là tệp kê khai dự án dùng để khai báo các gói và cấu hình nội dung."},"PRM-084":{"q":"Lệnh nào tìm nạp các phần phụ thuộc Flutter?","options":["flutter add","flutter get","flutter pub get","dart fetch"],"exp":"Tùy chọn C đúng: flutter pub get. pubspec.yaml is the project manifest used to declare packages and asset configuration."},"PRM-085":{"q":"Lệnh nào tạo dự án Flutter mới?","options":["flutter new","flutter create","dart create flutter","flutter init"],"exp":"Tùy chọn B đúng: flutter create. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-086":{"q":"Lệnh nào chạy ứng dụng Flutter?","options":["flutter go","flutter start","flutter run","dart run ui"],"exp":"Tùy chọn C đúng: flutter run. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-087":{"q":"Lệnh nào dọn sạch thư mục bản dựng?","options":["flutter purge","flutter clear","flutter clean","flutter remove"],"exp":"Tùy chọn C đúng: flutter clean. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-088":{"q":"Lệnh nào xây dựng ứng dụng iOS?","options":["flutter build ios","flutter ios build","flutter make ios","dart build ios"],"exp":"Tùy chọn A đúng: flutter build ios. Flutter supports multiple deployment targets, mặc dù mỗi mục tiêu có thể có SDK, yêu cầu về công cụ và tích hợp nền tảng riêng."},"PRM-089":{"q":"package nào phổ biến cho việc quản lý state đơn giản?","options":["Provider","SQL","HttpClient","Lint"],"exp":"Tùy chọn A đúng: Provider. Đây là khái niệm quản lý state: các thay đổi state phải thông báo hoặc kích hoạt phần có liên quan của UI để xây dựng lại."},"PRM-090":{"q":"package nào thường được sử dụng cho các yêu cầu HTTP?","options":["path","async","http","test"],"exp":"Tùy chọn C đúng: http. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-091":{"q":"Phương thức nào gửi yêu cầu GET bằng package:http?","options":["http.load","http.fetch","http.get","http.readall"],"exp":"Tùy chọn C đúng: http.get. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-092":{"q":"package nào được sử dụng rộng rãi để lưu trữ khóa-giá trị cục bộ?","options":["dio","shared_preferences","provider","analyzer"],"exp":"Tùy chọn B đúng: shared_preferences. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-093":{"q":"package nào thường được sử dụng để kết nối mạng mạnh mẽ trong Flutter?","options":["dio","lint","path","test"],"exp":"Tùy chọn A đúng: dio. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-094":{"q":"Lệnh nào chạy thử nghiệm trong Flutter?","options":["flutter test","flutter run test","phi tiêu flutter test","flutter check"],"exp":"Tùy chọn A đúng: flutter test. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-095":{"q":"Tệp nào thường lưu trữ các quy tắc tìm lỗi mã nguồn cho Dart/Flutter?","options":["analysis_options.yaml","pubspec.lock","routes.yaml","build.gradle"],"exp":"Tùy chọn A đúng: analysis_options.yaml. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-096":{"q":"Từ khóa mở rộng được sử dụng để?","options":["Chỉ thực hiện giao diện","Kế thừa từ một lớp","Tạo đối tượng","Nhập package"],"exp":"Tùy chọn B đúng: Kế thừa từ một lớp. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-097":{"q":"Từ khóa thực hiện được sử dụng để?","options":["Buộc thực hiện hợp đồng giao diện","Kéo dài thời gian xây dựng","Gói xuất khẩu","Ẩn thành viên"],"exp":"Tùy chọn A đúng: Buộc thực hiện hợp đồng giao diện. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-098":{"q":"Tệp nào được tạo và thường không được chỉnh sửa thủ công để khóa phụ thuộc?","options":["pubspec.lock","main.dart","analysis_options.yaml","android/ứng dụng/build.gradle"],"exp":"Tùy chọn A đúng: pubspec.lock. pubspec.yaml là tệp kê khai dự án dùng để khai báo các gói và cấu hình nội dung."},"PRM-099":{"q":"Dart sử dụng mô hình biên dịch kết hợp nào để hỗ trợ cả phát triển nhanh và hiệu suất sản xuất được tối ưu hóa?","options":["Chỉ JIT (Đúng lúc)","Chỉ AOT (Trước thời hạn)","Cả JIT (phát triển) và AOT (sản xuất)","Được giải thích thuần túy, không biên soạn"],"exp":"Dart kết hợp JIT (phát triển nhanh, hot reload) và AOT (biên dịch sản xuất hiệu suất cao). A và B state chỉ là một nửa sự thật; D hoàn toàn sai."},"PRM-100":{"q":"Câu nào SAI về lý do chọn Flutter ('Tại sao Flutter')?","options":["Tải lại nóng/Khởi động lại nóng cho phép phát triển nhanh","Cung cấp Chất liệu & Cupertino widgets cho một UI đẹp đẽ","Chỉ có thể chạy trên một nền tảng duy nhất","Hiệu suất gần như bản địa"],"exp":"'Chỉ có thể chạy trên một nền tảng duy nhất' là SAI vì Flutter là chéo-platform (Android, iOS, Web, Máy tính để bàn) --- đây là sức mạnh cốt lõi của Flutter, hoàn toàn trái ngược với tuyên bố 'Tại sao Flutter'. A, B, D đều là những lý do chính đáng được nêu trong bài giảng."},"PRM-101":{"q":"Ngoại lệ tùy chỉnh trong Dart (e.g. `class LoginException implements Exception`) mang lại lợi ích gì khi đưa ra một chuỗi lỗi thông thường?","options":["Không có lợi ích gì, nó chỉ làm tăng thêm độ phức tạp của mã","Cung cấp ngữ cảnh lỗi miền doanh nghiệp cụ thể, giúp debug và xử lý logic ở lớp UI/Repository dễ dàng hơn","Ngoại lệ tùy chỉnh chạy nhanh hơn Chuỗi đơn giản","Ngoại lệ tùy chỉnh chỉ có thể được sử dụng với API bên ngoài, không thể sử dụng nội bộ"],"exp":"Ngoại lệ tùy chỉnh cung cấp ngữ cảnh lỗi miền cụ thể, hỗ trợ gỡ lỗi và xử lý ở lớp UI/Repository. A, C, D không phù hợp với lợi ích thực tế đã nêu."},"PRM-102":{"q":"Theo phần \"Bảo mật\" của Các phương pháp hay nhất, phương pháp nào được khuyến nghị liên quan đến việc lưu trữ mã thông báo?","options":["Lưu trữ mã thông báo dưới dạng văn bản thuần túy công khai trong tệp nhật ký để dễ dàng gỡ lỗi","Không lưu trữ mã thông báo thô một cách không an toàn --- sử dụng cơ chế lưu trữ an toàn và luôn sử dụng HTTPS","Gửi mã thông báo qua kênh HTTP không được mã hóa để tăng tốc độ","Chia sẻ mã thông báo qua phương tiện truyền thông xã hội để đồng bộ hóa trên nhiều thiết bị"],"exp":"Phương pháp được khuyến nghị là lưu trữ an toàn và luôn sử dụng HTTPS, không bao giờ lưu trữ mã thông báo thô một cách không an toàn. A, C, D là các hành vi SAI, trái với hướng dẫn bảo mật được khuyến nghị."},"PRM-103":{"q":"Đặc điểm nào của lỗi tràn UI được mô tả trong Mô-đun 11 khiến lỗi này khó phát hiện nếu bạn chỉ chạy ứng dụng bình thường?","options":["Tràn luôn khiến ứng dụng bị sập ngay lập tức nên rất dễ phát hiện","Lỗi tràn thường không làm hỏng app (không có ngoại lệ dừng chương trình), vì vậy cần có các công cụ như kiểm tra hoặc DevTools để phát hiện chúng, thay vì chỉ dựa vào ứng dụng \"vẫn đang chạy","Tràn chỉ xảy ra trên iOS thiết bị","Tràn tràn luôn được tự động sửa bởi Dart tại thời điểm biên dịch"],"exp":"Lỗi tràn thường không làm hỏng ứng dụng, yêu cầu kiểm tra/DevTools để phát hiện thay vì chỉ quan sát rằng ứng dụng \"vẫn chạy\". A, C, D không phù hợp với đặc tính thực tế của lỗi tràn."},"PRM-104":{"q":"Trong \"Mục tiêu gỡ lỗi trong Flutter\", vấn đề \"Thường xuyên xây dựng lại không cần thiết\" liên quan trực tiếp đến chủ đề nào sẽ được khám phá sâu hơn trong Mô-đun 12?","options":["Đang tạo tệp JSON cục bộ","Tối ưu hóa hiệu suất","Cấu hình liên kết sâu","Đang thiết lập xác thực Firebase"],"exp":"Việc xây dựng lại thường xuyên không cần thiết\" liên quan trực tiếp đến Tối ưu hóa Hiệu suất, được tìm hiểu sâu hơn trong Học phần 12. A, C, D không liên quan đến vấn đề xây dựng lại này."},"PRM-105":{"q":"Khi Flutter không hỗ trợ trực tiếp một tính năng như máy ảnh, Bluetooth hoặc NFC, phương pháp tích hợp nào được khuyến nghị?","options":["Viết mã gốc và kết nối nó thông qua Kênh nền tảng","Chuyển đổi toàn bộ ứng dụng sang HTML","Lưu trữ dữ liệu tính năng trong SharedPreferences","Chỉ sử dụng Widget Thanh tra"],"exp":"Tùy chọn A đúng: Viết mã gốc và kết nối nó thông qua Kênh nền tảng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-106":{"q":"Điểm dừng được sử dụng để làm gì?","options":["Chọn bố cục cho phạm vi kích thước xác định","Mã hóa token","Tạm dừng trình gỡ lỗi","Tạo chỉ mục cơ sở dữ liệu"],"exp":"Tùy chọn A đúng: Chọn bố cục cho phạm vi kích thước xác định. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-107":{"q":"Chế độ xem Hiệu suất DevTools giúp kiểm tra điều gì?","options":["Tải trọng JWT","SQL lược đồ","Dòng thời gian FPS và chi phí kết xuất khung hình","Các tuyến đường được đặt tên"],"exp":"Tùy chọn C đúng: Dòng thời gian FPS và chi phí kết xuất khung hình. Hiệu suất Flutter phải được đánh giá ở chế độ profile, tốt nhất là trên thiết bị vật lý vì thời gian ở chế độ debug không mang tính đại diện."},"PRM-108":{"q":"Theo nguồn tin, \"Breakpoint\" là gì?","options":["Điểm mà mã ứng dụng dừng để gỡ lỗi.","Một pixel cụ thể width (e.g., 600px) được sử dụng để xác định thời điểm logic bố cục sẽ thay đổi.","Độ cao tối đa mà ListView có thể đạt tới trước khi cuộn.","Sự cố xảy ra khi widget vượt quá ranh giới của nó."],"exp":"Tùy chọn B đúng: Một pixel cụ thể width (e.g., 600px) được sử dụng để xác định khi nào logic bố cục sẽ thay đổi.. Câu trả lời khớp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-109":{"q":"Trong Dart, sự khác biệt cơ bản giữa `final` và `const` là gì?","options":["Không có gì khác biệt, hai từ khóa này có thể hoán đổi cho nhau trong mọi trường hợp","`final` là hằng số thời gian biên dịch, `const` là hằng số thời gian chạy","`final` là giá trị được gán một lần tại runtime (hằng số thời gian chạy), `const` là hằng số thời gian biên dịch","`final` chỉ dành cho loại số, `const` chỉ dành cho loại chuỗi"],"exp":"`final` được chỉ định một lần khi chạy; `const` là giá trị được biết trước tại thời điểm biên dịch. B đảo ngược các định nghĩa; D sai vì cả hai đều không bị giới hạn ở một loại dữ liệu cụ thể."},"PRM-110":{"q":"Câu nào đúng về sự khác biệt giữa `List`, `Set` và `Map` trong Dart?","options":["List không được sắp xếp và không cho phép trùng lặp, Set được sắp xếp, Map lưu trữ các cặp khóa-giá trị","List là tập hợp có thứ tự, Set là tập hợp các phần tử unique (không có thứ tự), Map lưu trữ các cặp khóa-giá trị","Cả ba đều có kiểu dữ liệu giống nhau, chỉ khác tên","Set được sắp xếp và cho phép trùng lặp, List thì không"],"exp":"List được sắp xếp; Set là tập hợp các phần tử duy nhất, không có thứ tự; Map lưu trữ các cặp khóa-giá trị --- định nghĩa tiêu chuẩn. A, C, D đều mô tả sai các đặc điểm cơ bản."},"PRM-111":{"q":"Trong Flutter, `State<T>` là ví dụ trong sách giáo khoa về khái niệm nào trong Mô-đun 3?","options":["Mixin","Lớp trừu tượng --- buộc StatefulWidgets sử dụng các phương thức override để xác định hành vi","Ràng buộc chung","Người xây dựng nhà máy"],"exp":"`State<T>` là một lớp trừu tượng, buộc StatefulWidget phải sử dụng các phương thức override để xác định hành vi. A, C, D không mô tả chính xác bản chất của State`<T>`."},"PRM-112":{"q":"Cú pháp Collection-if / Collection-for cho phép điều gì trong Dart?","options":["Chỉ có thể sử dụng được trong vòng lặp for thông thường, không sử dụng được trong khai báo List","Xây dựng linh hoạt một List/Set/Map bằng cách chèn elements (`if`) có điều kiện hoặc tạo các phần tử từ một loop (`for`) trực tiếp bên trong khai báo bộ sưu tập","Thay thế hoàn toàn từ khóa `var`","Chỉ áp dụng cho Map, không áp dụng cho List"],"exp":"Bộ sưu tập-if/for cho phép bạn xây dựng các bộ sưu tập một cách linh hoạt với các phần tử chèn có điều kiện hoặc được tạo vòng lặp ngay bên trong phần khai báo. A, C, D mô tả sai phạm vi áp dụng."},"PRM-113":{"q":"Theo bài giảng, Biểu tượng Material trong Flutter thường được sử dụng để làm gì?","options":["Hoàn toàn trang trí, không có chức năng","Các nút điều hướng, hành động buttons (thêm, xóa) và chỉ báo trạng thái","Chỉ được sử dụng làm nền Scaffold","Thay thế hoàn toàn Văn bản widget"],"exp":"Biểu tượng Material được sử dụng cho các nút điều hướng, nút hành động và chỉ báo trạng thái. A, C, D mô tả sai mục đích của chúng."},"PRM-114":{"q":"Kiểu dữ liệu nào lưu trữ giá trị dưới dạng cặp khóa-giá trị?","options":["Map","List","bool","Set"],"exp":"Tùy chọn A đúng: Map. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-115":{"q":"Từ khóa var có nghĩa là gì?","options":["Hằng số thời gian biên dịch","Kiểu biến được suy ra từ giá trị ban đầu của nó","Một hàm không bao giờ trả về","Một biến luôn có thể thay đổi thành bất kỳ loại nào"],"exp":"Tùy chọn B đúng: Loại biến được suy ra từ giá trị ban đầu của nó. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-116":{"q":"Từ khóa nào được sử dụng để kế thừa từ một lớp trong Dart?","options":["chỉ thực hiện","chỉ với","extends","inherits"],"exp":"Tùy chọn C đúng: extends. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-117":{"q":"Một trang Tài liệu thông thường thường chứa bao nhiêu Scaffold widgets chính?","options":["One","Chính xác là hai","Giàn giáo lồng nhau không giới hạn luôn được yêu cầu","Scaffold không được sử dụng"],"exp":"Tùy chọn A đúng: One. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-118":{"q":"Phương pháp nào hiển thị hình ảnh được khai báo trong nội dung dự án?","options":["Image.network","AssetText","Image.asset","FileBuilder"],"exp":"Tùy chọn C đúng: Image.asset. pubspec.yaml là tệp kê khai dự án dùng để khai báo các gói và cấu hình nội dung."},"PRM-119":{"q":"ElevatedButton thường được sử dụng cho loại hành động nào?","options":["Hành động chỉ có biểu tượng","Chỉ liên kết văn bản phụ","Một hành động chính như Đăng nhập, Lưu hoặc Gửi","Chọn giá trị liên tục"],"exp":"Tùy chọn C đúng: Hành động chính như Đăng nhập, Lưu hoặc Gửi. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-120":{"q":"Phương thức nào ghi Chuỗi vào một tệp?","options":["setString() của một widget","writeAsString()","query()","pushNamed()"],"exp":"Tùy chọn B đúng: writeAsString(). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-121":{"q":"Token được mô tả như thế nào?","options":["Một tập tin hình ảnh","Một widget","Mật khẩu thô của người dùng","Thông tin xác thực kỹ thuật số có thời hạn sử dụng ngắn do máy chủ tạo ra để chứng minh danh tính"],"exp":"Tùy chọn D đúng: Thông tin xác thực kỹ thuật số có thời hạn sử dụng ngắn do máy chủ tạo ra để chứng minh danh tính. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-122":{"q":"Khái niệm chính của Flutter UI là gì?","options":["Mọi thứ đều là widget","Mọi thứ đều là một lớp học","Mọi thứ đều là một chức năng","Mọi thứ đều là một tập tin"],"exp":"Tùy chọn A đúng: Mọi thứ đều là widget. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-123":{"q":"Từ khóa Dart nào khai báo biến được suy ra?","options":["let","dynamic","var","auto"],"exp":"Tùy chọn C đúng: var. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-124":{"q":"Bộ sưu tập nào sử dụng cặp khóa-giá trị?","options":["List","Set","Map","Tuple"],"exp":"Tùy chọn C đúng: Map. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-125":{"q":"Một vật thể là?","options":["một chức năng","Một thể hiện của một lớp","Một thư viện","Cây widget"],"exp":"Tùy chọn B đúng: Một thể hiện của một lớp. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-126":{"q":"widget nào thường được sử dụng cho thẻ vật liệu?","options":["Panel","Card","Canvas","Tile"],"exp":"Tùy chọn B đúng: Card. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-127":{"q":"widget nào hiển thị một dòng văn bản?","options":["Text","Chỉ RichText","Label","String"],"exp":"Tùy chọn A đúng: Text. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-128":{"q":"widget nào hiển thị hình ảnh từ nội dung?","options":["Image.asset","Asset.image","File.image","Picture.asset"],"exp":"Tùy chọn A đúng: Image.asset. pubspec.yaml là tệp kê khai dự án dùng để khai báo các gói và cấu hình nội dung."},"PRM-129":{"q":"widget nào tạo nút Material?","options":["ElevatedButton","ButtonWidget","ClickButton","TapButton"],"exp":"Tùy chọn A đúng: ElevatedButton. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-130":{"q":"widget nào được sử dụng cho các hành động chỉ có biểu tượng?","options":["FloatingActionButton","IconButton","ActionChip","PopupMenuButton"],"exp":"Tùy chọn B đúng: IconButton. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-131":{"q":"widget nào thường hiển thị nút tác vụ hình tròn?","options":["ElevatedButton","Icon","FloatingActionButton","Card"],"exp":"Tùy chọn C đúng: FloatingActionButton. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-132":{"q":"widget nào hiển thị thông báo bật lên ở cuối?","options":["AlertDialog","SnackBar","Banner","ToastView"],"exp":"Tùy chọn B đúng: SnackBar. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-133":{"q":"widget nào hiển thị hộp thoại phương thức?","options":["AlertDialog","Card","SnackBar","Drawer"],"exp":"Tùy chọn A đúng: AlertDialog. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-134":{"q":"Lớp nào chứa state có thể thay đổi cho StatefulWidget?","options":["State","WidgetStateHolder","MutableWidget","Store"],"exp":"Tùy chọn A đúng: State. Đây là khái niệm quản lý state: các thay đổi state phải thông báo hoặc kích hoạt phần có liên quan của UI để xây dựng lại."},"PRM-135":{"q":"Phương pháp nào mô tả widget UI?","options":["render","create","build","mount"],"exp":"Tùy chọn C đúng: build. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-136":{"q":"widget nào nên được ưu tiên cho các phần UI tĩnh khi có thể?","options":["const widget","dynamic widget","muộn widget","có thể thay đổi widget"],"exp":"Lựa chọn A đúng: const widget. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-137":{"q":"widget nào hiển thị khu vực tiêu đề thanh ứng dụng?","options":["AppBar","TopBar","TitleBar","Header"],"exp":"Tùy chọn A đúng: AppBar. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-138":{"q":"Thuộc tính nào của AppBar thường hiển thị tiêu đề widget?","options":["text","header","title","label"],"exp":"Tùy chọn C đúng: title. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-139":{"q":"widget nào tạo hiệu ứng thay đổi độ mờ?","options":["Opacity","AnimatedOpacity","FadeBox","AlphaWidget"],"exp":"Tùy chọn B đúng: AnimatedOpacity. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-140":{"q":"Thuộc tính nào của ListTile thường hiển thị biểu tượng/hình đại diện ở đầu?","options":["before","lead","leading","start"],"exp":"Tùy chọn C đúng: leading. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-141":{"q":"Thuộc tính nào của ListTile thường hiển thị văn bản nhỏ hơn bên dưới tiêu đề?","options":["caption","body","subtitle","note"],"exp":"Tùy chọn C đúng: subtitle. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-142":{"q":"Thuộc tính nào của ListTile thường hiển thị dấu widget?","options":["trailing","end","after","suffix"],"exp":"Tùy chọn A đúng: trailing. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-143":{"q":"widget nào có thể tạo các mục danh sách có thể loại bỏ?","options":["Dismissible","Removable","SwipeDelete","HiddenTile"],"exp":"Tùy chọn A đúng: Dismissible. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-144":{"q":"Hãy xem xét: dynamic x = 10; x = \"Hello\"; print(x); Điều gì xảy ra khi mã này chạy?","options":["Lỗi biên dịch vì không thể gán String cho biến đã được nhập là int","In \"Hello\" vì `dynamic` cho phép kiểu dữ liệu thay đổi khi chạy","In 10 vì kiểu dữ liệu gốc được giữ nguyên","Ném ra ngoại lệ TypeError khi chạy"],"exp":"`dynamic` cho phép kiểu dữ liệu thay đổi trong thời gian chạy, do đó nó in ra \"Hello\". A sai vì đây là hành vi `dynamic` hợp lệ; C, D sai vì không có lỗi và giá trị final là \"Hello\"."},"PRM-145":{"q":"Toán tử `??` làm gì trong Dart?","options":["So sánh đẳng thức kiểu","Trả về giá trị bên trái nếu nó không rỗng, nếu không thì trả về giá trị bên phải","Buộc ép kiểu không null, đưa ra lỗi nếu null","Toán tử XOR logic"],"exp":"`??` trả về phía bên trái nếu không rỗng, nếu không thì trả về bên phải side (kết hợp null). A, C, D mô tả sai chức năng của toán tử này."},"PRM-146":{"q":"Với `Map<String, int> scores = {\"Anna\": 95};`, điều gì sẽ xảy ra khi truy cập vào `scores[\"Ben\"]` (khóa không tồn tại)?","options":["Ném một ngoại lệ ngay lập tức","Trả về 0","Trả về giá trị rỗng","Trả về một chuỗi trống"],"exp":"Truy cập Map bằng khóa không tồn tại sẽ trả về giá trị rỗng trong Dart. A, B, D không khớp với hành vi mặc định của Map trong Dart."},"PRM-147":{"q":"Trong lần thử/bắt của Dart, cú pháp `catch (e, s)` cho phép nhà phát triển thực hiện những gì?","options":["Bắt hai loại ngoại lệ khác nhau cùng một lúc","Bắt đối tượng lỗi và dấu vết ngăn xếp tương ứng của nó","Bắt lỗi trên hai luồng khác nhau","Chỉ áp dụng cho lỗi loại String"],"exp":"`catch (e, s)` bắt cả đối tượng lỗi và dấu vết ngăn xếp. A, C, D mô tả sai chức năng của cú pháp này."},"PRM-148":{"q":"Hãy xem xét mã mixin bị ràng buộc này: class Pet { String name; Pet(this.name); } mixin CanBark on Pet { void bark() => print(\"\\$name says woof!\"); } class Dog extends Pet with CanBark { Dog() : super(\"Buddy\"); } class Fish { // want to apply \"with CanBark\" here } Nếu lớp `Fish` (không mở rộng `Pet`) cố gắng khai báo `class Fish with CanBark {}` thì điều gì sẽ xảy ra?","options":["Biên dịch thành công, Fish sẽ có phương thức bark() đang hoạt động","Lỗi biên dịch, vì mixin `CanBark` bị ràng buộc `on Pet`, chỉ các lớp mở rộng Pet mới có thể apply this mixin","Biên dịch nhưng đưa ra lỗi thời gian chạy khi gọi bark()","Dart sẽ tự động làm cho Fish ngầm mở rộng Pet"],"exp":"Mixin `CanBark on Pet` chỉ bị ràng buộc to các lớp apply to mở rộng Pet; vì Fish không mở rộng Pet nên biên dịch to không thành công. A, C, D không khớp với cách hoạt động của các ràng buộc mixin."},"PRM-149":{"q":"Với mã lớp chung này: class Box`<T>` { T value; Box(this.value); void show() => print(\"Value = \\$value\"); } void main() => Box`<int>`(10).show(); Nếu `Box<int>(10)` được thay thế bằng `Box<String>(10)`, điều gì sẽ xảy ra?","options":["Chạy bình thường, in \"Value = 10","Lỗi biên dịch vì 10 không phải là String, vi phạm ràng buộc loại chung","Dart tự động chuyển đổi 10 thành \"10","Chương trình đưa ra một ngoại lệ khi chạy nhưng vẫn biên dịch"],"exp":"`Box<String>(10)` không biên dịch được vì 10 (int) không khớp với loại String đã khai báo, vi phạm quy trình kiểm tra loại chung nghiêm ngặt. A, C, D không khớp với việc kiểm tra loại chung nghiêm ngặt của Dart."},"PRM-150":{"q":"Trong Flutter, widget nào đóng vai trò là \"xương sống\" của màn hình Material, cung cấp AppBar, nội dung và FloatActionButton?","options":["Container","Scaffold","MaterialApp","Column"],"exp":"Scaffold là xương sống của màn hình Material, cung cấp AppBar/body/FAB. A, C, D không mô tả chính xác vai trò cấu trúc này."},"PRM-151":{"q":"Học sinh đặt `ListView` trực tiếp bên trong `Column` mà không gói nó trong `Expanded` hoặc `Flexible`. Thường xảy ra lỗi gì?","options":["Ứng dụng chạy hoàn toàn bình thường, không có vấn đề gì","Lỗi \"tràn RenderFlex\" hoặc lỗi giới hạn chiều cao không giới hạn vì cả Column và ListView đều cố gắng yêu cầu không gian không giới hạn dọc theo trục chính","ListView tự động co lại thành đúng 1 mục","Column bị ẩn hoàn toàn khỏi màn hình"],"exp":"Việc đặt ListView trong Column không có Expanded/Flexible sẽ gây ra chiều cao không giới hạn error (tràn). A sai vì đây chính xác là lỗi phổ biến; C, D không khớp với hành vi thực tế của Flutter."},"PRM-152":{"q":"Trong ví dụ ListTile + CircleAvatar: ListTile( lead: CircleAvatar(child: Text(m['title']\\![0])), title: Text(m['title']!), subtitle: Text(m['year']!), Trailing: const Icon(Icons.chevron_right), onTap: () => debugPrint('Selected \\${m['title']}'), ); `!` sau `m['title']` có nghĩa là gì trong ngữ cảnh của Dart không an toàn?","options":["Toán tử logic negation (NOT)","Toán tử \"xác nhận null\" --- xác nhận với trình biên dịch rằng giá trị chắc chắn là không null; nếu sai thì nó báo lỗi thời gian chạy","Toán tử này hoàn toàn mang tính chất trang trí, không ảnh hưởng gì đến logic","Chuyển đổi loại String thành int"],"exp":"`!` là toán tử xác nhận null, xác nhận không null cho trình biên dịch, đưa ra lỗi thời gian chạy nếu sai. A, C, D mô tả sai ý nghĩa của toán tử này ở mức độ an toàn vô giá trị."},"PRM-153":{"q":"`Wrap` widget khác với `Row` như thế nào và tại sao nó phù hợp với danh sách chip thể loại?","options":["Wrap giống hệt với Row, không có sự khác biệt","Wrap tự động gói các phần tử con vào một dòng mới khi không có đủ khoảng trống theo chiều ngang, tránh lỗi tràn mà Row sẽ gặp phải khi có quá nhiều phần tử","Wrap chỉ cho phép tối đa 2 phần tử con","Row tự động ngắt dòng nhưng Wrap thì không"],"exp":"Wrap tự động xếp các phần tử con vào một dòng mới khi hết không gian theo chiều ngang, tránh tình trạng tràn Row. A, C, D mô tả sai/đảo ngược hai đặc điểm của widgets'."},"PRM-154":{"q":"Trong mã Màn hình chính được phân chia: body: ListView( đệm: const EdgeInsets.all(12), children: [ section('Now Playing'), const Placeholder(fallbackHeight: 120), section('Trending'), const Placeholder(fallbackHeight: 120), ], ), Tại sao lại sử dụng `ListView` (thay vì `Column`) làm gốc widget cho toàn bộ màn hình chứa nhiều phần?","options":["Bởi vì ListView là bắt buộc bên trong mọi Scaffold","Bởi vì ListView tự động cho phép cuộn khi nội dung vượt quá chiều cao màn hình, trong khi Column theo mặc định không thể cuộn và dễ gây tràn","Vì Column không hỗ trợ phần đệm","Không có lý do kỹ thuật, đó là sự lựa chọn ngẫu nhiên"],"exp":"ListView cho phép cuộn khi nội dung vượt quá chiều cao màn hình, trong khi Column không cuộn theo mặc định và dễ bị tràn. A, C, D không phù hợp với lý do kỹ thuật thực tế."},"PRM-155":{"q":"Trong Mã VS, tính năng \"Gói bằng Widget\" hỗ trợ gì cho nhà phát triển Flutter?","options":["Tự động triển khai ứng dụng đến cửa hàng","Nhanh chóng gói một widget đã chọn bằng một widget khác như Đệm, Giữa, Được mở rộng để tái cấu trúc bố cục","Tự động sửa mọi lỗi cú pháp trong file","Chuyển đổi Dart thành Kotlin"],"exp":"Gói bằng Widget\" nhanh chóng gói một widget đã chọn bằng Phần đệm/Center/Mở rộng để tái cấu trúc bố cục. A, C, D không phù hợp với chức năng của tính năng này."},"PRM-156":{"q":"Trong ví dụ Scaffold cơ bản, `floatingActionButton` thường được đặt ở đâu và nó được dùng để làm gì?","options":["Chính giữa màn hình, làm nền cho toàn bộ cơ thể","Thường nổi ở góc dưới bên phải màn hình, được sử dụng cho action chính nổi bật (e.g. add new)","Chỉ hiển thị bên trong AppBar","Không có vị trí cố định, luôn ở giữa AppBar"],"exp":"floatingActionButton thường nổi ở phía dưới bên phải, được sử dụng cho hành động chính nổi bật. A, C, D mô tả sai vị trí/vai trò của nó."},"PRM-157":{"q":"Theo Mô-đun 4, khi nào nên sử dụng `SingleChildScrollView` hoặc `Flexible` để khắc phục tình trạng tràn màn hình trên màn hình nhỏ?","options":["Không bao giờ cần thiết, Flutter tự động xử lý tình trạng tràn","Khi nội dung UI vượt quá màn hình có sẵn size (đặc biệt trên màn hình nhỏ), bạn cần cuộn hoặc thay đổi kích thước linh hoạt để tránh tràn bố cục","Chỉ sử dụng cho các ứng dụng chạy trên Desktop","Chỉ áp dụng cho Văn bản widget"],"exp":"Sử dụng chúng khi nội dung vượt quá kích thước màn hình có sẵn, để cho phép cuộn hoặc thay đổi kích thước linh hoạt và tránh tràn. A sai vì Flutter không tự động xử lý mọi trường hợp tràn; C, D hạn chế sai phạm vi sử dụng."},"PRM-158":{"q":"Sự khác biệt giữa `Flexible` và `Expanded` trong Hàng/Cột là gì?","options":["Không có gì khác biệt, hai widgets hoàn toàn tương đương","`Expanded` buộc trẻ chiếm toàn bộ không gian được phân bổ theo tỷ lệ linh hoạt, trong khi `Flexible` cho phép trẻ nhỏ hơn không gian được phân bổ nếu không cần all (tùy thuộc vào `fit: FlexFit.loose`)","Flexible chỉ có thể được sử dụng bên trong GridView chứ không phải trong Hàng/Cột","Expanded chỉ hoạt động với Văn bản widget"],"exp":"Expanded buộc lấp đầy toàn bộ không gian linh hoạt được phân bổ; Flexible cho phép kích thước nhỏ hơn nếu không phải là needed (FlexFit.loose). A, C, D không khớp với hành vi thực tế của chúng."},"PRM-159":{"q":"Theo \"Các phương pháp hay nhất\" của Mô-đun 6, khi nào `Wrap` nên được ưu tiên hơn `Row`?","options":["Khi hiển thị danh sách chip dài có thể tràn không gian ngang","Khi chỉ có đúng 1 phần tử con","Khi bạn cần một widget cố định không bao giờ thay đổi kích thước","`Wrap` không bao giờ được ưu tiên hơn Row"],"exp":"Wrap nên được ưu tiên cho danh sách chip dài có thể tràn theo chiều ngang. B, C, D không phù hợp với phương pháp hay nhất đã nêu."},"PRM-160":{"q":"Trong ví dụ trên, nếu người dùng nhập email `\"taken123@test.com\"`, ứng dụng sẽ hiển thị thông báo gì sau 2 giây?","options":["Đã tạo tài khoản cho taken123@test.com","Email này đã là taken","Không có tin nhắn nào được hiển thị","Ứng dụng sẽ đưa ra một ngoại lệ vì email không hợp lệ"],"exp":"Vì email bắt đầu bằng \"taken\" nên logic `_email.toLowerCase().startsWith(\"taken\")` hiển thị \"Email này đã là taken\" sau 2 giây. A, C, D không khớp với logic của mã đã cho."},"PRM-161":{"q":"Trong cú pháp SQL SELECT được ôn lại trong bài giảng, mệnh đề nào được sử dụng để LỌC các hàng dữ liệu trước khi trả về kết quả?","options":["ĐẶT HÀNG BỞI","WHERE","LIMIT","SELECT"],"exp":"`WHERE` lọc các hàng dữ liệu trước khi trả về kết quả. A, C, D phục vụ purposes khác (sắp xếp, giới hạn, chọn cột)."},"PRM-162":{"q":"Mệnh đề `GROUP BY` kết hợp với `HAVING` thường được sử dụng khi nào?","options":["Khi bạn cần sắp xếp kết quả theo thứ tự abc","Khi bạn cần nhóm các hàng theo tiêu chí và áp dụng điều kiện lọc trên các hàm tổng hợp như SUM, COUNT","Khi bạn cần giới hạn số lượng trả về records (phân trang)","Khi bạn cần đổi tên một cột trong kết quả truy vấn"],"exp":"GROUP BY + HAVING được sử dụng để nhóm các hàng và lọc theo các hàm tổng hợp như SUM/COUNT. A, C, D không phù hợp với mục đích của các điều khoản này."},"PRM-163":{"q":"widgets nào sau đây là ví dụ trong sách giáo khoa về Hoạt ảnh ngầm?","options":["AnimationController","AnimatedContainer","Tween","CurvedAnimation"],"exp":"`AnimatedContainer` là Sách giáo khoa Hoạt ảnh tiềm ẩn widget --- nó tự động hoạt hình khi properties (màu sắc, kích thước...) của nó thay đổi. A, C, D là các thành phần thuộc về Hoạt ảnh rõ ràng hoặc các công cụ hỗ trợ, chứ không phải chính Hoạt ảnh ngầm định widget."},"PRM-164":{"q":"Map.putIfAbsent(key, ifAbsent) làm gì khi khóa không tồn tại?","options":["Xóa toàn bộ Map","Ngay lập tức ném ra một lỗi","Gọi ifAbsent, lưu kết quả vào Map và trả về giá trị mới","Trả về null mà không gọi hàm"],"exp":"Tùy chọn C đúng: Gọi ifAbsent, lưu kết quả vào Map và trả về giá trị mới. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-165":{"q":"Cột và Hàng sắp xếp con cái theo hướng nào?","options":["Cột theo chiều dọc và Hàng theo chiều ngang","Cả hai đều là lưới","Chỉ theo chiều dọc","Cột theo chiều ngang và Hàng theo chiều dọc"],"exp":"Lựa chọn A đúng: Cột theo chiều dọc và Hàng theo chiều ngang. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-166":{"q":"widget nào phù hợp để hiển thị danh sách có thể cuộn dài?","options":["Ngăn xếp không thể cuộn được","IconButton","Một hàng cố định","ListView.builder hoặc ListView.separated"],"exp":"Tùy chọn D đúng: ListView.builder hoặc ListView.separated. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-167":{"q":"Lỗi thường gặp khi đặt ListView không bị ràng buộc bên trong Cột thường được khắc phục như thế nào?","options":["Thay thế nó bằng văn bản","Thêm GlobalKey ở mọi nơi","Xóa Scaffold","Gói ListView bằng phần mở rộng"],"exp":"Tùy chọn D đúng: Gói ListView bằng Mở rộng. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-168":{"q":"Linh hoạt khác với Mở rộng như thế nào?","options":["Nó cho phép trẻ uốn cong mà không buộc trẻ phải lấp đầy tất cả không gian còn lại","Nó chỉ được sử dụng cho cơ sở dữ liệu","Nó luôn tạo ra sự cuộn","Nó không thể được sử dụng trong một hàng hoặc cột"],"exp":"Phương án A đúng: Nó cho phép trẻ uốn cong mà không buộc trẻ phải lấp đầy khoảng trống còn lại. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-169":{"q":"Cải tiến nào được đề xuất cho màn hình rộng hơn 800 pixel?","options":["Yêu cầu chiều rộng cố định","Ẩn tất cả các bộ lọc","Sử dụng thanh bên bộ lọc và danh sách phim hai cột","Chỉ sử dụng một cột hẹp"],"exp":"Tùy chọn C đúng: Sử dụng thanh bên bộ lọc và danh sách phim hai cột. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-170":{"q":"Nội dung phản hồi của mạng trước khi giải mã là loại gì?","options":["Một đối tượng Post được tạo sẵn","String","Một hàng cơ sở dữ liệu","Cây widget"],"exp":"Tùy chọn B đúng: String. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-171":{"q":"Cú pháp hàm mũi tên trong Dart là gì?","options":["->","=>","==>","::="],"exp":"Tùy chọn B đúng: `=>` là cú pháp mũi tên của Dart cho hàm bao gồm một biểu thức."},"PRM-172":{"q":"Làm gì ?? nghĩa là trong Dart?","options":["Ném ngoại lệ","Mặc định nếu rỗng","Buộc thi triển","Increment"],"exp":"Tùy chọn B đúng: Mặc định nếu rỗng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-173":{"q":"widget nào thêm khoảng trống xung quanh phần tử con của nó?","options":["Margin","Padding","Align","Stack"],"exp":"Tùy chọn B đúng: Padding. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-174":{"q":"widget nào tập trung vào con của nó?","options":["Expanded","Align","Center","Positioned"],"exp":"Tùy chọn C đúng: Center. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-175":{"q":"widget nào sắp xếp phần tử con theo chiều dọc?","options":["Row","Column","Stack","Wrap"],"exp":"Tùy chọn B đúng: Column. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-176":{"q":"widget nào sắp xếp phần tử con theo chiều ngang?","options":["Row","Column","ListView","Flex"],"exp":"Tùy chọn A đúng: Row. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-177":{"q":"widget nào chồng lên các phần tử con?","options":["Stack","Wrap","Column","Expanded"],"exp":"Tùy chọn A đúng: Stack. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-178":{"q":"widget nào được sử dụng cho danh sách có thể cuộn?","options":["GridView","ListView","Row","Table"],"exp":"Tùy chọn B đúng: ListView. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-179":{"q":"`CurvedAnimation` trong Flutter dùng để làm gì?","options":["Vẽ một đường cong hình học trên màn hình","Áp dụng tính năng nới lỏng curve (e.g. `Curves.easeIn`) cho Hoạt ảnh tuyến tính hiện có, thay đổi cách giá trị của hoạt ảnh thay đổi trên time (nhanh/chậm không đồng đều) thay vì tuyến tính","Thay thế hoàn toàn AnimationController","Chỉ có thể sử dụng được với SliverAppBar"],"exp":"CurvedAnimation áp dụng đường cong giảm dần cho Hoạt ảnh tuyến tính, làm cho giá trị của nó thay đổi phi tuyến tính theo thời gian. A, C, D mô tả sai chức năng của nó."},"PRM-180":{"q":"Sự khác biệt cơ bản giữa `SliverAppBar` và `AppBar` thông thường là gì?","options":["SliverAppBar chỉ có thể hiển thị biểu tượng chứ không hiển thị văn bản","SliverAppBar được thiết kế để hoạt động bên trong `CustomScrollView`, có thể mở rộng, thu nhỏ hoặc hiển thị/ẩn linh hoạt dựa trên hành vi cuộn, trong khi AppBar thông thường có vị trí cố định","SliverAppBar không được chứa các nút hành động","Hai widgets hoàn toàn giống nhau, chỉ khác tên"],"exp":"SliverAppBar hoạt động bên trong CustomScrollView với khả năng mở rộng/thu nhỏ/hiển thị ẩn linh hoạt khi cuộn, không giống như AppBar thông thường có vị trí cố định. A, C, D mô tả sai đặc điểm."},"PRM-181":{"q":"Thuộc tính `flexibleSpace` và `expandedHeight` của `SliverAppBar` được dùng để làm gì?","options":["`flexibleSpace` xác định nội dung được hiển thị khi AppBar ở dạng state mở rộng (e.g. một hình nền lớn); `expandedHeight` đặt chiều cao tối đa khi AppBar được mở rộng hoàn toàn --- khi bạn cuộn xuống, AppBar sẽ dần dần co lại về chiều cao tiêu chuẩn của nó","Hai thuộc tính này chỉ ảnh hưởng đến màu sắc chứ không ảnh hưởng đến kích thước","`expandedHeight` xác định số lượng nút hành động tối đa","`flexibleSpace` chỉ hoạt động khi không có `CustomScrollView`"],"exp":"flexibleSpace xác định nội dung mở rộng-state; expandedHeight đặt chiều cao mở rộng tối đa, thu nhỏ khi cuộn. B, C, D mô tả sai chức năng của hai thuộc tính này."},"PRM-182":{"q":"Trong hệ sinh thái Sliver, `SliverList` và `SliverGrid` khác với `ListView`/`GridView` thông thường như thế nào?","options":["Không có gì khác biệt cả, hai loại này hoàn toàn tương đương trong mọi ngữ cảnh","`SliverList`/`SliverGrid` được thiết kế để kết hợp nhiều nội dung có thể cuộn khác nhau types (như SliverAppBar, SliverList, SliverGrid) trong một DUY NHẤT `CustomScrollView` với hiệu ứng cuộn liền mạch, trong khi `ListView`/`GridView` là các nội dung có thể cuộn độc lập widgets, khó phối hợp các hiệu ứng cuộn với các widgets có thể cuộn khác","SliverList chỉ hiển thị tối đa 10 phần tử","SliverGrid không hỗ trợ hiển thị hình ảnh"],"exp":"SliverList/SliverGrid được thiết kế để kết hợp liền mạch nhiều nội dung có thể cuộn trong một CustomScrollView, không giống như ListView/GridView độc lập. A, C, D không phù hợp với đặc tính kỹ thuật thực tế."},"PRM-183":{"q":"widget nào có thể dễ dàng cắt phần tử con của nó thành các góc tròn?","options":["ClipRRect","BorderRadius","DecoratedBox","RoundedBox"],"exp":"Tùy chọn A đúng: ClipRRect. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-184":{"q":"widget nào được sử dụng để vẽ tùy chỉnh?","options":["CustomPaint","PaintBox","DrawWidget","CanvasView"],"exp":"Tùy chọn A đúng: CustomPaint. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-185":{"q":"Lớp nào được mở rộng cho bản vẽ tùy chỉnh?","options":["CustomPainter","PaintState","DrawerPainter","ShapeBuilder"],"exp":"Tùy chọn A đúng: CustomPainter. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-186":{"q":"widget nào kết hợp nhiều phần trong một vùng có thể cuộn?","options":["CustomScrollView","MultiList","ScrollGroup","SliverBox"],"exp":"Tùy chọn A đúng: CustomScrollView. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-187":{"q":"widget nào có thể ghim và mở rộng thanh ứng dụng trong CustomScrollView?","options":["SliverAppBar","FlexibleBar","StickyBar","AppHeader"],"exp":"Tùy chọn A đúng: SliverAppBar. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-188":{"q":"widget nào là cần thiết để đảm bảo rằng các phần tử UI không bị che khuất bởi các tính năng phần cứng như \"Đảo động\", rãnh khía hoặc cạnh màn hình cong?","options":["Expanded","AspectRatio","SafeArea","FractionallySizedBox"],"exp":"Tùy chọn C đúng: SafeArea. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-189":{"q":"Nếu bạn muốn GridView hiển thị 2 cột trên thiết bị di động và 4 cột trên máy tính bảng, thuộc tính nào sẽ được cập nhật dựa trên chiều rộng màn hình?","options":["mainAxisSpacing","crossAxisCount","aspectRatio","pixelDensity"],"exp":"Tùy chọn B đúng: crossAxisCount. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-190":{"q":"Vai trò chính của Lớp nhúng trong kiến ​​trúc của Flutter là gì?","options":["Cung cấp tất cả Tài liệu và Cupertino widgets","Biên dịch mã Dart thành mã máy ARM","Tích hợp dành riêng cho nền tảng, xử lý dữ liệu đầu vào, lifecycle và quản lý cửa sổ","Thực hiện phân tích cú pháp JSON từ API"],"exp":"Lớp nhúng xử lý việc tích hợp, đầu vào, lifecycle và quản lý cửa sổ dành riêng cho nền tảng. A và D thuộc về các lớp Khung/mạng; B là công việc của trình biên dịch Dart AOT, không phải Trình nhúng."},"PRM-191":{"q":"`ThemeMode.system` có nghĩa là gì trong `MaterialApp`?","options":["Buộc ứng dụng luôn sử dụng giao diện nhẹ nhàng","Buộc ứng dụng luôn sử dụng chủ đề tối","Ứng dụng tự động tuân theo cài đặt giao diện sáng/tối ở cấp độ hệ điều hành của thiết bị","Không có hiệu lực nếu darkTheme không được khai báo"],"exp":"`ThemeMode.system` làm cho ứng dụng tự động tuân theo cài đặt sáng/tối của hệ điều hành của thiết bị. A, B sửa một chế độ, mâu thuẫn với \"system\"; D sai vì themeMode vẫn có ý nghĩa nhưng hiệu ứng đầy đủ cần được khai báo darkTheme."},"PRM-192":{"q":"Đã cho: return MaterialApp( theme: ThemeData.light(useMaterial3: true), darkTheme: ThemeData.dark(useMaterial3: true), themeMode: ThemeMode.dark, home: const DemoTheme(), ); Inside a child widget, what is the correct syntax to access the current theme's style (e.g. `titleLarge`)?","options":["`ThemeData.of(context).textTheme.titleLarge`","`Theme.of(context).textTheme.titleLarge`","`context.theme.titleLarge`","`MaterialApp.theme(context).titleLarge`"],"exp":"`Theme.of(context).textTheme.titleLarge` is the correct syntax để truy cập the current theme. A, C, D không phải là API Flutter hợp lệ."},"PRM-193":{"q":"Một học sinh viết: class DemoTheme extends StatelessWidget { @override Widget build(BuildContext context) { return Scaffold( body: Center(child: Text('Current theme', style: Theme.of(context).textTheme.titleLarge)), ); } } `BuildContext context` đóng vai trò gì trong hàm `build` khi gọi `Theme.of(context)`?","options":["Một tham số không có tác dụng thực sự, hoàn toàn mang tính hình thức","Biểu thị vị trí của widget trong cây widget, cho phép nó tra cứu InheritedWidget data gần nhất (như Theme) phía trên nó trong cây","Ứng dụng lưu trữ biến toàn cục state","Chỉ dùng để truyền dữ liệu API"],"exp":"`BuildContext` đại diện cho vị trí cây của widget, cho phép tra cứu of InheritedWidget gần nhất (như Theme) phía trên nó. A, C, D mô tả sai vai trò của BuildContext."},"PRM-194":{"q":"Sự khác biệt cốt lõi giữa \"Đáp ứng UI\" và \"Thích ứng UI\" trên mỗi bài giảng là gì?","options":["Các thay đổi UI đáp ứng dựa trên loại thiết bị, các thay đổi UI thích ứng dựa trên không gian có sẵn","UI đáp ứng thay đổi bố cục dựa trên space có sẵn (e.g. Cột → Hàng), trong khi UI thích ứng thay đổi dựa trên thiết bị type (e.g. Điều hướng dưới cùng → NavigationRail trên máy tính bảng)","Hai khái niệm này giống hệt nhau, không có sự khác biệt thực sự","Tính năng thích ứng UI chỉ áp dụng cho ứng dụng Web"],"exp":"Đáp ứng UI phản ứng với không gian có sẵn; Thích ứng UI phản ứng với loại thiết bị. A đảo ngược hai định nghĩa; C, D không phù hợp với nội dung bài giảng."},"PRM-195":{"q":"`MediaQuery.of(context).size.width` truy xuất thông tin gì?","options":["width of chính widget hiện tại","Toàn bộ width of màn hình của thiết bị hiện tại","width of bàn phím ảo","Số of con widgets trong cây"],"exp":"`MediaQuery.of(context).size.width` lấy toàn màn hình của thiết bị hiện tại width. A, C, D mô tả sai phạm vi of giá trị được trả về."},"PRM-196":{"q":"Đưa ra: Widget build(BuildContext context) { final w = MediaQuery.of(context).size.width; return Scaffold( body: Center( child: Text(w < 600 ? \"Mobile Layout\" : \"Tablet Layout\"), ), ); } Khi thiết bị được xoay từ dọc sang ngang, làm cho chiều rộng vượt quá 600px, điều gì sẽ xảy ra với văn bản được hiển thị?","options":["Không có gì thay đổi vì MediaQuery chỉ đọc giá trị một lần khi khởi động ứng dụng","Flutter tự động xây dựng lại widget khi màn hình size changes (e.g. do xoay), do đó văn bản chuyển từ \"Mobile Layout\" sang \"Tablet Layout","Ứng dụng gặp sự cố vì MediaQuery không hỗ trợ xoay màn hình","Chỉ có Text bị ẩn hoàn toàn cho đến khi ứng dụng khởi động lại"],"exp":"Flutter tự động tạo lại khi màn hình size changes (e.g. xoay), do đó MediaQuery phản ánh màn hình đó trong thời gian thực. A, C, D không khớp với hành vi thực tế của MediaQuery/Flutter."},"PRM-197":{"q":"Sự khác biệt cốt lõi giữa `LayoutBuilder` và `MediaQuery` là gì?","options":["LayoutBuilder cung cấp thông tin về các ràng buộc của cha mẹ trực tiếp widget, trong khi MediaQuery cung cấp thông tin của toàn bộ màn hình thiết bị","Cả hai đều hoàn toàn giống nhau về chức năng","LayoutBuilder chỉ hoạt động trên Web","MediaQuery chỉ cung cấp các ràng buộc của widget gốc chứ không cung cấp toàn màn hình"],"exp":"LayoutBuilder đưa ra các ràng buộc của cấp độ gốc trực tiếp; MediaQuery cung cấp thông tin thiết bị toàn màn hình. B, C, D đảo ngược/nhầm lẫn đặc điểm của hai công cụ."},"PRM-198":{"q":"Cho trước: LayoutBuilder( builder: (context, c) { return c.maxWidth > 500 ? WideCard() : NarrowCard(); }, ); Nếu `LayoutBuilder` này được đặt bên trong một `Container` có chiều rộng cố định là 300px (trong khi màn hình thiết bị rộng 800px), thì widget nào sẽ được hiển thị?","options":["WideCard(), vì màn hình thiết bị rộng hơn 500px","NarrowCard(), vì `c.maxWidth` phản ánh ràng buộc từ cấp độ gốc trực tiếp widget (300px), chứ không phải toàn màn hình thiết bị","Cả hai widgets sẽ được hiển thị cùng lúc","Điều này sẽ gây ra lỗi vì không thể đặt LayoutBuilder bên trong Container có kích thước cố định"],"exp":"`c.maxWidth` phản ánh constraint của cha mẹ trực tiếp (300px), không phải toàn màn hình, vì vậy NarrowCard() được hiển thị. A bỏ qua vai trò của ràng buộc cục bộ; C, D không khớp với cách LayoutBuilder thực sự hoạt động."},"PRM-199":{"q":"`OrientationBuilder` dùng để làm gì?","options":["Đang phát hiện thiết bị rotation (dọc/ngang) và thay đổi UI cho phù hợp","Chỉ được sử dụng để thay đổi màu nền của ứng dụng","Kiểm tra kết nối mạng của thiết bị","Thay thế hoàn toàn MediaQuery trong mọi trường hợp"],"exp":"OrientationBuilder phát hiện thao tác xoay thiết bị và cho phép UI thay đổi tương ứng. B, C, D mô tả sai chức năng của nó."},"PRM-200":{"q":"Trong danh sách \"Tổng quan về tiện ích đáp ứng\", widget nào giúp tránh tràn bằng cách để phần tử con chiếm không gian còn lại trong Hàng/Cột?","options":["Wrap","Expanded","AspectRatio","FractionallySizedBox"],"exp":"Expanded cho phép trẻ chiếm khoảng trống còn lại trong Hàng/Cột, tránh tràn. A, C, D phục vụ các mục đích khác, không cụ thể cho mục đích này."},"PRM-201":{"q":"Với mã GridView này: GridView.count( crossAxisCount: width < 600 ? 2 : 4, ); Nếu biến `width` được đọc MỘT LẦN trong `initState()` thay vì trong `build()` (từ MediaQuery), vấn đề gì có thể phát sinh khi người dùng xoay màn hình sau đó?","options":["Không có vấn đề gì cả vì Flutter tự động đồng bộ hóa initState với build","`crossAxisCount` sẽ không được cập nhật khi kích thước màn hình changes (do xoay), vì initState chỉ chạy một lần khi widget được tạo, khiến bố cục không còn phản ánh kích thước hiện tại","GridView sẽ tự động ẩn hoàn toàn","Ứng dụng sẽ hiển thị lỗi biên dịch"],"exp":"Chỉ đọc width trong initState() có nghĩa là crossAxisCount không được cập nhật khi xoay vòng, vì initState chỉ chạy một lần khi tạo widget. A, C, D không phù hợp với hệ quả kỹ thuật thực tế."},"PRM-202":{"q":"Trong Genre Chips example (danh sách chip dựa trên Wrap), bài giảng nhấn mạnh: \"Hành vi này đạt được một cách tự động bằng cách sử dụng Wrap, không có logic có điều kiện.\" Điều này có ý nghĩa gì về mặt kỹ thuật?","options":["Bạn cần nhiều câu lệnh `if` để kiểm tra kích thước màn hình, sau đó quyết định số chip trên mỗi hàng","`Wrap` widget tự động tính toán và gói các phần tử vào một dòng mới dựa trên không gian có sẵn mà không cần nhà phát triển viết logic điều kiện thủ công để đáp ứng","Wrap chỉ hoạt động chính xác khi được kết hợp với LayoutBuilder","Mô tả này sai, Wrap luôn cần logic điều kiện đi kèm"],"exp":"`Wrap` tự động tính toán và bao bọc các phần tử dựa trên không gian có sẵn mà không cần logic điều kiện thủ công. A, C, D không khớp với ý nghĩa dự định của câu được trích dẫn."},"PRM-203":{"q":"Trong ví dụ về Thẻ phim đáp ứng: LayoutBuilder( builder: (context, c) { final isWide = c.maxWidth > 600; return Row(children: [ Image.network(poster, width: isWide ? 150 : 100), SizedBox(width: 16), Expanded(child: Text(title)) ]); }, ) Vai trò của `Expanded` gói `Text(title)` trong Hàng này là gì?","options":["Làm cho Text tự động in đậm","Cho phép Text chiếm toàn bộ không gian ngang còn lại sau hình ảnh, đồng thời tránh tràn ngang khi title dài","Expanded hoàn toàn mang tính thẩm mỹ, không liên quan đến bố cục","Expanded làm cho hình ảnh co lại để phù hợp với kích thước của Text"],"exp":"Expanded cho phép Text chiếm không gian ngang còn lại và tránh tràn ngang cho các tiêu đề dài. A, C, D mô tả sai vai trò kỹ thuật của Expanded ở đây."},"PRM-204":{"q":"Trong Lab 6.3 (Tăng cường bố cục máy tính bảng), yêu cầu đối với màn hình > 800px là thêm bộ lọc thanh bên và chuyển sang danh sách phim 2 cột. Kỹ thuật nào được khuyến nghị để triển khai điều này ở cấp độ gốc của màn hình?","options":["Chỉ sử dụng `Wrap`, không cần công cụ nào khác","Sử dụng `LayoutBuilder` ở cấp cơ sở để phát hiện giới hạn về chiều rộng, quyết định hiển thị máy tính bảng layout (thanh bên + 2 cột) hay bố cục trên thiết bị di động","Sử dụng `OrientationBuilder` thay vì kiểm tra chiều rộng","Không thể tạo bố cục máy tính bảng riêng biệt trong Flutter"],"exp":"Việc sử dụng LayoutBuilder ở cấp cơ sở để phát hiện giới hạn về độ rộng là technique được khuyến nghị (theo ghi chú \"sử dụng LayoutBuilder ở cấp cơ sở\"). A, C, D không phù hợp với kỹ thuật được đề xuất."},"PRM-205":{"q":"`AspectRatio` widget trong danh sách \"Tổng quan về tiện ích đáp ứng\" giúp giải quyết vấn đề gì?","options":["Giúp hình ảnh tránh bị kéo giãn/méo khi kích thước vùng chứa thay đổi, bằng cách duy trì tỷ lệ khung hình cố định","Tăng tốc độ tải hình ảnh từ mạng","Chỉ dùng được cho video, không dùng được cho hình ảnh","Thay thế hoàn toàn BoxFit"],"exp":"AspectRatio duy trì tỷ lệ khung hình cố định để hình ảnh không bị giãn khi kích thước vùng chứa thay đổi. B, C, D không khớp với phạm vi/chức năng của nó."},"PRM-206":{"q":"Hãy xem xét: một danh sách thả xuống sắp xếp được đặt bên trong `Row` với `mainAxisSize: MainAxisSize.max` cùng với widgets có kích thước cố định lớn khác, khiến tổng chiều rộng vượt quá một màn hình nhỏ. Theo tinh thần của Mô-đun 6, giải pháp nào là hợp lý nhất?","options":["Loại bỏ hoàn toàn Dropdown khỏi màn hình nhỏ","Wrap element linh hoạt (như Trình đơn thả xuống hoặc văn bản dài) với `Flexible`/`Expanded` hoặc sử dụng `Wrap` để tự động ngắt dòng sang dòng mới khi không có đủ khoảng trống","Luôn cung cấp cho mọi phần tử trong Row một kích thước cố định tuyệt đối","Chuyển đổi toàn bộ Row thành Ngăn xếp"],"exp":"Việc gói phần tử linh hoạt bằng Flexible/Expanded hoặc sử dụng Wrap để tự động gói là giải pháp được đề xuất. A, C, D không phù hợp với nguyên tắc đáp ứng đã dạy."},"PRM-207":{"q":"So sánh việc sử dụng `MediaQuery.of(context).size.width` ở cấp độ toàn màn hình với `LayoutBuilder` ở cấp độ con được lồng sâu widget level (e.g. bên trong Thẻ hẹp trong Hàng 3 cột). Tuyên bố nào là chính xác nhất?","options":["Cả hai cách tiếp cận luôn cho kết quả giống nhau trong mọi trường hợp","`MediaQuery` trả về toàn màn hình của thiết bị width mặc dù con widget bị ràng buộc nhiều hơn bởi cha mẹ của nó, trong khi `LayoutBuilder` phản ánh chính xác space (ràng buộc) thực mà con widget thực sự có --- vì vậy hãy sử dụng LayoutBuilder khi bạn cần phản hồi với không gian cục bộ","LayoutBuilder không thể được sử dụng lồng trong một Hàng","MediaQuery chỉ hoạt động bên trong StatelessWidget"],"exp":"MediaQuery trả về toàn màn hình width bất kể ràng buộc cục bộ of; LayoutBuilder phản ánh chính xác không gian cục bộ thực tế --- sử dụng LayoutBuilder để đáp ứng cục bộ. A, C, D không phù hợp với đặc tính kỹ thuật đã phân tích."},"PRM-208":{"q":"Theo bài giảng, công cụ nào trong Flutter Inspector giúp debug bố cục phản hồi?","options":["Trình khám phá bố cục","Thanh tra mạng","Trình phân tích bộ nhớ","Trình phân tích CPU"],"exp":"Layout Explorer\" trong Flutter Inspector giúp debug bố cục phản hồi theo \"Các phương pháp hay nhất\" của Mô-đun 6. B, C, D không phải là công cụ được nêu cho mục đích này."},"PRM-209":{"q":"Trong ngữ cảnh của thanh tìm kiếm đáp ứng: Container( đệm: EdgeInsets.symmetric(horizontal: 16), child: TextField(...), ) Bài giảng lưu ý \"Học sinh thường quên SafeArea ở đây.\" Nếu đây là phần tử đầu tiên trong `body` của Scaffold và không có SafeArea thì rủi ro cụ thể nào có thể xảy ra nhất trên thiết bị có notch?","options":["TextField sẽ tự động bị vô hiệu hóa","Phần trên cùng của thanh tìm kiếm có thể bị chồng lên bởi thanh trạng thái/vết khía, khiến người dùng khó chạm vào TextField một cách chính xác","Bàn phím ảo sẽ không bao giờ xuất hiện","Ứng dụng sẽ không biên dịch"],"exp":"Việc thiếu SafeArea có nguy cơ khiến phần trên cùng của thanh tìm kiếm bị chồng lên bởi thanh trạng thái/vết khía, khiến TextField khó chạm chính xác. A, C, D không phản ánh rủi ro thực tế."},"PRM-210":{"q":"`FractionallySizedBox` trong danh sách widget đáp ứng được dùng để làm gì?","options":["Định cỡ widget dưới dạng phần trăm so với giá trị gốc widget của nó, thay vì giá trị pixel cố định","Chỉ được sử dụng cho hình ảnh động","Cắt các góc tròn trên widget","Không có chức năng thực sự, chỉ mang tính chất minh họa trong slide"],"exp":"FractionallySizedBox kích thước widget theo tỷ lệ phần trăm của cha mẹ thay vì pixel cố định. B, C, D mô tả sai chức năng của nó."},"PRM-211":{"q":"Cho trước: if (width < 600) return MobileView(); return TabletView(); Nếu logic điểm dừng này được đặt trong hàm `build()` của một phần tử con được lồng sâu widget bên trong nhiều lớp `Padding`/`Container` bị ràng buộc, nhưng `width` được lấy từ `MediaQuery.of(context).size.width` (chiều rộng toàn màn hình) thay vì `LayoutBuilder`, hậu quả tiềm ẩn là gì?","options":["Không có hậu quả gì cả vì Flutter tự động đồng bộ hóa","Quyết định phản hồi có thể sai: widget có thể chọn sai `TabletView` mặc dù không gian cục bộ thực tế mà nó có rất narrow (vì cha mẹ widgets đã hạn chế không gian), dẫn đến tràn hoặc bố cục không phù hợp","Ứng dụng sẽ luôn hiển thị chính xác MobileView bất kể màn hình of size","Đây là cách duy nhất được đề xuất để viết điều này trong mọi trường hợp"],"exp":"Việc sử dụng các ràng buộc MediaQuery width toàn màn hình thay vì of cục bộ LayoutBuilder có thể dẫn đến quyết định phản hồi sai và bố cục tràn/không phù hợp trong các ngữ cảnh lồng nhau. A, C, D không phù hợp với hệ quả thực tế."},"PRM-212":{"q":"Theo bảng \"Các loại bộ nhớ cục bộ trong Flutter\", trường hợp nào phù hợp nhất khi sử dụng SQLite (sqflite)?","options":["Lưu trữ cờ boolean \"quá trình cài đặt đã hoàn tất","Lưu trữ dữ liệu quan hệ có cấu trúc, e.g. một ứng dụng Todo có nhiều bản ghi cần truy vấn, lọc, sắp xếp","Chỉ lưu trữ chủ đề sáng/tối","Lưu trữ một chuỗi văn bản đơn giản không cần truy vấn"],"exp":"SQLite phù hợp nhất với dữ liệu quan hệ có cấu trúc cần truy vấn/bộ lọc/sắp xếp, như ứng dụng Todo. A, C, D phù hợp hơn với SharedPreferences hoặc một tệp đơn giản."},"PRM-213":{"q":"Loại dữ liệu nào KHÔNG được liệt kê làm ví dụ điển hình phù hợp với Bộ nhớ cục bộ trong \"Tại sao lại lưu trữ cục bộ?","options":["Cài đặt chế độ tối","Các mục đã xem gần đây","Phiên gọi điện video theo thời gian thực token (dữ liệu phát trực tuyến theo thời gian thực)","Đang giới thiệu flag (\"người dùng lần đầu?\")"],"exp":"Mã thông báo phiên cuộc gọi video theo thời gian thực KHÔNG được liệt kê dưới dạng ví dụ về Bộ nhớ cục bộ điển hình. A, B, D đều là những ví dụ được đề cập rõ ràng trong bài giảng."},"PRM-214":{"q":"Trong Lab 9 (Ứng dụng mini ngoại tuyến đầu tiên), SharedPreferences được đề xuất sử dụng cho phần nào của ứng dụng?","options":["Lưu trữ toàn bộ danh sách Todo có cấu trúc quan hệ","Lưu trữ chủ đề của ứng dụng state (Chế độ Tối/Sáng)","Lưu trữ tệp JSON xuất/nhập dữ liệu","Lưu trữ dữ liệu quan hệ nhiều bảng"],"exp":"SharedPreferences được đề xuất để lưu trữ chủ đề của ứng dụng state (Chế độ tối/sáng) trong Lab 9. A, C, D phù hợp hơn với tệp SQLite/JSON."},"PRM-215":{"q":"Theo \"Kỹ thuật tối ưu hóa 3: Tránh làm việc nặng nhọc trong build()\", điều nào sau đây KHÔNG nên được thực hiện trực tiếp bên trong hàm `build()`?","options":["Trả về một `Text` widget đơn giản","Gọi API, phân tích cú pháp JSON, sắp xếp danh sách hoặc thực hiện các phép tính phức tạp","Trả về một `Column` chứa một vài con tĩnh widgets","Đọc một giá trị từ MediaQuery"],"exp":"KHÔNG nên thực hiện việc gọi API, phân tích cú pháp JSON, sắp xếp hoặc tính toán phức tạp bên trong build(). A, C, D là các hoạt động bình thường, chi phí thấp và không gây ra vấn đề đáng kể về hiệu suất trong build()."},"PRM-216":{"q":"`AnimationController` cần tham số bắt buộc nào để hoạt động, minh họa mối liên hệ giữa hoạt ảnh và widget lifecycle?","options":["`context` --- vì hoạt ảnh phải được gắn với BuildContext","`vsync` --- thường được cung cấp bởi `TickerProviderStateMixin`, để đồng bộ hóa hoạt ảnh với các khung được hiển thị và tránh lãng phí tài nguyên khi không hiển thị widget","`theme` --- để hoạt ảnh áp dụng đúng màu","`key` --- để có thể kiểm tra hoạt ảnh"],"exp":"`vsync` (thường từ TickerProviderStateMixin) đồng bộ hóa hoạt ảnh với khung hiển thị, tránh lãng phí tài nguyên khi không hiển thị. A, C, D không phải là tham số bắt buộc của AnimationController."},"PRM-217":{"q":"Material và Cupertino chủ yếu cung cấp những gì ở Flutter?","options":["Hai công cụ kiểm tra","Hai loại cơ sở dữ liệu cục bộ","Hai state hệ thống quản lý","Bộ UI widget tuân theo kiểu thiết kế Android và iOS"],"exp":"Tùy chọn D đúng: các bộ UI widget tuân theo kiểu thiết kế Android và iOS. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-218":{"q":"Tại sao các ngoại lệ tùy chỉnh lại hữu ích?","options":["Họ trực tiếp tăng FPS","Chúng thay thế Provider","Chúng cung cấp bối cảnh lỗi theo miền cụ thể thay vì các chuỗi lỗi chung","Chúng tự động làm cho UI phản hồi"],"exp":"Tùy chọn C đúng: Chúng cung cấp ngữ cảnh lỗi theo miền cụ thể thay vì chuỗi lỗi chung. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-219":{"q":"Phản hồi UI là gì?","options":["UI luôn sử dụng pixel cố định","Bố cục chỉ thay đổi theo hệ điều hành","Một UI chỉ thay đổi màu chủ đề của nó","Bố cục thay đổi theo không gian có sẵn"],"exp":"Tùy chọn D đúng: Bố cục thay đổi theo không gian có sẵn. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-220":{"q":"UI thích ứng là gì?","options":["Bố cục chỉ thay đổi theo chiều rộng của cha mẹ","Bố cục chỉ sử dụng SafeArea","Bố cục chỉ sử dụng GridView","Bố cục hoặc thành phần thay đổi tùy theo loại thiết bị hoặc nền tảng"],"exp":"Tùy chọn D đúng: Bố cục hoặc thành phần thay đổi tùy theo loại thiết bị hoặc nền tảng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-221":{"q":"Ví dụ nào là hành vi đáp ứng?","options":["Thay thế BottomNavigationBar bằng NavigationRail vì thiết bị là máy tính bảng","Thay đổi lưới từ hai cột thành bốn cột khi màn hình rộng hơn","Sử dụng Material trên Android và Cupertino trên iOS","Sử dụng xác thực Firebase"],"exp":"Tùy chọn B đúng: Thay đổi lưới từ hai cột thành bốn cột khi màn hình rộng hơn. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-222":{"q":"Ví dụ nào là hành vi thích ứng?","options":["Tăng phần đệm theo chiều rộng","Cho phép chip tự động bọc","Sử dụng AspectRatio cho hình ảnh","Thay thế điều hướng phía dưới bằng NavigationRail trên máy tính bảng"],"exp":"Tùy chọn D đúng: Thay thế điều hướng phía dưới bằng NavigationRail trên máy tính bảng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-223":{"q":"Biểu thức nào lấy được chiều rộng màn hình thông qua MediaQuery?","options":["Screen.getWidth()","MediaQuery.of(ngữ cảnh).size.width","context.width.database","LayoutBuilder.width() không có trình tạo"],"exp":"Tùy chọn B đúng: MediaQuery.of(ngữ cảnh).size.width. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-224":{"q":"OrientationBuilder phát hiện những gì?","options":["Chủ đề sáng hoặc tối","Hướng dọc hoặc ngang","Mã thông báo đã hết hạn hay chưa","Cho dù thiết bị đang trực tuyến hay ngoại tuyến"],"exp":"Tùy chọn B đúng: Hướng dọc hoặc hướng ngang. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-225":{"q":"Sự khác biệt giữa mũi tên function (`=>`) và hàm block (`{ return ...; }`) trong Dart là gì?","options":["Hàm mũi tên chỉ có thể được sử dụng cho hàm async","Hàm mũi tên là cách viết tắt của hàm có một biểu thức return duy nhất, trong khi khối hàm cho phép nhiều câu lệnh","Hai cú pháp có ý nghĩa hoàn toàn khác nhau về loại return","Hàm mũi tên không được phép lấy tham số"],"exp":"Hàm mũi tên là cách viết tắt của một biểu thức đơn return; khối chức năng cho phép nhiều câu lệnh. A, C, D không phù hợp với đặc điểm của cú pháp này."},"PRM-226":{"q":"Hãy xem xét mã này và dự đoán kết quả: Future`<String>` fetchData() async { await Future.delayed(Duration(seconds: 1)); return \"Data loaded\"; } void main() { print(\"Start\"); fetchData().then((value) => print(value)); print(\"End\"); } Thứ tự nào được in ra bảng điều khiển?","options":["Start, Data loaded, End","Start, End, Data loaded","Data loaded, Start, End","Start, End (không bao giờ in \"Data loaded\")"],"exp":"Vì `fetchData()` không được chờ đợi trong `main()` nên nó không chặn mã tiếp theo --- `.then()` là không chặn, vì vậy \"Start\", \"End\" print trước tiên và sau 1 giây \"Data loaded\" sẽ in. A, C xếp sai thứ tự; D sai vì Data loaded cuối cùng cũng được in ra."},"PRM-227":{"q":"Hãy xem xét lớp Sinh viên và phòng thí nghiệm nhỏ: class Student { String name; Student(this.name); } void main() async { var list = [Student(\"An\"), Student(\"Binh\")]; await Future.delayed(Duration(seconds: 1)); list.forEach((s) => print(s.name)); } Nếu từ khóa `await` trước `Future.delayed(...)` bị xóa, điều gì sẽ xảy ra?","options":["Chương trình sẽ hiển thị lỗi biên dịch do thiếu await","`forEach` vẫn in tên học sinh theo đúng thứ tự nhưng có thể chạy trước độ trễ 1 giây finishes (vì nó không còn đợi Future hoàn thành nữa), vì `Future.delayed` không có await chỉ đơn thuần là \"bắt đầu\" mà không chặn việc thực thi","Chương trình sẽ gặp sự cố vì Future không được xử lý","Thứ tự list của học sinh sẽ bị đảo ngược"],"exp":"Không chờ `Future.delayed` cho phép `main()` tiếp tục thực thi các câu lệnh tiếp theo mà không cần đợi hết giây --- mặc dù `forEach` vẫn thực thi tên theo đúng thứ tự, nó có thể chạy trước \"độ trễ\" completes (không có tác dụng thực tế ở đây vì không có gì phụ thuộc vào độ trễ). A sai vì đây không phải là lỗi biên dịch; C sai vì nó không bị lỗi; D sai vì thứ tự name được giữ nguyên."},"PRM-228":{"q":"Cho bảng so sánh `extends`, `implements`, `with`, bảng nào mô tả đúng nhất về `implements`?","options":["Kế thừa tất cả các hành vi có sẵn từ lớp cha","Chỉ kế thừa \"chữ ký\" của lớp/giao diện, buộc bạn phải viết lại tất cả hành vi tùy chỉnh --- được sử dụng để xác định hợp đồng","Được sử dụng để chia sẻ các khối mã có thể tái sử dụng mà không có mối quan hệ kế thừa","Không được Dart hỗ trợ, chỉ tồn tại ở Java"],"exp":"`implements` chỉ lấy signature (giao diện), buộc bạn phải tự viết tất cả hành vi, được sử dụng như một hợp đồng. A mô tả `extends`; C mô tả `mixin`; D sai vì Dart hỗ trợ đầy đủ implements."},"PRM-229":{"q":"Mục đích chính đằng sau việc giới thiệu Mẫu Repository trong Mô-đun 3 là gì?","options":["Thay thế hoàn toàn Widget trong Flutter","Tách logic tìm nạp dữ liệu khỏi lớp trình bày/UI, giúp kiểm tra và bảo trì mã dễ dàng hơn, đồng thời tạo nền tảng cho Bloc/Provider/Riverpod","Chỉ sử dụng cho các ứng dụng không có UI","Sự thay thế cho SQLite"],"exp":"Mẫu Repository tách việc tìm nạp dữ liệu khỏi UI, hỗ trợ khả năng kiểm tra/bảo trì và tạo nền tảng cho Bloc/Provider/Riverpod. A, C, D mô tả sai mục đích của nó."},"PRM-230":{"q":"Với mã kho lưu trữ này bằng cách sử dụng Stream: Stream`<int>` counter() async { for (int i = 1; i <= 3; i++) { await Future.delayed(Duration(milliseconds: 300)); yield i; } } Khi Stream này được liên kết với `StreamBuilder(stream: repo.counter(), ...)`, UI sẽ hoạt động như thế nào?","options":["UI chỉ tạo một lần sau khi toàn bộ vòng lặp kết thúc","UI tự động xây dựng lại mỗi khi một giá trị mới được chỉnh sửa `yield`, tạo hiệu ứng cập nhật theo thời gian thực","StreamBuilder không hỗ trợ Luồng được tạo từ `async`","Ứng dụng sẽ freeze (chặn chuỗi UI) for trong 900 mili giây đầy đủ"],"exp":"UI tự động xây dựng lại mỗi khi có giá trị mới, tạo hiệu ứng cập nhật theo thời gian thực. A sai vì StreamBuilder được xây dựng lại cho mỗi sự kiện; C sai vì StreamBuilder hỗ trợ đầy đủ async*; D sai vì độ trễ không chặn toàn bộ luồng UI nhờ cơ chế async."},"PRM-231":{"q":"Đã cho: class _RadioScreenState extends State`<RadioScreen>` { String? quality = 'HD'; @override Widget build(BuildContext context) { return Column(children: [ RadioListTile`<String>`( title: const Text('SD'), value: 'SD', groupValue: quality, onChanged: (v) => setState(() => quality = v), ), RadioListTile`<String>`( title: const Text('HD'), value: 'HD', groupValue: quality, onChanged: (v) => setState(() => quality = v), ), ]); } } Nếu `setState()` bị xóa khỏi `onChanged` (chỉ giữ lại `quality = v`), điều gì sẽ xảy ra khi người dùng chạm vào 'SD'?","options":["Biến `quality` vẫn được cập nhật thành 'SD' nhưng UI không được xây dựng lại để phản ánh sự thay đổi, radio vẫn hiển thị như trước","Ứng dụng đưa ra lỗi thời gian chạy ngay lập tức","Nút radio tự động tạo lại vì Flutter luôn theo dõi mọi biến trong State","value của quality sẽ không thay đổi vì setState i"],"exp":"Không có setState, `quality` vẫn cập nhật trong bộ nhớ nhưng Flutter không biết cách xây dựng lại --- UI không hiển thị thay đổi nào. B sai vì không có lỗi thời gian chạy; C sai vì Flutter không tự động theo dõi mọi biến; D sai vì quality không thay đổi, chỉ có UI là không."},"PRM-232":{"q":"Mã này được sử dụng để chọn ngày: Future`<void>` pickDate() async { final date = await showDatePicker( context: context, initialDate: DateTime.now(), firstDate: DateTime(2000), lastDate: DateTime(2100), ); if (date != null) setState(() => selectedDate = date); } Tại sao cần kiểm tra `if (date != null)` trước khi gọi `setState`?","options":["Bởi vì `showDatePicker` luôn trả về null khi hoạt động chính xác","Bởi vì người dùng có thể hủy/loại bỏ hộp thoại bộ chọn date, trong trường hợp đó, Future trả về null và bạn không nên setState có giá trị null không mong muốn","Bởi vì đây là cú pháp Dart bắt buộc cho mọi hàm async","Bởi vì DateTime không bao giờ được phép là null trong Flutter"],"exp":"Việc kiểm tra null là cần thiết vì người dùng có thể hủy hộp thoại, khiến cho Future trả về null và bạn không nên setState với một null không mong muốn. A, C, D không khớp với lý do thực tế."},"PRM-233":{"q":"Trong ví dụ `HomeTabs`: class _HomeTabsState extends State`<HomeTabs>` { int index = 0; final screens = const [Center(child: Text('Home')), ...]; @override Widget build(BuildContext context) { return Scaffold( body: screens[index], bottomNavigationBar: BottomNavigationBar( currentIndex: index, onTap: (i) => setState(() => index = i), items: const [...], ), ); } } Nếu biến `index` không được giữ bên trong `StatefulWidget` (e.g. được khai báo trong StatelessWidget), điều gì sẽ xảy ra khi người dùng chạm vào một tab?","options":["Ứng dụng vẫn hoạt động bình thường vì StatelessWidget cũng hỗ trợ setState","Không thể gọi `setState` và UI không thể tự động cập nhật màn hình tương ứng khi người dùng chuyển tab, vì StatelessWidget không có cơ chế cho state nội bộ có thể thay đổi","Chương trình sẽ tự động chuyển sang sử dụng InheritedWidget","Không có gì khác biệt b"],"exp":"StatelessWidget không có setState nên không thể lưu trữ và cập nhật `index` state khi người dùng nhấn vào tab. A, C, D mô tả sai đặc điểm của StatelessWidget."},"PRM-234":{"q":"Trong danh sách \"Lỗi thường gặp và cách sửa chữa\" của Mô-đun 4, nguyên nhân phổ biến khiến UI \"không cập nhật\" sau khi thay đổi dữ liệu là gì?","options":["Lỗi mạng","Quên gọi `setState()` sau khi thay đổi giá trị của biến trong StatefulWidget","Thiếu Scaffold","Cú pháp nhập không chính xác"],"exp":"Quên gọi `setState()` là nguyên nhân phổ biến khiến UI không cập nhật, theo danh sách kiểm tra \"Lỗi thường gặp và cách khắc phục\". A, C, D không phải là nguyên nhân nêu trong bài giảng."},"PRM-235":{"q":"Sự khác biệt cơ bản giữa `StatelessWidget` và `StatefulWidget` là gì?","options":["StatelessWidget có thể thay đổi UI linh hoạt hơn StatefulWidget","StatelessWidget không chứa state nội bộ có thể thay đổi và không được xây dựng lại khi dữ liệu nội bộ thay đổi; StatefulWidget giữ state (đối tượng State) và có thể xây dựng lại thông qua `setState()`","Chỉ StatelessWidget có phương thức `build()`","StatefulWidget không được phép chứa con widgets"],"exp":"StatelessWidget không có state có thể thay đổi và không tự xây dựng lại; StatefulWidget giữ đối tượng State và xây dựng lại thông qua setState(). A, C, D mô tả sai đặc điểm cơ bản của hai loại widget."},"PRM-236":{"q":"Với mã CounterPage này bằng cách sử dụng `setState`: class _CounterPageState extends State`<CounterPage>` { int count = 0; void increment() { setState(() { count++; }); } ... } Nếu được thay thế bằng chỉ `count++;` MÀ KHÔNG gọi `setState()`, điều gì sẽ xảy ra?","options":["Giá trị của `count` vẫn tăng chính xác trong bộ nhớ, nhưng Flutter sẽ không biết cách tạo lại widget, do đó, count được hiển thị của UI không thay đổi","Ứng dụng đưa ra lỗi biên dịch ngay lập tức","UI vẫn tự động cập nhật vì Flutter luôn theo dõi mọi biến trong State","Giá trị count đặt lại về 0 mỗi lần xây dựng lại"],"exp":"Không có setState, count vẫn tăng bộ nhớ, nhưng Flutter không biết cách xây dựng lại --- UI hiển thị count không thay đổi. B sai vì không có lỗi biên dịch; C sai vì Flutter không tự động theo dõi mọi biến; D sai vì count không được đặt lại."},"PRM-237":{"q":"\"Nâng State lên\" có nghĩa là gì trong Flutter?","options":["Xóa tất cả state khỏi ứng dụng","Di chuyển state được chia sẻ lên tổ tiên chung widget để con widgets có thể truy cập và đồng bộ hóa dữ liệu, giảm logic trùng lặp","Di chuyển tất cả logic UI sang phía máy chủ","Chỉ áp dụng khi sử dụng Provider"],"exp":"Việc nâng State lên sẽ di chuyển state được chia sẻ lên một tổ tiên chung để giảm logic trùng lặp và cải thiện luồng dữ liệu. A, C, D mô tả sai khái niệm này."},"PRM-238":{"q":"`Provider` (ChangeNotifierProvider + Consumer) xây dựng trên nền tảng nào trong Flutter và nó mang lại lợi ích gì so với InheritedWidget đơn giản?","options":["Được xây dựng trên SQLite, giúp lưu trữ dữ liệu ngoại tuyến","Được xây dựng dựa trên InheritedWidget nhưng giảm mã nguyên mẫu, giúp việc chia sẻ và nghe state dễ dàng hơn nhiều","Không liên quan đến InheritedWidget chút nào","Provider chỉ hoạt động với kiểu dữ liệu String"],"exp":"Provider được xây dựng trên InheritedWidget nhưng giảm bớt bản soạn sẵn để chia sẻ/nghe state. A, C, D không phù hợp với nền tảng kỹ thuật thực tế của Provider."},"PRM-239":{"q":"Cho mã Provider này: class CounterModel with ChangeNotifier { int count = 0; void increment() { count++; notifyListeners(); } } Nếu dòng `notifyListeners();` bị xóa khỏi `increment()`, điều gì sẽ xảy ra?","options":["Chương trình hiển thị lỗi biên dịch","`count` vẫn tăng trong bộ nhớ, nhưng `Consumer<CounterModel>` widgets sẽ không được thông báo để xây dựng lại, vì vậy UI không hiển thị giá trị mới","`notifyListeners()` không có tác dụng gì với UI, đó chỉ là nhật ký nội bộ","Ứng dụng tự động gọi âm thầm notifyListeners() mỗi giây"],"exp":"Nếu không có notifyListeners(), count vẫn tăng bộ nhớ nhưng Consumer widgets không được thông báo để xây dựng lại --- UI không cập nhật. A, C, D mô tả sai hành vi này."},"PRM-240":{"q":"Trong phần \"Quản lý ứng dụng State\" với `ChangeNotifier`: class AppState extends ChangeNotifier { bool loggedIn = false; void login() { loggedIn = true; notifyListeners(); } } Tại sao việc tách state (đăng nhập/đăng xuất) thành lớp riêng của nó khỏi lớp UI được coi là tốt practice (theo ghi chú của người hướng dẫn)?","options":["Bởi vì Flutter yêu cầu điều này để biên dịch","Bởi vì sự tách biệt làm tăng khả năng kiểm tra và làm rõ kiến trúc của ứng dụng; UI chỉ cần lắng nghe những thay đổi thay vì tự quản lý logic nghiệp vụ","Bởi vì làm như vậy khiến ứng dụng chạy nhanh gấp đôi","Không có lý do cụ thể, chỉ là sở thích cá nhân của người hướng dẫn"],"exp":"Việc tách state cải thiện khả năng kiểm tra và độ rõ ràng của kiến trúc, cho phép UI chỉ lắng nghe thay vì quản lý logic nghiệp vụ. A, C, D không phải là lý do đúng/hợp lệ."},"PRM-241":{"q":"Theo Tóm tắt của Mô-đun 5, state kỹ thuật quản lý nào được đề cập, theo thứ tự từ cơ bản đến nâng cao hơn?","options":["Provider → Widget được kế thừa → setState","setState → Widget được kế thừa → Provider","Chỉ đề cập đến setState, không có kỹ thuật nào khác được đề cập","BLoC → Riverpod → GetX"],"exp":"Theo Tóm tắt, thứ tự từ cơ bản đến nâng cao là: setState → InheritedWidget → Provider. A đảo ngược thứ tự; C không đầy đủ; D không phải là trọng tâm của Mô-đun 5 (chỉ được đề cập ngắn gọn ở phần chuẩn bị trong Mô-đun 3)."},"PRM-242":{"q":"Trong Demo 8.3, khối `try/catch/finally` được sử dụng như sau: try { final response = await http.post(...); if (response.statusCode == 201) { setState(() => result = response.body); } else { throw Exception('Failed with status: \\${response.statusCode}'); } } catch (e) { setState(() => errorMessage = e.toString()); } finally { setState(() => isLoading = false); } Tại sao `setState(() => isLoading = false);` được đặt trong khối `finally` thay vì chỉ trong khối `try`?","options":["Không có sự khác biệt giữa việc đặt nó trong try hoặc finally","Để đảm bảo quá trình tải state luôn bị tắt cho dù yêu cầu thành công hay fails (ném một ngoại lệ), tránh việc nút bị \"kẹt\" vĩnh viễn khi tải state do lỗi","`finally` chạy trước `try`, vì vậy nó phải được đặt ở đó để chạy sớm hơn","Việc đặt nó vào finally sẽ khiến isLoading không bao giờ trở thành false"],"exp":"finally đảm bảo isLoading luôn bị tắt bất kể thành công hay thất bại, tránh việc tải state bị kẹt vĩnh viễn. A, C, D không khớp với vai trò/thứ tự thực hiện thực tế của finally."},"PRM-243":{"q":"Trong \"Những cạm bẫy phổ biến và các phương pháp hay nhất\" của Mô-đun 8, việc gọi một API trực tiếp bên trong `build()` được coi như thế nào?","options":["Một thực tiễn tốt nhất nên được áp dụng","Một cạm bẫy phổ biến cần tránh --- vì `build()` có thể được gọi nhiều lần, dẫn đến các lệnh gọi API lặp lại không kiểm soát được; thay vào đó bạn nên gọi API bằng `initState()`","Cách duy nhất để gọi API trong Flutter","Chỉ gây lỗi với POST, không ảnh hưởng tới GET"],"exp":"Gọi một API bên trong build() là một điều khó tránh vì build() có thể chạy lại nhiều lần; thay vào đó hãy gọi initState(). A, C, D không khớp với nội dung cạm bẫy đã nêu của bài giảng."},"PRM-244":{"q":"So sánh phân tích cú pháp `response.body` (JSON) trực tiếp trong hàm `build()` của widget với phân tích cú pháp trong một function riêng biệt (như `fetchPosts()` được gọi từ `initState()`). Tuyên bố nào là chính xác nhất về hiệu suất?","options":["Không có sự khác biệt về hiệu suất giữa hai phương pháp","Việc phân tích cú pháp JSON trong `build()` làm cho work (phân tích cú pháp) nặng được làm lại mỗi khi widget xây dựng lại --- điều này có thể xảy ra rất thường xuyên --- trong khi phân tích cú pháp trong hàm được gọi từ `initState()` (với kết quả được lưu trữ trong biến Future) chỉ xảy ra một lần cho mỗi lần tải dữ liệu","build() luôn chạy nhanh hơn initState() bất kể nội dung","Vị trí đặt mã không ảnh hưởng đến hiệu suất, chỉ tổ chức mã"],"exp":"Việc phân tích cú pháp trong build() lặp lại công việc nặng nhọc trong mỗi lần xây dựng lại, trong khi phân tích cú pháp một lần từ initState() (kết quả được lưu vào bộ nhớ đệm trong một Future) chỉ xảy ra một lần cho mỗi lần tải. A, C, D không khớp với phân tích hiệu suất thực tế."},"PRM-245":{"q":"Trong Luồng cấp cao tiêu chuẩn của SharedPreferences: \"Tải phiên bản bộ nhớ → Đọc giá trị hiện có → Cập nhật giá trị dựa trên hành động của người dùng → Lưu lại vào bộ nhớ → Làm mới UI.\" Nếu \"Làm mới UI\" step (e.g. gọi `setState()`) bị bỏ qua sau khi lưu giá trị mới thì điều gì sẽ xảy ra?","options":["Giá trị vẫn được lưu chính xác vào thiết bị storage (đúng trong lần khởi chạy ứng dụng tiếp theo), nhưng UI hiện tại sẽ không phản ánh thay đổi ngay lập tức cho đến khi quá trình xây dựng lại khác diễn ra","Giá trị sẽ không được lưu vào bộ nhớ nếu thiếu bước này","Ứng dụng sẽ tự động bị lỗi","SharedPreferences sẽ tự động gọi ngầm setState"],"exp":"Giá trị vẫn được lưu chính xác vào bộ nhớ nhưng UI hiện tại sẽ không phản ánh thay đổi cho đến khi quá trình xây dựng lại khác diễn ra. B, C, D không khớp với hành vi thực tế của SharedPreferences/Flutter."},"PRM-246":{"q":"Trong architecture của Ứng dụng nhiệm vụ (được sử dụng làm ví dụ chạy xuyên suốt Mô-đun 11), thành phần nào chịu trách nhiệm quản lý state trên toàn ứng dụng?","options":["TaskListScreen","TaskProvider","TaskRepository","main.dart"],"exp":"TaskProvider chịu trách nhiệm quản lý toàn bộ ứng dụng state trong kiến trúc của Taskly. A, C, D không phù hợp với trách nhiệm này."},"PRM-247":{"q":"Với mã \"trước khi tối ưu hóa\" này từ Demo 12.1: Widget build(BuildContext context) { final tasks = context.watch`<TaskProvider>`().tasks; return Column( children: [ InputRow(), // static Expanded( child: ListView.builder( itemCount: tasks.length, itemBuilder: (_, i) => ListTile( title: Text(tasks[i].title), trailing: Checkbox(...), ), ), ), ], ); } Tại sao việc sử dụng `context.watch<TaskProvider>()` ngay ở cấp cao nhất widget (bao gồm cả `InputRow` tĩnh) lại gây ra vấn đề về hiệu suất?","options":["Không có vấn đề gì cả, đây là cách viết được khuyên dùng","Bất kỳ thay đổi nào trong `TaskProvider` (dù chỉ là một thay đổi nhỏ đối với một tác vụ) đều khiến toàn bộ tác vụ gốc widget (bao gồm cả static `InputRow` không liên quan) phải xây dựng lại, gây lãng phí tài nguyên một cách không cần thiết","`context.watch` chỉ có thể được sử dụng trong StatelessWidget, gây ra lỗi biên dịch ở đây","Vấn đề duy nhất là đặt sai vị trí Expanded"],"exp":"Việc xem ở cấp cao nhất khiến ngay cả những static widgets không liên quan như InputRow phải xây dựng lại dựa trên bất kỳ thay đổi provider nào, gây lãng phí tài nguyên. A, C, D không phù hợp với vấn đề hiệu suất thực tế."},"PRM-248":{"q":"Giải pháp \"Sử dụng Bộ chọn để CHỈ xây dựng lại danh sách\" trong Bản trình diễn 12.1 mang lại lợi ích gì cho một `context.watch<T>()` đơn giản?","options":["Bộ chọn cho phép xây dựng lại chi tiết --- chỉ phần UI thực sự phụ thuộc vào việc xây dựng lại dữ liệu đã thay đổi, thay vì toàn bộ phần gốc widget như với watch phạm vi rộng","Bộ chọn và watch hoạt động hoàn toàn giống nhau khi xây dựng lại","Bộ chọn chỉ hoạt động với kiểu dữ liệu String","Bộ chọn khiến toàn bộ ứng dụng luôn được xây dựng lại bất kể có thay đổi gì không"],"exp":"Bộ chọn cho phép xây dựng lại chi tiết, chỉ xây dựng lại phần thực sự phụ thuộc vào dữ liệu đã thay đổi. B, C, D không phù hợp với hành vi/lợi ích thực sự của Selector."},"PRM-249":{"q":"Đưa ra: class _MyWidgetState extends State`<MyWidget>` with SingleTickerProviderStateMixin { late AnimationController _controller; @override void initState() { super.initState(); _controller = AnimationController( duration: const Duration(seconds: 2), vsync: this, )..repeat(); } @override void dispose() { _controller.dispose(); super.dispose(); } } Nếu nhà phát triển quên gọi `_controller.dispose()` trong `dispose()`, hậu quả có thể xảy ra nhất là gì?","options":["Không có hậu quả gì cả vì Dart tự động thu gom rác mọi đối tượng","`AnimationController` (đặc biệt là while `repeat()`-ing) vẫn tiếp tục chạy ngay cả sau khi widget bị xóa khỏi cây, gây rò rỉ bộ nhớ và lãng phí tài nguyên CPU","Ứng dụng gặp sự cố ngay lập tức khi widget được xử lý","Hoạt ảnh tự động dừng vì Flutter luôn theo dõi widget lifecycle"],"exp":"Việc quên dispose() sẽ khiến một AnimationController lặp lại chạy sau khi xóa widget, gây rò rỉ bộ nhớ và lãng phí CPU. A sai vì GC của Dart không thể thu thập đối tượng vẫn được tham chiếu bởi Mã đang hoạt động; C, D không khớp với hành vi thực tế của Flutter."},"PRM-250":{"q":"BLoC (Thành phần logic nghiệp vụ) là mẫu kiến ​​trúc quản lý state trong Flutter, dựa trên khái niệm cốt lõi nào?","options":["Cha mẹ widget truyền dữ liệu trực tiếp cho con widget thông qua hàm tạo","Luồng đầu vào là Sự kiện, luồng đầu ra là Trạng thái --- BLoC nhận Sự kiện, xử lý logic nghiệp vụ, sau đó phát ra State mới để UI nghe và cập nhật","Chỉ sử dụng SharedPreferences để lưu trữ state","Không có khái niệm cốt lõi, BLoC chỉ là tên gọi khác của setState"],"exp":"Khái niệm cốt lõi của BLoC: luồng đầu vào = Sự kiện, luồng đầu ra = Trạng thái, xử lý logic nghiệp vụ ở giữa. A, C, D mô tả sai bản chất cơ bản của BLoC."},"PRM-251":{"q":"Cho mã Cubit đơn giản này: class CounterCubit extends Cubit`<int>` { CounterCubit() : super(0); void increment() => emit(state + 1); } widget nào trong `flutter_bloc` nghe `CounterCubit` tốt nhất và tự động xây dựng lại UI bất cứ khi nào giá trị `state` thay đổi?","options":["`FutureBuilder`","`BlocBuilder<CounterCubit, int>`","`StreamController`","`InheritedWidget` (được sử dụng trực tiếp, không có thư viện)"],"exp":"`BlocBuilder<CounterCubit, int>` là flutter_bloc API chính xác để nghe Cubit và tự động xây dựng lại trên các thay đổi của state. A, C, D không phải là widget/API thích hợp cho mục đích này."},"PRM-252":{"q":"Theo triết lý thiết kế của mẫu BLoC, tại sao logic nghiệp vụ phải được tách biệt hoàn toàn khỏi UI widget?","options":["Bởi vì Flutter không cho phép viết logic bên trong widget","Để tăng testability (kiểm tra logic độc lập mà không cần xây dựng UI), hãy sử dụng lại logic trên các nền tảng/màn hình khác nhau và giữ cho widget tập trung vào hiển thị","Bởi vì BLoC chạy nhanh hơn nếu logic nằm trong widget","Không có lý do rõ ràng, đó chỉ là quy ước đặt tên"],"exp":"Việc phân tách làm tăng khả năng kiểm tra, cho phép sử dụng lại logic trên các nền tảng/màn hình và giúp widgets tập trung vào hiển thị. A, C, D mô tả sai mục đích của triết lý thiết kế này."},"PRM-253":{"q":"Hãy xem xét Tác vụ app (từ Mô-đun 12/11) được viết lại bằng kiến ​​trúc BLoC thay vì Provider: `TaskBloc` sẽ nhận được `AddTaskEvent` và `ToggleTaskEvent`, sau đó phát ra một `TaskState` mới. So với việc sử dụng `TaskProvider` (ChangeNotifier) như trong các trang trình bày gốc, điểm khác biệt cốt lõi trong quy trình xử lý là gì?","options":["Không có sự khác biệt nào cả, BLoC và Provider hoàn toàn giống nhau về cách chúng nhận các thay đổi từ UI","Với ChangeNotifier (Provider), UI gọi trực tiếp một phương thức trên Provider (e.g. `taskProvider.addTask(...)`) và Provider tự biến đổi rồi gọi `notifyListeners()`; với BLoC, UI phải \"gửi\" một Sự kiện object (e.g. `bloc.add(AddTaskEvent(...))`) vào luồng đầu vào và Bloc xử lý Sự kiện đó để phát ra một State mới, được tách hoàn toàn khỏi lệnh gọi trực tiếp","BLoC không thể được sử dụng để xây dựng ứng dụng Todo như Taskly","Provider được yêu cầu chỉ sử dụng Sự kiện"],"exp":"Provider sử dụng lệnh gọi phương thức trực tiếp + notifyListeners(); BLoC sử dụng các Sự kiện được gửi đi được xử lý thành các Trạng thái được phát ra, tách rời khỏi các cuộc gọi trực tiếp --- đây là điểm khác biệt cốt lõi của luồng. A, C, D không khớp với cách thức hoạt động thực sự của hai kiến ​​trúc."},"PRM-254":{"q":"Tại sao nhiều dự án Flutter trong thế giới thực chọn BLoC thay vì chỉ `setState` cho các ứng dụng quy mô lớn có nhiều màn hình chia sẻ phức tạp state?","options":["Vì `setState` không được Flutter hỗ trợ trong các ứng dụng lớn","BLoC phân tách rõ ràng luồng Sự kiện/State, giúp kiểm tra logic independently dễ dàng hơn (không cần xây dựng UI), dễ dàng theo dõi luồng dữ liệu một cách rõ ràng hơn và mở rộng quy mô tốt hơn khi nhiều màn hình cần chia sẻ và phản ứng với cùng một nguồn state phức tạp --- điều mà `setState` cục bộ gặp khó khăn khi ứng dụng phát triển","`setState` chỉ hoạt động với đúng 1 màn hình trong toàn bộ ứng dụng","BLoC luôn nhanh hơn setState về hiệu suất hiển thị tuyệt đối trong mọi trường hợp"],"exp":"Tính năng phân tách Sự kiện/{0}} rõ ràng của BLoC hỗ trợ khả năng kiểm tra độc lập, theo dõi luồng dữ liệu rõ ràng và mở rộng quy mô tốt hơn cho state phức tạp được chia sẻ trên nhiều màn hình. A, C, D không phù hợp với lý do thực tế khi chọn BLoC."},"PRM-255":{"q":"Mũi tên syntax (=>) phù hợp với loại hàm nào?","options":["Một nhà xây dựng nhà máy bắt buộc","Hàm không có tham số","Một hàm chứa một số khối thử/bắt","Một hàm bao gồm một biểu thức duy nhất"],"exp":"Lựa chọn D đúng: Một hàm bao gồm một biểu thức. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-256":{"q":"Khi nào chuỗi Future với then() hữu ích?","options":["Xác định lược đồ SQLite","Tạo nhiều chuỗi kế thừa","Vẽ cây widget","Xâu chuỗi các bước không đồng bộ mà không có khối async/await"],"exp":"Tùy chọn D đúng: Xâu chuỗi các bước không đồng bộ mà không có khối async/await. Dart sử dụng Future cho một kết quả không đồng bộ và Stream cho một chuỗi sự kiện không đồng bộ; async/await làm cho mã dựa trên Future dễ đọc hơn."},"PRM-257":{"q":"Từ khóa nào phát ra các giá trị từ hàm Stream-tạo ra async*?","options":["yield","notifyListeners","chỉ trả lại","emitWidget"],"exp":"Tùy chọn A đúng: yield. Dart sử dụng Future cho một kết quả không đồng bộ và Stream cho một chuỗi sự kiện không đồng bộ; async/await làm cho mã dựa trên Future dễ đọc hơn."},"PRM-258":{"q":"widget trong Flutter là gì?","options":["Một bảng SQL","Trình biên dịch","Một loại mã thông báo","Khối xây dựng cơ bản của giao diện người dùng"],"exp":"Tùy chọn D đúng: Khối xây dựng cơ bản của giao diện người dùng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-259":{"q":"Flutter là gì?","options":["Một ngôn ngữ lập trình mới được phát triển bởi Google","Bộ công cụ UI của Google để xây dựng các ứng dụng được biên dịch nguyên bản từ một cơ sở mã duy nhất","Một framework chỉ để xây dựng các ứng dụng web","Một hệ điều hành di động của Google"],"exp":"Flutter là bộ công cụ UI của Google để xây dựng các ứng dụng được biên dịch nguyên bản từ một cơ sở mã. (A sai vì Flutter không phải là ngôn ngữ; C sai vì Flutter là đa nền tảng, không chỉ web; D sai vì Flutter không phải là hệ điều hành.)"},"PRM-260":{"q":"Lớp nào của kiến ​​trúc Flutter được viết bằng C++ và sử dụng Skia để xử lý kết xuất, khả năng truy cập và bố cục văn bản?","options":["Lớp khung","Lớp động cơ","Lớp nhúng","Lớp Widget"],"exp":"Lớp Công cụ được viết bằng C++ và sử dụng Skia để hiển thị/khả năng truy cập/bố cục văn bản. Khung Layer (A) là lớp Dart phía trên nó; Embedder (C) xử lý việc tích hợp nền tảng; 'Widget Layer' (D) không phải là tên chính thức cho lớp kiến ​​trúc này."},"PRM-261":{"q":"Một công ty khởi nghiệp muốn xây dựng MVP một cách nhanh chóng, chạy trên cả Android và iOS, với đội ngũ phát triển hạn chế và không cần hiệu năng đồ họa cực cao. Theo bài giảng, tình huống này là:","options":["Không phù hợp với Flutter vì Flutter chỉ hỗ trợ Android","Sự phù hợp hợp lý cho Flutter vì nó phù hợp với mục tiêu rút ngắn thời gian tiếp thị và giảm chi phí phát triển","Phù hợp hơn với mã gốc thuần túy vì Flutter không hỗ trợ MVP","Hoàn thành tốt nhất ở Kotlin vì Flutter không được tối ưu hóa cho các ứng dụng thương mại"],"exp":"Bài giảng nêu rõ Flutter phù hợp với MVP, công ty khởi nghiệp, giảm chi phí và thời gian tiếp thị --- khớp chính xác với kịch bản này. A, C, D đều mâu thuẫn với nội dung bài giảng."},"PRM-262":{"q":"Flutter giao tiếp với features gốc (Camera, Bluetooth, NFC...) mà nó không hỗ trợ trực tiếp thông qua cơ chế nào?","options":["WebSocket","Kênh nền tảng","Còn lại API","Cầu FFI tự động"],"exp":"Flutter tích hợp với các tính năng gốc thông qua Kênh nền tảng. A, C, D không phải là cơ chế được đề cập trong bài giảng."},"PRM-263":{"q":"Theo dòng thời gian lịch sử phát triển được đề cập trong bài giảng, Flutter 2.0 (2021) đã bổ sung hỗ trợ nền tảng nào?","options":["Chỉ thêm Android hỗ trợ Wear","Web và Máy tính để bàn","Chỉ thêm hỗ trợ iOS","Chỉ thêm hỗ trợ watchOS"],"exp":"Flutter 2.0 (2021) đã thêm Web và hỗ trợ Máy tính để bàn theo dòng thời gian của bài giảng. A, C, D không trùng với các mốc đã nêu."},"PRM-264":{"q":"Theo bài giảng, khi nào nhóm phát triển nên cân nhắc sử dụng code gốc (Kotlin/Swift) thay vì Flutter thuần túy?","options":["Khi ứng dụng cần quyền truy cập phần cứng ở cấp độ rất thấp hoặc các yêu cầu nghiêm ngặt về UI/UX dành riêng cho nền tảng","Khi ứng dụng chỉ cần chạy trên một nền tảng Android đơn giản","Khi nhóm có ít kinh nghiệm với Kotlin/Swift","Khi ứng dụng chỉ hiển thị danh sách văn bản tĩnh"],"exp":"Bản gốc nên được xem xét để truy cập phần cứng ở cấp độ rất thấp hoặc nền tảng cụ thể nghiêm ngặt UI/UX --- khớp với 'Khi thích hợp phát triển bản địa hơn.' B, C, D là những trường hợp Flutter vẫn phù hợp hoặc không liên quan."},"PRM-265":{"q":"Cho bảng so sánh: Flutter (Dart, Native UI + Engine), React Native (JS, Bridge to Native), Native (Kotlin/Swift, Pure Native). Tuyên bố nào phân tích tốt nhất sự đánh đổi giữa ba cách tiếp cận này?","options":["Bản gốc luôn chậm hơn Flutter vì nó không có công cụ chuyên dụng","React Bản địa nhanh nhất vì không cần biên dịch","Flutter đạt được hiệu suất gần như gốc nhờ trình kết xuất riêng của nó engine (Skia) mà không cần cầu nối như React Gốc, trong khi Gốc đạt được hiệu suất tối đa nhưng mất đi lợi thế cơ sở mã chung","Cả ba đều tạo ra mã gốc thuần túy giống hệt nhau"],"exp":"Flutter đạt được hiệu suất gần như gốc thông qua công cụ Skia của chính nó mà không cần cầu nối như React Bản địa; Bản địa đạt được hiệu suất cao nhất nhưng mất cơ sở mã chung --- đây là sự đánh đổi chính xác trên mỗi bảng so sánh. A, B, D sai hoặc đơn giản hóa quá mức."},"PRM-266":{"q":"Cho trước: List`<int>` nums = [1, 2, 3, 4, 5]; var result = nums.map((e) => e * 2).where((e) => e > 4).toList(); print(result); Cái gì được in?","options":["[2, 4, 6, 8, 10]","[6, 8, 10]","[3, 4, 5]","[1, 2, 3, 4, 5]"],"exp":"`[1,2,3,4,5].map(x*2) = [2,4,6,8,10]`, rồi `.where(e>4) = [6,8,10]`. A chỉ hiển thị bước map; C, D không khớp với phép biến đổi."},"PRM-267":{"q":"Trong đoạn mã sau, nội dung nào được in ra bàn điều khiển? void main() { try { int result = 10 \\~/ 0; print(result); } catch (e) { print(\"Error: \\$e\"); } finally { print(\"Done\"); } }","options":["Error: ... rồi Done (chia số nguyên cho 0 ném ra IntegerDivisionByZeroException)","10, không in Done","Vô cực, Done","Chương trình bị treo hoàn toàn không có kết quả"],"exp":"Chia số nguyên cho 0 với `~/` ném `IntegerDivisionByZeroException`, bị `catch` bắt, in \"Error: ...\" rồi \"Done\" (finally luôn chạy). B, C sai vì xảy ra ngoại lệ; D sai vì catch xử lý lỗi nên chương trình không bị lỗi hoàn toàn."},"PRM-268":{"q":"Sự khác biệt giữa `for-in` và `forEach` khi lặp lại Danh sách trong Dart là gì?","options":["`for-in` không thể được sử dụng với List","`forEach` là cú pháp vòng lặp dựa trên chỉ mục cổ điển, trong khi `for-in` là hàm bậc cao hơn","`for-in` là cú pháp for lặp lại từng phần tử của bộ sưu tập, trong khi `forEach` gọi hàm gọi lại in kiểu lập trình chức năng for mỗi phần tử","Hai cú pháp này có hiệu suất và cú pháp in hoàn toàn giống nhau, không có sự khác biệt"],"exp":"`for-in` lặp lại từng phần tử bộ sưu tập; `forEach` là hàm bậc cao hơn lấy kiểu gọi lại in theo kiểu hàm. A sai vì for-in hoạt động với List; B đảo ngược mô tả; D sai vì có sự khác biệt về phong cách."},"PRM-269":{"q":"Hãy xem đoạn mã này minh họa Vòng lặp sự kiện của Dart: import 'dart:async'; void main() { print(\"A\"); scheduleMicrotask(() => print(\"micro\")); Future(() => print(\"future\")); print(\"B\"); } Thứ tự đầu ra đúng là gì?","options":["A, B, micro, future","A, micro, future, B","A, B, future, micro","micro, A, B, future"],"exp":"Các tác vụ vi mô có mức độ ưu tiên cao hơn hàng đợi Sự kiện nhưng vẫn chạy sau khi thực thi mã đồng bộ hiện tại: in \"A\", \"B\" (đồng bộ hóa trước), sau đó vi tác vụ \"micro\" chạy trước Future \"future\". Câu trả lời đúng: A, B, micro, future."},"PRM-270":{"q":"Cho mã Stream này: Stream`<int>` countUp() async { for (int i = 1; i <= 3; i++) { yield i; } } void main() async { await for (var value in countUp()) { print(value); } } Cái gì được in?","options":["1","1 2 3 (mỗi số nằm trên một dòng riêng)","3 2 1","Lỗi vì không cho phép `async` for hàm trả về Stream"],"exp":"Vòng lặp `async`/`yield` tạo thứ tự 1, 2, 3 in, mỗi thứ tự được in trên dòng riêng thông qua `await for`. A chỉ liệt kê một value; C đảo ngược thứ tự; D sai vì Dart hỗ trợ đầy đủ `async`."},"PRM-271":{"q":"Trong Dart, loại `Never` được dùng để làm gì?","options":["Một biến không bao giờ được gán giá trị","Hàm không bao giờ trả về normally (luôn ném ngoại lệ hoặc lặp vô hạn)","Kiểu dữ liệu tương đương với `void`","Một loại được sử dụng cho các chức năng không đồng bộ"],"exp":"`Never` được sử dụng cho các hàm không bao giờ trả về normally (luôn ném hoặc lặp vô hạn). A, C, D mô tả sai mục đích của loại Never."},"PRM-272":{"q":"Trong trường hợp chuyển đổi của Dart, tại sao thường cần `break` (hoặc `return`) sau mỗi trường hợp?","options":["Bởi vì mọi trường hợp không trống đều phải kết thúc bằng break/return/continue --- Dart cấm ngầm định rơi-through (không giống như C), nếu không thì đó là lỗi biên dịch","Vì Dart yêu cầu cú pháp này để biên dịch nên không liên quan đến hành vi","Vì break được dùng để thoát khỏi hàm chính","Dart không hỗ trợ trường hợp chuyển đổi"],"exp":"Các trường hợp chuyển đổi không trống trong Dart không bao giờ rơi vào implicitly (chỉ các trường hợp trống mới có chung nội dung); cú pháp bắt buộc phải có dấu kết thúc. B, C, D mô tả sai vai trò của break trong trường hợp chuyển đổi."},"PRM-273":{"q":"mixin được dùng để làm gì trong Dart?","options":["Thay thế hoàn toàn các hàm tạo","Chia sẻ hành vi trên nhiều lớp mà không cần chuỗi kế thừa truyền thống","Được sử dụng riêng cho việc xử lý JSON","Một loại biến đặc biệt trong Dart"],"exp":"mixin chia sẻ hành vi trên nhiều lớp mà không có chuỗi kế thừa truyền thống. A, C, D mô tả sai mục đích của mixin."},"PRM-274":{"q":"Hàm tạo gốc khác với hàm tạo thông thường trong Dart như thế nào?","options":["Một nhà xây dựng nhà máy luôn tạo một đối tượng hoàn toàn mới, không có ngoại lệ","Hàm tạo ban đầu cho phép kiểm soát việc tạo phiên bản --- nó có thể trả về một instance (cache/singleton) hiện có hoặc phân tích cú pháp data (JSON) thay vì luôn trả về một đối tượng mới","Một nhà xây dựng nhà máy không thể được đặt tên","Một hàm tạo của nhà máy chỉ có thể được sử dụng với một lớp trừu tượng"],"exp":"Trình xây dựng gốc kiểm soát việc tạo cá thể --- nó có thể trả về một cá thể hiện có hoặc phân tích dữ liệu, thay vì luôn tạo mới. A sai vì đây chính là sự khác biệt; C, D sai về cú pháp/phạm vi."},"PRM-275":{"q":"Cho trước: class User { final String name; factory User.fromJson(Map j) => User._(j['name']); User._(this.name); } Tại sao hàm tạo `User._` được tạo ra private (với `_`)?","options":["Bởi vì Dart yêu cầu mọi hàm tạo factory phải có một hàm tạo riêng đi kèm","Để ngăn mã bên ngoài class gọi trực tiếp hàm tạo thông thường, buộc sử dụng thông qua `User.fromJson` --- kiểm soát cách tạo đối tượng","Bởi vì `_` là quy ước đặt tên bắt buộc để phân tích cú pháp JSON","Không có lý do cụ thể, chỉ là lựa chọn phong cách mã hóa"],"exp":"Đặt hàm tạo ở chế độ riêng tư sẽ ngăn các cuộc gọi trực tiếp từ bên ngoài, buộc sử dụng thông qua `fromJson` --- kiểm soát việc tạo đối tượng. A, C, D không phải là lý do đúng/chính xác trong mẫu this factory."},"PRM-276":{"q":"Lợi ích chính mà generics (`List<T>`, `Future<T>`, `Map<K,V>`) mang lại Dart là gì?","options":["Làm cho chương trình chạy nhanh hơn trên CPU","Đảm bảo an toàn cho loại thời gian biên dịch, tránh lỗi sử dụng sai loại dynamic","Cho phép bỏ qua hoàn toàn việc khai báo kiểu dữ liệu","Chỉ hoạt động với types nguyên thủy (int, double)"],"exp":"Generics đảm bảo an toàn cho loại thời gian biên dịch, tránh các lỗi sử dụng sai loại dynamic. A, C, D mô tả sai lợi ích cốt lõi của thuốc generic."},"PRM-277":{"q":"Trong Dart, hàng đợi nào có mức độ ưu tiên CAO HƠN giữa hàng đợi Microtask và hàng đợi Sự kiện?","options":["Hàng đợi Sự kiện có mức độ ưu tiên cao hơn, luôn chạy trước hàng đợi Microtask","Hàng đợi Microtask có mức độ ưu tiên cao hơn --- tất cả các microtask chạy trước khi Dart tiếp tục xử lý Sự kiện queue (Tương lai, bộ tính giờ, sự kiện UI)","Cả hai chạy song song, không có thứ tự ưu tiên","Mức độ ưu tiên phụ thuộc vào thứ tự khai báo trong code, không cố định"],"exp":"Hàng đợi Microtask có mức độ ưu tiên cao hơn --- tất cả các microtask chạy trước khi Dart chuyển sang hàng đợi Sự kiện. A đảo ngược điều này; C, D không khớp với cơ chế vòng lặp sự kiện của Dart."},"PRM-278":{"q":"Cho mã chuỗi Future này: Future(() => 1) .then((v) => v + 1) .then((v) => print(v)); Giá trị nào được in?","options":["1","2","0","Không có gì được in vì thiếu await"],"exp":"`Future(()=>1).then((v)=>v+1).then((v)=>print(v))` → 1+1 = 2, in ra 2. A, C có giá trị sai; D sai vì mã vẫn thực thi mà không có await rõ ràng ở phần chính."},"PRM-279":{"q":"So sánh Future chaining (`.then()`) với `async/await`, nhận định nào chính xác nhất?","options":["`.then()` và `async/await` hoàn toàn không tương thích, không thể sử dụng cùng nhau trong dự án","`.then()` phù hợp với chuỗi async đơn giản mà không cần biến trung gian; `async/await` làm cho mã async được đọc tuyến tính, dễ theo dõi hơn khi có nhiều bước phụ thuộc","`async/await` chạy hoàn toàn đồng bộ, không còn không đồng bộ nữa","`.then()` luôn nhanh hơn `async/await` về mặt hiệu suất"],"exp":"`.then()` phù hợp với chuỗi đơn giản; `async/await` giúp mã đọc tuyến tính khi các bước phụ thuộc vào nhau. A sai vì chúng có thể được sử dụng cùng nhau; C sai vì async/await vẫn không đồng bộ; D không có cơ sở về hiệu suất tuyệt đối."},"PRM-280":{"q":"`StreamController.broadcast()` khác với gói đăng ký một lần mặc định Stream như thế nào?","options":["Broadcast chỉ cho phép chính xác một người nghe","Broadcast cho phép nhiều người nghe nghe đồng thời và nhận các sự kiện được chia sẻ, trong khi đăng ký một lần chỉ cho phép một người nghe, tiêu thụ tuần tự","Không có sự khác biệt thực sự, chỉ là một cái tên khác","Truyền phát chỉ hoạt động với loại dữ liệu String"],"exp":"Broadcast cho phép nhiều người nghe nhận các sự kiện được chia sẻ; đăng ký một lần chỉ cho phép một. A đảo ngược điều này; C, D không khớp với đặc điểm thực tế của hai loại Stream."},"PRM-281":{"q":"Cho mã StreamController.broadcast() này: var c = StreamController`<int>`.broadcast(); c.stream.listen((v) => print(\"A:$v\")); c.stream.listen((v) => print(\"B:$v\")); c..add(1)..add(2); Cái gì được in theo thứ tự?","options":["A:1, A:2, B:1, B:2","A:1, B:1, A:2, B:2","Chỉ A:1, A:2 được in vì trình nghe B không hoạt động","Lỗi vì StreamController.broadcast() không hỗ trợ nhiều trình nghe"],"exp":"Với `c..add(1)..add(2)`, mỗi add sẽ kích hoạt cả người nghe A và B trước add tiếp theo: A:1, B:1, A:2, B:2. A có thứ tự nhóm sai; C sai vì cả hai trình nghe đều hoạt động; D sai vì broadcast hỗ trợ đầy đủ nhiều trình nghe."},"PRM-282":{"q":"Theo phần \"Các phương pháp thực hành tốt nhất về hiệu suất\" của Mô-đun 3, phương pháp nào KHÔNG được khuyến nghị?","options":["Sử dụng const widgets để giảm chi phí xây dựng lại","Chạy một vòng lặp nặng trực tiếp trên isolate chính trong khi xây dựng UI","Sử dụng hàm async cho các thao tác I/O","Sử dụng Isolates cho các tác vụ CPU nặng"],"exp":"Chạy một vòng lặp nặng trực tiếp trên isolate chính trong khi xây dựng UI là phương pháp KHÔNG nên áp dụng done (ngược lại với phương pháp hay nhất). A, C, D đều là những phương pháp được khuyến nghị."},"PRM-283":{"q":"Trong Dart, điểm khác biệt cốt lõi giữa `abstract class` và `implicit interface` (mỗi lớp tự động có giao diện) là gì?","options":["Không có gì khác biệt, hai khái niệm này giống nhau","Một abstract class có thể chứa cả phương thức có nội dung và không có nội dung và không thể được khởi tạo trực tiếp; trong khi mọi class thông thường đều tự động xác định một implicit interface mà các lớp khác có thể `implements`","Giao diện chỉ tồn tại trong Java, Dart không có khái niệm như vậy","Các lớp trừu tượng luôn nhanh hơn các giao diện khi chạy"],"exp":"Tóm tắt class có thể kết hợp các phương thức có nội dung/không có nội dung và không thể được khởi tạo trực tiếp; mọi class thông thường đều tự động có implicit interface người khác có thể triển khai. A sai vì có sự khác biệt rõ ràng; C sai vì Dart có khái niệm này thông qua giao diện implicit; D không có cơ sở về hiệu suất thời gian chạy tuyệt đối."},"PRM-284":{"q":"Một học sinh viết Repository này: class Repo { Future`<String>` getUser() async { await Future.delayed(Duration(milliseconds: 300)); return \"Anna\"; } } and calls `var name = repo.getUser();` (without using `await`). Biến `name` sẽ có loại và giá trị gì tại thời điểm gán?","options":["Nhập ngay String, giá trị \"Anna\"","Nhập Future`<String>`, đối tượng Future vẫn \"đang chờ\" hoàn thành, chưa có giá trị String thực tế","Nhập dynamic, giá trị null","Lỗi biên dịch do thiếu await"],"exp":"Không có await, `name` có loại `Future<String>` --- một đối tượng Future đang chờ xử lý, chưa có giá trị String thực tế. A, C, D không khớp với hành vi của Future trong Dart."},"PRM-285":{"q":"Trong RadioListTile, vai trò của thuộc tính `groupValue` là gì?","options":["Xác định value của nút radio cụ thể đó","Giữ value hiện được chọn cho toàn bộ nhóm RadioListTiles, được sử dụng để so sánh với `value` của từng mục nhằm xác định state đã chọn","Không có tác dụng, hoàn toàn trang trí","Được sử dụng để đặt màu nền của RadioListTile"],"exp":"`groupValue` giữ value hiện được chọn cho cả nhóm, so với `value` của từng mục. A, C, D mô tả sai chức năng của nó."},"PRM-286":{"q":"Sự khác biệt giữa `Slider` và `Switch` trong Flutter là gì?","options":["Slider chọn một giá trị liên tục trong một phạm vi, Switch chỉ chuyển đổi giá trị boolean","Cả hai đều được sử dụng cho các giá trị boolean","Switch dành cho số thực, Slider dành cho boolean","Không có sự khác biệt về chức năng"],"exp":"Slider chọn một giá trị liên tục, Switch chỉ chuyển đổi boolean. B, C, D mô tả sai/đảo ngược hai hàm widgets'."},"PRM-287":{"q":"Trong ví dụ `showDatePicker`, tham số `firstDate` và `lastDate` được dùng để làm gì?","options":["Xác định ngày hiện tại mặc định","Hạn chế phạm vi ngày hợp lệ mà người dùng có thể chọn trên lịch","Không có hiệu lực thực sự, hoàn toàn là một tham số cú pháp bắt buộc","Xác định hiển thị ngày format (dd/mm/yyyy hoặc mm/dd/yyyy)"],"exp":"`firstDate`/`lastDate` hạn chế phạm vi ngày có thể chọn hợp lệ trên lịch. A, C, D mô tả sai chức năng của hai tham số này."},"PRM-288":{"q":"Trong bảng so sánh Không trạng thái/Trạng thái, ví dụ sử dụng nào phù hợp với StatelessWidget?","options":["Một biểu mẫu đầu vào có xác nhận","Bộ đếm tăng/giảm khi tương tác với người dùng","Logo tĩnh, văn bản không thay đổi","Danh sách có thể thêm/xóa các mục"],"exp":"Logo tĩnh/văn bản không thay đổi phù hợp với StatelessWidget vì không cần phải xây dựng lại. A, B, D đều yêu cầu StatefulWidget do thay đổi state."},"PRM-289":{"q":"Một học sinh quên bọc thanh tìm kiếm vào `SafeArea` trên thiết bị có rãnh khía. Hậu quả có thể xảy ra nhất trong thế giới thực là gì?","options":["Ứng dụng tự động bị treo ngay khi khởi động","Một phần khu vực trên cùng của thanh tìm kiếm có thể bị che khuất hoặc bị cắt bớt bởi thanh khía/trạng thái, gây hại cho trải nghiệm người dùng","GridView tự động chuyển bố cục của nó thành 2 cột","Không có tác dụng gì cả, SafeArea hoàn toàn mang tính thẩm mỹ và không cần thiết"],"exp":"Thiếu SafeArea có thể khiến phần trên cùng của thanh tìm kiếm bị che khuất/cắt bớt bởi thanh khía/trạng thái, gây hại cho UX. A, C, D không phản ánh hậu quả thực tế."},"PRM-290":{"q":"Khi nào bạn nên sử dụng `TextFormField` thay vì `TextField` đơn giản?","options":["Khi bạn không cần bất kỳ chức năng đặc biệt nào","Khi đầu vào cần nằm trong `Form` và cần chức năng xác thực","`TextFormField` chỉ có thể được sử dụng cho Web","Không có sự khác biệt giữa hai widgets"],"exp":"Sử dụng TextFormField khi dữ liệu đầu vào nằm trong Form và cần xác thực. A, C, D mô tả sai cách dùng."},"PRM-291":{"q":"`GlobalKey<FormState>` được dùng để làm gì trong `Form`?","options":["Chỉ được sử dụng để đặt màu của biểu mẫu","Cho phép truy cập và kiểm soát state của Form từ bên ngoài, e.g. gọi `validate()`, `save()`, `reset()` trên tất cả các trường trong biểu mẫu","Cú pháp bắt buộc nhưng không có tác dụng thực sự","Dùng để mã hóa dữ liệu đã nhập"],"exp":"GlobalKey`<FormState>` cho phép truy cập/điều khiển state của Form từ bên ngoài thông qua validate()/save()/reset(). A, C, D mô tả sai vai trò của nó."},"PRM-292":{"q":"Cho trước: void _submit() { final isValid = _formKey.currentState!.validate(); if (!isValid) return; _formKey.currentState!.save(); ScaffoldMessenger.of(context).showSnackBar( SnackBar(content: Text('Signed up as $_name ($_email)')), ); } Nếu đơn hàng được hoán đổi, gọi `_formKey.currentState!.save();` TRƯỚC KHI gọi `validate()`, điều gì có thể xảy ra?","options":["Không có gì khác biệt, thứ tự cuộc gọi không quan trọng","Dữ liệu không hợp lệ vẫn có thể được lưu vào state variables (`_name`, `_email`...) qua `onSaved`, vì save() bản thân nó không kiểm tra tính hợp lệ trước khi lưu --- validate() phải được gọi trước để đảm bảo chỉ dữ liệu đã kiểm tra mới được lưu","Ứng dụng sẽ hiển thị lỗi biên dịch","save() sẽ tự động gọi ngầm validate() trước khi lưu"],"exp":"Việc gọi save() trước validate() có nguy cơ lưu dữ liệu chưa được xác thực qua onSaved, vì save() không tự kiểm tra tính hợp lệ. A sai vì thứ tự rất quan trọng; C sai vì đây không phải là lỗi biên dịch; D sai vì save() không tự động gọi validate()."},"PRM-293":{"q":"Theo bài giảng, cạm bẫy phổ biến nào được nhấn mạnh đối với những sinh viên mới làm quen với Dart?","options":["Quên đóng dấu ngoặc nhọn của một lớp","Bỏ qua các cảnh báo an toàn rỗng và trộn mã đồng bộ/không đồng bộ không đúng cách","Sử dụng quá nhiều hàm async khiến việc thực thi song song không chính xác","Không thể tạo biến loại String"],"exp":"Những cạm bẫy phổ biến đã nêu: bỏ qua các cảnh báo an toàn rỗng và trộn mã đồng bộ/{0}} không đúng cách. A, C, D không phải là nội dung được nhấn mạnh trong bài giảng."},"PRM-294":{"q":"Hãy xem xét \"Nhiệm vụ thực hành\" của Mô-đun 4: xây dựng danh sách phim bằng cách sử dụng `ListView.builder` + `ListTile`, trong đó `onTap` cần hiển thị `SnackBar(title)`. Cách chính xác để gọi SnackBar trong Flutter là gì?","options":["`Text(title).showSnackBar()`","`ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(title)))`","`Navigator.of(context).showSnackBar(title)`","`SnackBar.show(context, title)`"],"exp":"`ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(title)))` là cách gọi đúng. A, C, D không phải là API Flutter hợp lệ."},"PRM-295":{"q":"Trong Flutter, `Navigator.push()` làm gì?","options":["Xóa toàn bộ ngăn xếp điều hướng","Adds (đẩy) tuyến đường/màn hình mới lên đầu ngăn xếp điều hướng","Quay lại màn hình trước đó","Đóng ứng dụng"],"exp":"`Navigator.push()` đẩy tuyến đường mới lên đầu ngăn xếp điều hướng. A, C, D mô tả sai chức năng của phương pháp này."},"PRM-296":{"q":"Phương thức `Navigator.pop(context)` làm gì?","options":["Đẩy một màn hình mới khác vào ngăn xếp","Removes (bật lên) màn hình hiện ở đầu ngăn xếp, hiển thị màn hình bên dưới nó","Thay thế toàn bộ ngăn xếp bằng một tuyến đường mới","Khởi động lại ứng dụng từ đầu"],"exp":"`Navigator.pop(context)` xóa màn hình trên cùng khỏi ngăn xếp, hiển thị màn hình bên dưới. A, C, D mô tả sai hành vi này."},"PRM-297":{"q":"Sự khác biệt giữa `Navigator.push()` và `Navigator.pushReplacement()` là gì?","options":["Không có sự khác biệt","`push()` thêm tuyến mới lên trên one hiện tại (tuyến cũ vẫn ở trong ngăn xếp), trong khi `pushReplacement()` thay thế tuyến hiện tại bằng one mới (tuyến cũ bị xóa khỏi ngăn xếp)","`pushReplacement()` chỉ có thể được sử dụng với các tuyến đường được đặt tên","`push()` không cho phép quay lại bằng nút quay lại"],"exp":"`push()` giữ tuyến đường cũ trong ngăn xếp; `pushReplacement()` xóa tuyến đường cũ khi thêm tuyến đường mới. A sai vì có sự khác biệt rõ ràng; C, D là các đặc tính kỹ thuật không chính xác."},"PRM-298":{"q":"Trong luồng đăng nhập, nhà phát triển sử dụng `Navigator.pushReplacementNamed(context, '/home')` thay vì `Navigator.pushNamed(context, '/home')` sau khi đăng nhập thành công. Lý do hợp lý nhất cho sự lựa chọn này là gì?","options":["`pushReplacementNamed` chạy nhanh hơn về mặt hiệu suất","Nó ngăn người dùng nhấn Quay lại để quay lại màn hình Đăng nhập sau khi đăng nhập thành công, vì tuyến Đăng nhập đã bị xóa khỏi ngăn xếp","`pushNamed` không hỗ trợ truyền tham số","Không có sự khác biệt thực sự giữa hai cuộc gọi"],"exp":"`pushReplacementNamed` ngăn việc quay lại Đăng nhập qua Quay lại do tuyến Đăng nhập bị xóa khỏi ngăn xếp. A, C, D không phải là lý do đúng."},"PRM-299":{"q":"Các tuyến đường được đặt tên trong Flutter mang lại lợi ích gì khi gọi trực tiếp `MaterialPageRoute` ở mọi nơi?","options":["Các tuyến được đặt tên chạy nhanh hơn khi chạy","Chúng tăng khả năng đọc và khả năng mở rộng trong các ứng dụng lớn, đặc biệt khi các tham số cần được thông qua hoặc nhiều màn hình cần quản lý tập trung","Tuyến đường được đặt tên là cách duy nhất Flutter hỗ trợ điều hướng","Các tuyến đường được đặt tên chỉ hoạt động với Navigator 2.0"],"exp":"Các tuyến được đặt tên cải thiện khả năng đọc và khả năng mở rộng trong các ứng dụng lớn, đặc biệt là đối với việc truyền tham số và quản lý màn hình tập trung. A, C, D không phù hợp với lợi ích thực tế."},"PRM-300":{"q":"Sự khác biệt cốt lõi giữa Navigator 1.0 và Navigator 2.0 là gì?","options":["Navigator 1.0 sử dụng mô hình khai báo, Navigator 2.0 sử dụng mô hình mệnh lệnh","Navigator 1.0 là bắt buộc --- gọi thủ công push()/pop(); Navigator 2.0 mang tính khai báo --- mô tả ngăn xếp mong muốn state và để khung tự động đồng bộ hóa","Cả hai đều hoàn toàn giống nhau, chỉ có tên khác nhau trên các phiên bản Flutter","Navigator 2.0 không hỗ trợ liên kết sâu, chỉ có Navigator 1.0 mới hỗ trợ"],"exp":"Navigator 1.0 là imperative (đẩy/bật thủ công); Navigator 2.0 là declarative (mô tả ngăn xếp mong muốn, đồng bộ hóa khung). A đảo ngược điều này; C, D không phù hợp với đặc điểm của hai phiên bản."},"PRM-301":{"q":"Ba thành phần chính trong kiến ​​trúc của Navigator 2.0 như đã đề cập trong bài giảng là gì?","options":["Router, Bộ điều khiển, Chế độ xem","RouterDelegate, RouteInformationParser, BackButtonDispatcher","Navigator, Tuyến đường, Ngăn xếp","Provider, Người tiêu dùng, ChangeNotifier"],"exp":"Ba thành phần chính: RouterDelegate, RouteInformationParser, BackButtonDispatcher --- khớp với slide. A, C, D không phải là tên chính xác của các thành phần này."},"PRM-302":{"q":"Liên kết sâu trong Flutter cho phép điều gì?","options":["Tăng tốc độ xây dựng ứng dụng","Cho phép người dùng trực tiếp mở một màn hình cụ thể trong ứng dụng thông qua URL hoặc source bên ngoài (e.g. liên kết web hoặc thông báo)","Chỉ áp dụng cho các ứng dụng chạy trên Web","Một tính năng thay thế hoàn toàn SharedPreferences"],"exp":"Liên kết sâu cho phép người dùng mở một màn hình cụ thể trực tiếp thông qua URL/nguồn bên ngoài. A, C, D mô tả sai mục đích của liên kết sâu."},"PRM-303":{"q":"Với mã `InheritedWidget` này: class AppData extends InheritedWidget { final String theme; const AppData({required this.theme, required Widget child, Key? key}) : super(key: key, child: child); static AppData of(BuildContext context) => context.dependOnInheritedWidgetOfExactType`<AppData>`()!; } Mục đích chính của `InheritedWidget` trong ví dụ này là gì?","options":["Chỉ được sử dụng để xác định tuyến đường điều hướng","Truyền dữ liệu xuống tất cả child widgets một cách hiệu quả trong cây widget mà không cần truyền tham số theo cách thủ công qua mọi hàm tạo trung gian","Thay thế hoàn toàn Scaffold","Chỉ được sử dụng để lưu trữ dữ liệu ngoại tuyến"],"exp":"InheritedWidget truyền dữ liệu xuống cây widget một cách hiệu quả mà không cần chuyển qua mọi cấp độ hàm tạo theo cách thủ công. A, C, D mô tả sai mục đích của nó."},"PRM-304":{"q":"Trong mã này kết hợp Điều hướng và State: if (appState.loggedIn) Navigator.pushNamed(context, '/dashboard'); else Navigator.pushNamed(context, '/login'); Mã này minh họa nguyên tắc gì?","options":["State hoàn toàn riêng biệt và không liên quan đến điều hướng","Ứng dụng state xác định luồng điều hướng --- kết hợp logic quản lý state với quyết định hiển thị tuyến đường nào","Đây là mã không chính xác vì không thể sử dụng if/else với Navigator","Chỉ hoạt động khi sử dụng Navigator 2.0"],"exp":"Điều này minh họa state việc xác định luồng điều hướng, kết hợp logic state với các quyết định về tuyến đường. A, C, D mô tả sai ý nghĩa/tính hợp lệ của mã này."},"PRM-305":{"q":"Trong Navigator 2.0, đoạn mã sau minh họa vai trò của thành phần nào? class AppRouterDelegate extends RouterDelegate`<AppRoute>` with ChangeNotifier, PopNavigatorRouterDelegateMixin`<AppRoute>` { @override Widget build(BuildContext context) { return Navigator( pages: [MaterialPage(child: HomePage())], onPopPage: (route, result) => route.didPop(result), ); } }","options":["RouteInformationParser --- chịu trách nhiệm phân tích cú pháp URL","RouterDelegate --- chịu trách nhiệm xây dựng trang hiện tại stack (`pages`) và xử lý các sự kiện bật lên, phản ánh điều hướng mong muốn state","BackButtonDispatcher --- chỉ xử lý nút quay lại vật lý Android","Đây chỉ là một StatelessWidget thông thường không liên quan đến điều hướng"],"exp":"Mã này minh họa RouterDelegate --- xây dựng ngăn xếp trang hiện tại và xử lý các sự kiện bật lên. A, C, D gán sai vai trò cho một thành phần Navigator 2.0 khác."},"PRM-306":{"q":"Trong ví dụ về Biểu ngữ anh hùng MovieDetailPage: Stack( trẻ em: [ Image.network(movie.posterUrl, fit: BoxFit.cover), Positioned(bottom: 0, child: Container(height: 80, trang trí: gradient)), ], ) Tại sao `Stack` được sử dụng thay vì `Column` ở đây?","options":["Bởi vì Stack chạy nhanh hơn Column","Bởi vì Stack cho phép con widgets chồng lên nhau ở cùng một vị trí, nên cần đặt một lớp chuyển màu lên hình ảnh áp phích","Bởi vì Column không hỗ trợ Image.network","Không có gì khác biệt, hai widgets hoàn toàn tương đương"],"exp":"Stack cho phép các phần tử con chồng lên nhau, cần thiết để tạo lớp chuyển màu trên hình ảnh áp phích. A, C, D không phù hợp với lý do kỹ thuật của lựa chọn này."},"PRM-307":{"q":"Trong luồng xử lý deep link qua `onGenerateRoute`, mục đích chính của lệnh gọi lại này trong `MaterialApp` là gì?","options":["Chỉ xử lý lỗi mạng","Cho phép ứng dụng phân tích cú pháp tuyến đường name (và các tham số) đến từ một liên kết bên ngoài, sau đó trả về động tuyến đường/màn hình tương ứng, thường được sử dụng để xử lý deep links","Thay thế hoàn toàn Scaffold","Chỉ hoạt động khi ứng dụng ngoại tuyến"],"exp":"`onGenerateRoute` phân tích tên/tham số tuyến đường từ một liên kết bên ngoài và tự động trả về màn hình tương ứng, thường là cho deep links. A, C, D mô tả sai mục đích của nó."},"PRM-308":{"q":"Lớp `Route` trong Flutter đại diện cho điều gì?","options":["Điểm cuối API từ máy chủ","Một màn hình/trang trong ứng dụng, thường được triển khai thông qua `MaterialPageRoute`","Một loại hoạt hình","Cấu trúc dữ liệu JSON"],"exp":"`Route` đại diện cho một màn hình/trang trong ứng dụng, thường được triển khai thông qua MaterialPageRoute. A, C, D mô tả sai khái niệm Route."},"PRM-309":{"q":"Hãy xem xét yêu cầu: \"Chạm vào bên ngoài biểu mẫu → ẩn bàn phím.\" Phương pháp thực hiện phổ biến được đề cập trong bài giảng là gì?","options":["Gọi `Navigator.pop(context)` khi người dùng chạm ra ngoài","Bao bọc biểu mẫu trong một `GestureDetector` với `onTap` gọi `FocusScope.of(context).unfocus()` (ẩn bàn phím khi chạm vào bên ngoài trường nhập)","Việc này không thể thực hiện được trong Flutter","Bàn phím chỉ có thể ẩn đi bằng nút Back vật lý"],"exp":"Gói biểu mẫu bằng cách GestureDetector gọi FocusScope.of(context).unfocus() khi nhấn là cách triển khai phổ biến. A, C, D không phù hợp với cách tiếp cận tiêu chuẩn được dạy."},"PRM-310":{"q":"Cho trước: Future`<void>` fetchPosts() async { final url = Uri.parse('https://jsonplaceholder.typicode.com/posts'); final response = await http.get(url); if (response.statusCode == 200) { print('Response body: \\${response.body}'); } else { print('Request failed: \\${response.statusCode}'); } } Tại sao hàm này cần được khai báo `async` và sử dụng `await` trước `http.get(url)`?","options":["Vì `http.get()` luôn chạy đồng bộ nên async là bắt buộc","Vì `http.get()` trả về `Future<Response>` --- thao tác mạng không hoàn thành ngay lập tức, nên `await` tạm dừng thực thi hàm cho đến khi có response, tránh chặn luồng UI trong khi chờ đợi","`async`/`await` hoàn toàn là cú pháp trang trí và không ảnh hưởng đến hành vi","Bởi vì Dart không hỗ trợ gọi hàm không đồng bộ mà không có async"],"exp":"`http.get()` trả về Future`<Response>`; await tạm dừng thực thi cho đến khi hoàn thành, tránh chặn luồng UI. A, C, D mô tả sai lý do thực sự về mặt kỹ thuật."},"PRM-311":{"q":"Trong Demo 8.2, khi người dùng nhấn vào một mục trong danh sách bài đăng để mở màn hình chi tiết, bài đăng data (`Post`) được chuyển đến `PostDetailScreen` như thế nào?","options":["Gọi lại API để tải riêng dữ liệu chi tiết","Truyền trực tiếp đối tượng `Post` đã có sẵn thông qua hàm tạo của `PostDetailScreen` khi điều hướng qua `MaterialPageRoute`","Lưu nó vào SharedPreferences rồi đọc lại trên màn hình chi tiết","Sử dụng biến toàn cục để chia sẻ dữ liệu"],"exp":"Đối tượng Post được truyền trực tiếp qua hàm tạo của PostDetailScreen trong khi điều hướng qua MaterialPageRoute, theo mã Demo 8.2. A, C, D không khớp với cách triển khai thực tế của bản demo."},"PRM-312":{"q":"Giả sử một học sinh viết: Future<List`<Post>`> fetchPosts() async { final response = await http.get(url); final List`<dynamic>` jsonList = json.decode(response.body); return jsonList.map((e) => Post.fromJson(e)).toList(); } but does NOT check `response.statusCode` before decoding. Nếu máy chủ trả về lỗi 500 với non-valid-JSON content (e.g. một trang lỗi HTML), điều gì có nhiều khả năng xảy ra nhất?","options":["App vẫn hiển thị danh sách bài viết bình thường","`json.decode()` sẽ gửi `FormatException` vì nội dung được trả về không hợp lệ JSON, khiến `Future` bị lỗi, cần xử lý thông qua `catch` hoặc `snapshot.hasError` trong FutureBuilder","Máy chủ sẽ tự động gửi lại response được định dạng chính xác","Dart sẽ tự động bỏ qua lỗi và return danh sách trống"],"exp":"json.decode() ném FormatException vào nội dung không phải JSON, gây lỗi Future, yêu cầu xử lý catch/snapshot.hasError. A, C, D không khớp với hành vi thực tế của json.decode() đối với dữ liệu nhập không hợp lệ."},"PRM-313":{"q":"Theo \"Các phương pháp & mẫu xác thực tốt nhất\", tại sao `pushReplacementNamed()` được khuyến nghị hơn `pushNamed()` khi di chuyển từ màn hình Splash/Đăng nhập về Trang chủ sau khi xác thực thành công?","options":["Vì `pushReplacementNamed()` chạy nhanh hơn ở tốc độ CPU","Để ngăn người dùng nhấn Quay lại để quay lại màn hình Splash hoặc Đăng nhập đã phục vụ mục đích của nó, tránh điều hướng phi logic experience (đăng nhập → quay lại → đăng nhập lại)","Vì `pushNamed()` không hỗ trợ các tuyến đường được đặt tên","Không có sự khác biệt thực sự giữa hai phương pháp trong bối cảnh này"],"exp":"pushReplacementNamed() ngăn việc quay lại màn hình Splash/Đăng nhập đã hoàn tất thông qua Quay lại, tránh điều hướng phi logic. A, C, D không khớp với lý do thực tế."},"PRM-314":{"q":"Từ khóa with thường được dùng với cái gì?","options":["Người xây dựng nhà máy","Các tuyến đường được đặt tên","Mixins","FutureBuilder"],"exp":"Tùy chọn C đúng: Mixins. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-315":{"q":"Địa chỉ mixin cần gì?","options":["Tạo tuyến đường khai báo","Tái sử dụng hành vi giữa các lớp mà không yêu cầu mối quan hệ thừa kế","Lưu trữ dữ liệu quan hệ","Thay thế ứng dụng khách HTTP"],"exp":"Tùy chọn B đúng: Sử dụng lại hành vi giữa các lớp mà không yêu cầu mối quan hệ kế thừa. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-316":{"q":"Trong Ô`<T>`, T đại diện cho điều gì?","options":["Một Future cố định","Tên của một biến toàn cục","Tên tuyến đường","Một tham số loại chung"],"exp":"Tùy chọn D đúng: Tham số loại chung. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-317":{"q":"Hai hàng đợi chính nào được mô tả trong công cụ không đồng bộ của Dart?","options":["Kết xuất hàng đợi và hàng đợi tuyến đường","hàng đợi Widget và hàng đợi SQL","hàng đợi HTTP và hàng đợi JSON","Hàng đợi microtask và hàng đợi sự kiện"],"exp":"Tùy chọn D đúng: Hàng đợi microtask và Hàng đợi sự kiện. Dart sử dụng Future cho một kết quả không đồng bộ và Stream cho một chuỗi sự kiện không đồng bộ; async/await làm cho mã dựa trên Future dễ đọc hơn."},"PRM-318":{"q":"Loại tác vụ nào được xử lý trước các tác vụ trong hàng đợi sự kiện?","options":["Khung ảnh","Microtask","Tuyến đường được đặt tên","Di chuyển cơ sở dữ liệu"],"exp":"Tùy chọn B đúng: Microtask. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-319":{"q":"scheduleMicrotask() làm gì?","options":["Thêm một cuộc gọi lại vào hàng đợi microtask","Khai báo một cái chung","Mở một tuyến đường","Tạo tệp JSON"],"exp":"Tùy chọn A đúng: Thêm lệnh gọi lại vào hàng đợi vi nhiệm. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-320":{"q":"Phương thức lifecycle nào được sử dụng cho logic khởi tạo một lần trong đối tượng State?","options":["onGenerateRoute()","chỉ build()","dispose()","initState()"],"exp":"Tùy chọn D đúng: initState(). Đây là khái niệm quản lý state: các thay đổi state phải thông báo hoặc kích hoạt phần có liên quan của UI để xây dựng lại."},"PRM-321":{"q":"Phương pháp nào hiển thị hình ảnh từ một URL?","options":["chỉ Image.asset","Text.network","Image.network","Icon.url"],"exp":"Tùy chọn C đúng: Image.network. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-322":{"q":"BoxFit kiểm soát những gì?","options":["Cách mã thông báo hết hạn","Cách một hình ảnh được thu nhỏ hoặc vừa với khu vực hiển thị của nó","Cách lọc List","Làm thế nào một tuyến đường được đẩy"],"exp":"Tùy chọn B đúng: Cách thu nhỏ hoặc điều chỉnh hình ảnh trong khu vực hiển thị của nó. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-323":{"q":"Navigator 1.0 sử dụng cấu trúc nào để quản lý màn hình?","options":["Một chồng các tuyến đường/trang","Cây SQL","Danh sách token","Hàng đợi vi nhiệm"],"exp":"Tùy chọn A đúng: Một chồng các tuyến đường/trang. API điều hướng Flutter quản lý quá trình chuyển đổi tuyến đường hoặc ánh xạ thông tin URL/tuyến đường đến tới ứng dụng state, tùy thuộc vào API được sử dụng."},"PRM-324":{"q":"Khi một ứng dụng cần đồng bộ hóa URL web và deep links phức tạp, tài liệu khuyên bạn nên cân nhắc điều gì?","options":["Chỉ sử dụng setState","Container","ThemeData","Router"],"exp":"Router phù hợp với các nhu cầu liên kết sâu và định tuyến phức tạp hơn mà Navigator 1.0 push/pop bắt buộc không thể thể hiện được, bao gồm cả đồng bộ hóa URL web. Các tùy chọn khác là các API widgets hoặc state không liên quan."},"PRM-325":{"q":"Navigator.pop() làm gì?","options":["Xóa tuyến đường hiện tại và hiển thị tuyến đường bên dưới nó","Thay thế toàn bộ ứng dụng state","Thêm một tuyến đường mới","Tạo một deep link"],"exp":"Tùy chọn A đúng: Xóa tuyến đường hiện tại và hiển thị tuyến đường bên dưới nó. API điều hướng Flutter quản lý quá trình chuyển đổi tuyến đường hoặc ánh xạ thông tin URL/tuyến đường đến tới ứng dụng state, tùy thuộc vào API được sử dụng."},"PRM-326":{"q":"Trình xây dựng MaterialPageRoute trả về cái gì?","options":["Một JSON Map","Cơ sở dữ liệu","widget xác định UI của màn hình tiếp theo","Mã thông báo JWT"],"exp":"Tùy chọn C đúng: widget xác định UI của màn hình tiếp theo. API điều hướng Flutter quản lý quá trình chuyển đổi tuyến đường hoặc ánh xạ thông tin URL/tuyến đường đến tới ứng dụng state, tùy thuộc vào API được sử dụng."},"PRM-327":{"q":"Kiến trúc của Flutter có ba lớp chính. order từ trên xuống dưới chính xác (gần nhất với nhà phát triển và gần nhất với phần cứng) là gì?","options":["Công cụ → Khung → Trình nhúng","Khung → Công cụ → Trình nhúng","Trình nhúng → Khung → Công cụ","Khung → Trình nhúng → Công cụ"],"exp":"Thứ tự kiến trúc: Framework (Dart) → Engine (C++) → Trình nhúng --- thứ tự tiêu chuẩn được nêu trong trang trình bày 'Flutter Tổng quan về kiến trúc'. Các tùy chọn khác đảo ngược thứ tự không chính xác."},"PRM-328":{"q":"Theo kiến ​​trúc của Flutter, câu nào mô tả đúng nhất khái niệm về 'Widget'?","options":["Widget chỉ là thành phần hiển thị hình ảnh","Trong Flutter, mọi thứ trên screen (bố cục, kiểu dáng, tương tác) đều được xây dựng thông qua Widget","Widget chỉ tồn tại trong Lớp Engine","Widget là khái niệm chỉ có Android, không được sử dụng trong Flutter"],"exp":"'Mọi thứ đều là Widget' --- mọi thứ trên màn hình đều là widget. A giới hạn sai phạm vi; C, D sai về vị trí/cái gì của widget."},"PRM-329":{"q":"`ListView.separated` khác với `ListView.builder` như thế nào?","options":["`ListView.separated` không hỗ trợ itemBuilder","`ListView.separated` cho phép chèn dấu phân cách widget giữa các mục thông qua `separatorBuilder` mà `ListView.builder` thiếu","`ListView.builder` chỉ hiển thị tối đa 10 mục","Cả hai hoàn toàn giống nhau ở API"],"exp":"`ListView.separated` cho phép chèn dấu phân cách giữa các mục thông qua `separatorBuilder`. A sai vì nó vẫn có itemBuilder; C sai vì không có giới hạn 10 mục; D sai vì hai API khác nhau."},"PRM-330":{"q":"`FocusNode` kết hợp với `textInputAction: TextInputAction.next` và `onFieldSubmitted` được dùng để làm gì?","options":["Mã hóa dữ liệu được nhập vào trường","Kiểm soát việc chuyển trọng tâm sang trường nhập next khi người dùng nhấn \"Tiếp theo\" trên bàn phím, cải thiện trải nghiệm nhập liệu trên thiết bị di động","Ẩn hoàn toàn bàn phím khi bắt đầu gõ","Tự động điền dữ liệu từ API"],"exp":"Sự kết hợp này kiểm soát việc chuyển trọng tâm sang trường next khi người dùng nhấn Tiếp theo, cải thiện UX trên thiết bị di động. A, C, D mô tả sai mục đích của nó."},"PRM-331":{"q":"`SharedPreferences` phù hợp nhất với loại dữ liệu nào?","options":["Dữ liệu quan hệ phức tạp với nhiều bảng được liên kết","Dữ liệu khóa-giá trị đơn giản như cờ hoặc cài đặt","Tệp hình ảnh lớn","Video có thời lượng dài"],"exp":"SharedPreferences phù hợp nhất với dữ liệu khóa-giá trị đơn giản như cờ hoặc cài đặt. A, C, D không phải là trường hợp thích hợp cho SharedPreferences."},"PRM-332":{"q":"Trên Flutter Web, `SharedPreferences` hoạt động dựa trên cơ chế lưu trữ trình duyệt nào?","options":["IndexedDB","Cookie","localStorage","SessionStorage"],"exp":"Trên Flutter Web, SharedPreferences ánh xạ tới `localStorage` của trình duyệt. A, B, D không khớp với cơ chế nêu trong bảng so sánh."},"PRM-333":{"q":"SQFlite khác với SQLite như thế nào theo câu hỏi \"Tại sao không đặt tên là SQLite?\" lời giải thích?","options":["SQFlite và SQLite là hai tên khác nhau cho cùng một khái niệm, không có sự khác biệt về mặt kỹ thuật","SQLite là công cụ lưu trữ thực tế, trong khi SQFlite là một Flutter plugin/wrapper (được viết bằng Dart + mã gốc) cho phép Flutter giao tiếp với SQLite --- SQFlite không phải là cơ sở dữ liệu độc lập","SQFlite chạy nhanh hơn 10 lần so với SQLite","SQFlite chỉ hoạt động trên Web, SQLite chỉ hoạt động trên thiết bị di động"],"exp":"SQLite là công cụ lưu trữ thực tế; SQFlite là plugin/trình bao bọc của Flutter kết nối với nó chứ không phải cơ sở dữ liệu độc lập. A, C, D không khớp với lời giải thích đã cho."},"PRM-334":{"q":"Trong SQFlite, hàm nào được gọi để mở hoặc tạo cơ sở dữ liệu và tần suất gọi hàm đó như thế nào?","options":["`openDatabase()` --- chỉ nên gọi là once (singleton/service) để tránh mở nhiều kết nối trùng lặp","`createDatabase()` --- nên được gọi mỗi lần trước khi truy vấn","`initDatabase()` --- tần suất cuộc gọi không thành vấn đề","`connectDatabase()` --- chỉ có thể sử dụng được với Web"],"exp":"`openDatabase()` chỉ nên được gọi là once (singleton/service) để tránh kết nối trùng lặp. B, C, D không phải là tên chức năng/cách sử dụng được khuyến nghị."},"PRM-335":{"q":"Đưa ra: ứng dụng Todo cần hiển thị danh sách tác vụ được phân trang để tránh tải tất cả dữ liệu cùng một lúc trên thiết bị di động. Mệnh đề SQL nào phù hợp nhất để triển khai phân trang?","options":["NHÓM THEO và CÓ","LIMIT và OFFSET","Chỉ ở ĐÂU là đủ","SQLite không hỗ trợ phân trang"],"exp":"`LIMIT` và `OFFSET` là cú pháp SQL tiêu chuẩn để phân trang. A, C, D không phù hợp/đúng cho mục đích này."},"PRM-336":{"q":"Ngoại tuyến-Đầu tiên\" là chiến lược thiết kế ứng dụng dựa trên nguyên tắc nào?","options":["Ứng dụng chỉ hoạt động khi có kết nối Internet ổn định","Ưu tiên tải và hiển thị dữ liệu cục bộ trước, sau đó đồng bộ hóa với máy chủ khi có kết nối mạng, giúp ứng dụng có thể sử dụng ngoại tuyến","Không bao giờ lưu trữ dữ liệu cục bộ, luôn gọi API mỗi khi cần dữ liệu","Chỉ áp dụng cho ứng dụng trò chơi"],"exp":"Ngoại tuyến-Đầu tiên ưu tiên tải dữ liệu cục bộ trước, đồng bộ hóa với máy chủ khi trực tuyến, giúp ứng dụng có thể sử dụng ngoại tuyến. A, C, D mô tả sai nguyên tắc thiết kế này."},"PRM-337":{"q":"Tại sao SharedPreferences được mô tả là \"KHÔNG dành cho các đối tượng phức tạp hoặc dữ liệu lớn\"?","options":["Bởi vì SharedPreferences chỉ hỗ trợ lưu trữ số nguyên","Bởi vì SharedPreferences được thiết kế để lưu trữ khóa-giá trị đơn giản values (String, bool, int, double, List`<String>`), điều này không phù hợp và không hiệu quả đối với dữ liệu có cấu trúc phức tạp hoặc khối lượng lớn","Vì SharedPreferences chỉ hoạt động với kết nối mạng","Vì SharedPreferences tự động xóa dữ liệu sau 24 giờ"],"exp":"SharedPreferences được thiết kế cho dữ liệu khóa-giá trị đơn giản, không phù hợp/không hiệu quả cho dữ liệu phức tạp hoặc lớn. A, C, D không khớp với lý do thực sự."},"PRM-338":{"q":"Sự khác biệt giữa Xác thực và Ủy quyền là gì?","options":["Hai khái niệm này hoàn toàn giống nhau","Câu trả lời xác thực \"Bạn là ai?\" (xác minh danh tính), Câu trả lời ủy quyền \"Bạn được phép làm gì?\" (kiểm soát truy cập)","Việc ủy quyền luôn diễn ra trước Xác thực","Xác thực chỉ áp dụng cho web, không áp dụng cho thiết bị di động"],"exp":"Xác thực xác minh identity (\"Bạn là ai?\"); Việc ủy ​​quyền xác định permissions (\"Bạn có thể làm gì?\"). A, C, D mô tả sai/đảo ngược hai khái niệm."},"PRM-339":{"q":"Theo ghi chú của người hướng dẫn \"JWT không được lưu trữ mật khẩu. Chỉ xác nhận danh tính\", SAI là gì nếu hệ thống lưu trữ mật khẩu của người dùng trực tiếp trong tải trọng JWT?","options":["Không có vấn đề gì vì JWT đã được ký nên nó luôn được bảo mật tuyệt đối","JWT chỉ được ký chứ không được mã hóa theo mặc định --- có nghĩa là bất kỳ ai nắm giữ token (e.g. thông qua giải mã base64 đều có thể giải mã và đọc trọng tải --- nên việc lưu trữ thông tin nhạy cảm như mật khẩu là một lỗ hổng bảo mật nghiêm trọng","JWT không thể chứa tải trọng kiểu đối tượng, chỉ có các chuỗi đơn giản","Đây là thông lệ tiêu chuẩn được ngành khuyến nghị"],"exp":"JWT chỉ có signed (không được mã hóa), vì vậy bất kỳ ai có mã thông báo đều có thể đọc được tải trọng của nó --- việc lưu trữ mật khẩu trong đó là một lỗ hổng nghiêm trọng. A, C, D không khớp với thuộc tính bảo mật thực tế của JWT."},"PRM-340":{"q":"Sự khác biệt giữa Mã thông báo truy cập và Mã thông báo làm mới theo bài giảng là gì?","options":["Mã thông báo truy cập có thời gian tồn tại lâu hơn Mã thông báo làm mới","Mã thông báo truy cập thường ngắn-lived (giảm rủi ro nếu bị lộ) và được gửi cùng với mọi yêu cầu; Refresh Token có đặc quyền mạnh hơn, dùng để nhận Access Token mới khi hết hạn nên cần bảo mật hơn storage (Lưu trữ an toàn)","Hai loại token có chức năng hoàn toàn giống nhau, chỉ khác nhau về tên gọi","Mã thông báo làm mới được gửi cùng với mọi yêu cầu API, trong khi Mã thông báo truy cập chỉ được sử dụng một lần"],"exp":"Mã thông báo truy cập tồn tại trong thời gian ngắn và được gửi theo yêu cầu; Refresh Token có đặc quyền mạnh hơn, dùng để gia hạn Access Token, cần lưu trữ an toàn hơn. A, C, D mô tả sai đặc điểm của hai token."},"PRM-341":{"q":"Trong quy trình Luồng đăng ký, câu nào đúng về mối quan hệ giữa AuthService được sử dụng cho Login (Bản demo 10.1) và Signup (Bản demo 10.2)?","options":["Đăng ký phải tạo một dịch vụ hoàn toàn mới, tách biệt hoàn toàn với AuthService của Đăng nhập","Đăng ký sử dụng lại cùng một lớp `AuthService`, chỉ thêm một method (`signup(...)` mới), giữ nguyên kiến trúc và xử lý lỗi đã được thiết lập bởi Đăng nhập","Đăng ký không cần dịch vụ nào cả, xử lý mọi thứ trực tiếp trong widget","AuthService chỉ được sử dụng để đăng xuất"],"exp":"Đăng ký sử dụng lại cùng một lớp AuthService, thêm phương thức signup() mới trong khi vẫn giữ cấu trúc/xử lý lỗi hiện có. A, C, D không khớp với nội dung \"Đăng ký API Integration (Sử dụng lại AuthService)\"."},"PRM-342":{"q":"`SharedPreferences` chủ yếu được sử dụng để làm gì trong Demo 10.3?","options":["Lưu trữ toàn bộ lịch sử duyệt web của người dùng","Duy trì mã thông báo xác thực để triển khai tự động đăng nhập, do đó người dùng không cần đăng nhập lại mỗi khi mở ứng dụng","Lưu trữ ảnh đại diện của người dùng dưới dạng dữ liệu nhị phân","Thay thế hoàn toàn JWT"],"exp":"SharedPreferences duy trì mã thông báo xác thực để đăng nhập tự động, tránh đăng nhập nhiều lần. A, C, D không phù hợp với mục đích của nó trong Demo 10.3."},"PRM-343":{"q":"Trong Luồng đăng nhập tự động: \"Splash → (có mã thông báo?) → Trang chủ / Đăng nhập.\" Nếu mã thông báo đã hết hạn nhưng vẫn tồn tại trong SharedPreferences (ứng dụng chỉ kiểm tra \"mã thông báo có tồn tại\" MÀ KHÔNG kiểm tra thời hạn sử dụng của nó không), điều gì có thể xảy ra?","options":["Ứng dụng sẽ luôn phát hiện chính xác mã thông báo đã hết hạn vì SharedPreferences tự động xác thực mã thông báo đó","Ứng dụng có thể điều hướng nhầm người dùng đến Trang chủ mặc dù mã thông báo đã hết hạn, khiến các yêu cầu API tiếp theo trở thành rejected (401 trái phép) --- cho thấy nhu cầu cũng phải kiểm tra thời hạn sử dụng của mã thông báo hoặc xử lý lỗi 401 để buộc đăng xuất khi cần","Mã thông báo sẽ tự động làm mới mà không cần thêm logic","Ứng dụng sẽ luôn ở trên màn hình Splash mãi mãi"],"exp":"Nếu không kiểm tra thời hạn sử dụng, ứng dụng có thể điều hướng sai đến Trang chủ, dẫn đến lỗi 401 trong các yêu cầu tiếp theo, cho thấy cần phải kiểm tra thời hạn sử dụng hoặc xử lý 401. A, C, D không phù hợp với hệ quả thực tế."},"PRM-344":{"q":"Một ứng dụng thực hiện như sau: (1) Người dùng đăng nhập và nhận Mã thông báo truy cập sẽ hết hạn sau 15 phút; (2) Mã thông báo truy cập được lưu trữ trong SharedPreferences; (3) Không có cơ chế Refresh Token nào được triển khai. Hậu quả thực tế có thể xảy ra nhất sau 15 phút sử dụng ứng dụng liên tục là gì?","options":["Ứng dụng sẽ tự động gia hạn mã thông báo mãi mãi mà không cần thực hiện hành động nào","API yêu cầu sau khi hết hạn sẽ bắt đầu là rejected (401 Không được phép) và do không có Mã thông báo làm mới nên người dùng buộc phải đăng nhập lại theo cách thủ công để nhận Mã thông báo truy cập mới --- đây là một hạn chế cần được khắc phục bằng cơ chế mã thông báo làm mới","Access Token sẽ tự động trở thành Refresh Token","Ứng dụng sẽ gặp sự cố ngay lập tức khi Access Token hết hạn"],"exp":"Nếu không có cơ chế làm mới, các yêu cầu sau khi hết hạn sẽ gặp lỗi 401, buộc phải đăng nhập lại thủ công --- một hạn chế cần sửa mã thông báo làm mới. A, C, D không phù hợp với hệ quả thực tế."},"PRM-345":{"q":"So sánh AuthService (Mẫu đơn) được đề cập trong \"Mẫu kiến ​​trúc\" với logic xác thực phân tán trực tiếp trên từng màn hình riêng lẻ widgets (LoginScreen, SignupScreen, HomeScreen, mỗi mã đều viết logic gọi API của riêng chúng). Theo tinh thần của bài giảng, nhược điểm chính của phương pháp phân tán là gì?","options":["Không có nhược điểm nào cả, cả hai phương pháp đều có chất lượng tương đương","Cách tiếp cận phân tán dẫn đến logic trùng lặp trên các màn hình, khó duy trì nhất quán khi luồng xác thực thay đổi và giảm khả năng sử dụng lại --- trong khi AuthService tập trung tách UI khỏi logic nghiệp vụ, giúp kiểm tra và mở rộng dễ dàng hơn","Cách tiếp cận phân tán luôn nhanh hơn trong thời gian chạy","Singleton AuthService chỉ phù hợp với các ứng dụng không cần đăng nhập"],"exp":"Logic xác thực phân tán gây ra sự trùng lặp, khó bảo trì và khả năng sử dụng lại thấp; AuthService tập trung tách biệt UI khỏi logic, hỗ trợ khả năng kiểm tra/mở rộng. A, C, D không khớp với phân tích kiến ​​trúc phần mềm."},"PRM-346":{"q":"Công cụ kết xuất nào được đề cập trong kiến ​​trúc của Flutter?","options":["Gecko","Blink","Skia","WebKit"],"exp":"Tùy chọn C đúng: Skia. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-347":{"q":"Ba lớp chính của kiến ​​trúc Flutter là gì?","options":["HTML, CSS và JavaScript","Mô hình, Chế độ xem và Bộ điều khiển","Máy khách, máy chủ và cơ sở dữ liệu","Khung, Công cụ và Trình nhúng"],"exp":"Tùy chọn D đúng: Framework, Engine và Embedder. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-348":{"q":"Khi nào const thích hợp?","options":["Khi một giá trị không đổi được biết tại thời điểm biên dịch","Khi một giá trị chỉ được biết sau lệnh gọi API","Khi một giá trị phải là nullable","Khi một biến phải thay đổi liên tục"],"exp":"Tùy chọn A đúng: Khi biết giá trị không đổi tại thời điểm biên dịch. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-349":{"q":"Padding và SizedBox chủ yếu cải thiện điều gì?","options":["Tạo bảng cơ sở dữ liệu","Mã hóa JWT","Khoảng cách, khả năng đọc và tính nhất quán về mặt hình ảnh","API tốc độ yêu cầu"],"exp":"Tùy chọn C đúng: Khoảng cách, khả năng đọc và tính nhất quán về hình ảnh. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-350":{"q":"AspectRatio giúp đạt được điều gì?","options":["Duy trì tỷ lệ khung hình và ngăn ngừa biến dạng hình ảnh","Gọi một API","Mã hóa hình ảnh","Tạo nhiều cột lưới"],"exp":"Tùy chọn A đúng: Giữ nguyên tỷ lệ khung hình và ngăn ngừa biến dạng hình ảnh. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-351":{"q":"SafeArea ngăn chặn điều gì?","options":["tiêm SQL","Ngoại lệ rỗng","Nội dung được bao phủ bởi khu vực notch, Dynamic Island hoặc hệ thống UI","API hết thời gian chờ"],"exp":"Tùy chọn C đúng: Nội dung được bao phủ bởi khu vực notch, Dynamic Island hoặc hệ thống UI. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-352":{"q":"Khoảng cách và điều khiển runSpacing trong Wrap là gì?","options":["Khoảng cách ngang và khoảng cách giữa các dòng","API hết thời gian chờ và thử lại","Chiều rộng và chiều cao của hình ảnh","Mã thông báo hết hạn và làm mới"],"exp":"Phương án A đúng: Khoảng cách ngang và khoảng cách giữa các dòng. Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-353":{"q":"API được mô tả như thế nào?","options":["Cơ sở dữ liệu cục bộ cần thiết","Bố cục widget","Hợp đồng cho phép khách hàng giao tiếp với máy chủ thông qua các điểm cuối","Một tập tin hình ảnh"],"exp":"Tùy chọn C đúng: Hợp đồng cho phép khách hàng giao tiếp với máy chủ thông qua các điểm cuối. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-354":{"q":"Dữ liệu lưu trữ cục bộ được lưu ở đâu?","options":["Trực tiếp trên thiết bị của người dùng","Chỉ có trong GPU","Chỉ trên máy chủ đám mây","Chỉ trong mã nguồn"],"exp":"Tùy chọn A đúng: Trực tiếp trên thiết bị của người dùng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-355":{"q":"Những lợi ích lưu trữ cục bộ nào được đề cập?","options":["Nó luôn yêu cầu kết nối internet","Nó không thể lưu trữ tùy chọn","Nó chỉ được sử dụng cho hình ảnh","Nó hoạt động ngoại tuyến, tiếp tục khởi động lại và cung cấp khả năng truy cập nhanh"],"exp":"Tùy chọn D đúng: Nó hoạt động ngoại tuyến, tiếp tục khởi động lại và cung cấp khả năng truy cập nhanh. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-356":{"q":"SharedPreferences phù hợp nhất để làm gì?","options":["Tệp video lớn","Dữ liệu khóa-giá trị đơn giản như cài đặt và cờ","Nội dung trò chơi 3D","Bộ dữ liệu quan hệ lớn"],"exp":"Tùy chọn B đúng: Dữ liệu khóa-giá trị đơn giản như cài đặt và cờ. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-357":{"q":"Trường hợp nào không nên sử dụng SharedPreferences?","options":["Chế độ sắp xếp mặc định","Cờ chế độ tối","Đối tượng phức tạp hoặc dữ liệu lớn","Cờ giới thiệu đã hoàn tất"],"exp":"Tùy chọn C đúng: Đối tượng phức tạp hoặc dữ liệu lớn. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-358":{"q":"Trên Flutter Web, SharedPreferences thường ánh xạ tới cái gì?","options":["Firebase Xác thực","Trình duyệt localStorage","Android Bản kê khai","Tệp SQLite"],"exp":"Tùy chọn B đúng: Trình duyệt localStorage. Flutter hỗ trợ nhiều mục tiêu triển khai, mặc dù mỗi mục tiêu có thể có SDK, yêu cầu về công cụ và tích hợp nền tảng riêng."},"PRM-359":{"q":"Phương pháp nào lưu trữ boolean trong SharedPreferences?","options":["insertRow()","setMap()","writeJwt()","setBool(khóa, giá trị)"],"exp":"Tùy chọn D đúng: setBool(khóa, giá trị). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-360":{"q":"Phương pháp sqflite nào thêm một hàng?","options":["insert()","query()","delete()","update()"],"exp":"Tùy chọn A đúng: insert(). Bố cục Flutter được tạo từ widgets; widget đã chọn cung cấp hành vi sắp xếp, định cỡ, giãn cách hoặc ràng buộc được mô tả."},"PRM-361":{"q":"Thư mục nào trong cấu trúc dự án Flutter chứa cấu hình nội dung và phần phụ thuộc?","options":["lib/","kiểm tra/","pubspec.yaml","android/"],"exp":"`pubspec.yaml` chứa cấu hình nội dung và phần phụ thuộc. A giữ mã Dart chính; B tổ chức các bài kiểm tra đơn vị; D chứa mã dành riêng cho Android."},"PRM-362":{"q":"Lệnh `flutter doctor` dùng để làm gì?","options":["Tự động sửa lỗi trong mã nguồn Dart","Kiểm tra và xác nhận xem cài đặt Flutter SDK và các công cụ liên quan đã sẵn sàng chưa","Xây dựng ứng dụng thành tệp release APK","Chạy thử nghiệm đơn vị cho toàn bộ dự án"],"exp":"`flutter doctor` kiểm tra môi trường cài đặt Flutter SDK và các công cụ liên quan. A, C, D mô tả sai chức năng của lệnh này."},"PRM-363":{"q":"Trong `ApiService`, tham số hàm tạo `ApiService({http.Client? client}) : client = client ?? http.Client();` minh họa kỹ thuật nào?","options":["Buộc luôn sử dụng cùng một phiên bản toàn cầu HTTP Client","Cho phép \"chèn\" một `http.Client` tùy chỉnh từ outside (hữu ích khi thử nghiệm với một client giả); nếu không có thông tin nào được thông qua thì client mặc định sẽ được sử dụng","Đây là cú pháp Dart không hợp lệ","Không có mục đích rõ ràng, chỉ để rút ngắn mã"],"exp":"Điều này minh họa việc chèn phần phụ thuộc --- cho phép một http.Client tùy chỉnh là injected (hữu ích cho việc thử nghiệm mô phỏng), nếu không thì hãy đặt mặc định. A, C, D không phù hợp với mục đích thực sự."},"PRM-364":{"q":"Theo bài giảng, ba nhóm dữ liệu API điển hình mà học sinh có thể chọn cho dự án của mình là gì?","options":["thời gian thực, phương tiện truyền thông, API mô phỏng","xác thực, lưu trữ, kiểm tra API","Chỉ có JSONPlaceholder thôi","Firebase, SQLite, GraphQL"],"exp":"Ba nhóm điển hình: thời gian thực, phương tiện, API mô phỏng --- khớp với câu hỏi \"API là gì? HTTP là gì?\" cầu trượt. B, C, D không đúng nội dung đã nêu."},"PRM-365":{"q":"Trong bảng \"Hỗ trợ SharedPreferences trên nhiều môi trường\", tại sao DartPad (Chế độ Flutter) không thực sự hỗ trợ SharedPreferences?","options":["Bởi vì DartPad chỉ hỗ trợ ngôn ngữ JavaScript","Vì DartPad không có quyền truy cập vào thiết bị thực storage (không có bộ nhớ riêng), nên cần có một mô hình class (như FakePrefs) để mô phỏng hành vi lưu trữ trong bộ nhớ","Bởi vì SharedPreferences chỉ hoạt động trên iOS","Bởi vì DartPad hoàn toàn không hỗ trợ bất kỳ Flutter widgets nào"],"exp":"DartPad không có quyền truy cập vào bộ nhớ thiết bị thực, yêu cầu một lớp mô phỏng để mô phỏng bộ nhớ trong bộ nhớ. A, C, D không phù hợp với lý do kỹ thuật thực tế."},"PRM-366":{"q":"Trong Demo 10.1, tại sao bài giảng lại chọn \"Xác thực mô phỏng\" (xác thực mô phỏng bên trong AuthService) thay vì gọi một API thực ngay từ đầu?","options":["Bởi vì về mặt lý thuyết, Xác thực mô phỏng nhanh hơn trong tính toán","Để đảm bảo bản demo hoạt động đáng tin cậy trong mọi hoạt động học tập environment (không phụ thuộc vào kết nối mạng vì máy chủ thực có thể bị lỗi/hết thời gian chờ), phù hợp với giai đoạn tìm hiểu các khái niệm cơ bản trước khi chuyển sang tích hợp API thực","Vì Real API luôn yêu cầu thanh toán","Bởi vì Flutter không hỗ trợ thực hiện các yêu cầu HTTP thực sự trong ứng dụng dành cho thiết bị di động"],"exp":"Xác thực mô phỏng đảm bảo các bản demo đáng tin cậy trên các môi trường bất kể sự cố mạng, phù hợp để dạy các khái niệm cơ bản trước khi tích hợp API thực. A, C, D không khớp với lý do thực tế."},"PRM-367":{"q":"Theo bảng so sánh Mock API và Real API, nhược điểm của Real API so với Mock API trong bối cảnh giảng dạy là gì?","options":["Real API luôn nhanh hơn và ổn định hơn Mock API","Real API có thể gặp lỗi từ mạng, máy chủ, TLS hoặc CORS --- kém ổn định hơn Mock API, luôn hoạt động mà không cần Internet","Không thể sử dụng API thực để dạy học sinh về mạng","Mô phỏng API không bao giờ được sử dụng trong các dự án thực tế hoặc trong giảng dạy"],"exp":"API thực có thể bị lỗi do sự cố mạng/máy chủ/TLS/CORS, kém ổn định hơn Mock API không cần Internet. A, C, D không khớp với nội dung thực tế của bảng so sánh."},"PRM-368":{"q":"Ba loại thử nghiệm chính trong Flutter được đề cập trong bài giảng là gì?","options":["Kiểm tra đơn vị, Kiểm tra Widget, Kiểm tra tích hợp","Thử nghiệm Alpha, Thử nghiệm Beta, Thử nghiệm phát hành","Kiểm tra thủ công, Kiểm tra tự động, Kiểm tra khói","Kiểm tra tải, Kiểm tra căng thẳng, Kiểm tra bảo mật"],"exp":"Ba loại thử nghiệm chính: Thử nghiệm đơn vị, Thử nghiệm Widget, Thử nghiệm tích hợp. B, C, D không phải là các phân loại bài kiểm tra được dạy ở Học phần 11."},"PRM-369":{"q":"Theo \"Flutter Kim tự tháp thử nghiệm\", loại thử nghiệm nào sẽ có số lượng LỚN NHẤT trong một dự án vì nó nhanh, ổn định và chi phí thấp?","options":["Kiểm tra tích hợp","Widget Kiểm tra","Kiểm tra đơn vị","Cả ba loại đều có số lượng bằng nhau"],"exp":"Các bài kiểm thử đơn vị phải có số lượng nhiều nhất theo Kim tự tháp kiểm thử --- nhanh, ổn định, chi phí thấp. A, B không đúng vị trí trong kim tự tháp; D sai vì phân phối không bằng nhau."},"PRM-370":{"q":"Với bài kiểm tra đơn vị này: test('toggle() should switch completed state', () { final task = Task(id: '1', title: 'Demo task'); expect(task.completed, false); task.toggle(); expect(task.completed, true); task.toggle(); expect(task.completed, false); }); Mẫu cấu trúc bài kiểm tra phổ biến nào sẽ kiểm tra điều này apply (mặc dù không được gắn nhãn rõ ràng bằng nhận xét)?","options":["Chế độ xem mô hình-Controller (MVC)","Sắp xếp - Hành động - Assert (chuẩn bị dữ liệu, thực hiện hành động, xác minh kết quả)","Mẫu đơn","Mẫu quan sát"],"exp":"test này tuân theo mẫu Sắp xếp - Hành động - Khẳng định. A, C, D là các mẫu thiết kế/kiến trúc không liên quan, không phải cấu trúc test."},"PRM-371":{"q":"Bài kiểm tra Widget trong Flutter khác với Bài kiểm tra đơn vị như thế nào?","options":["Kiểm tra Widget chỉ kiểm tra logic thuần túy không liên quan đến UI, giống hệt như Kiểm tra đơn vị","Kiểm tra Widget kiểm tra kết xuất UI và interaction (e.g. nhập văn bản, nhấn nút) trên cây widget hoặc cây widget nhỏ, trong khi Kiểm tra đơn vị chỉ kiểm tra logic/chức năng không liên quan đến UI","Widget Kiểm tra luôn chạy chậm hơn Kiểm tra tích hợp","Widget Kiểm tra không thể mô phỏng việc nhập văn bản hoặc nhấn"],"exp":"Kiểm tra Widget kiểm tra việc hiển thị/tương tác UI trên cây widget; Kiểm tra đơn vị kiểm tra logic thuần túy không liên quan đến UI. A, C, D mô tả sai đặc điểm của hai loại bài kiểm tra."},"PRM-372":{"q":"Trong Kiểm tra điều hướng, `pumpAndSettle()` khác với `pump()` đơn giản như thế nào?","options":["Không có gì khác biệt cả, 2 chức năng hoàn toàn tương đương","`pumpAndSettle()` liên tục \"bơm\" khung hình cho đến khi không còn hoạt ảnh/chuyển tiếp nào còn running (đã giải quyết hoàn toàn), rất hữu ích để chờ hiệu ứng chuyển màn hình kết thúc trước khi xác nhận","`pumpAndSettle()` chỉ có thể được sử dụng cho Bài kiểm tra đơn vị","`pump()` luôn đợi lâu hơn `pumpAndSettle()`"],"exp":"pumpAndSettle() liên tục bơm khung hình cho đến khi tất cả hoạt ảnh ổn định, hữu ích cho việc chờ chuyển đổi điều hướng. A, C, D mô tả sai chức năng này."},"PRM-373":{"q":"Theo bảng \"Cách kiểm tra ánh xạ tới các vấn đề Flutter thực tế\", vấn đề \"Điều hướng sai\" chủ yếu được phát hiện bởi loại kiểm tra nào?","options":["Kiểm tra đơn vị","Điều hướng Test (một phần của nhóm Kiểm tra Widget mở rộng)","Các vấn đề về điều hướng hoàn toàn không thể được kiểm tra","Chỉ có thể được phát hiện thông qua kiểm tra thủ công"],"exp":"Điều hướng sai\" chủ yếu phải được phát hiện bởi Điều hướng Test (Kiểm tra Widget mở rộng), trên mỗi bảng. A, C, D không khớp với nội dung của bảng."},"PRM-374":{"q":"Trong Ứng dụng Taskly, `TaskRepository` xử lý logic CRUD cho các tác vụ, trong khi `TaskProvider` quản lý state. Nếu Kiểm tra Widget muốn kiểm tra hành vi UI KHÔNG tùy thuộc vào kết nối cơ sở dữ liệu/API thực của Repository, thì phương pháp hợp lý nào được đề xuất trong \"Các phương pháp hay nhất\" của Mô-đun 11?","options":["Luôn kết nối trực tiếp với dữ liệu thực để đảm bảo độ chính xác kiểm tra tuyệt đối","Giả lập Repository khi có thể, để Widget Thử nghiệm chạy nhanh, đáng tin cậy và độc lập với dữ liệu bên ngoài thực tế state","Hoàn toàn bỏ qua việc kiểm tra bất kỳ widget nào liên quan đến Repository","Di chuyển tất cả logic Repository bên trong Widget để giúp việc kiểm tra dễ dàng hơn"],"exp":"Việc mô phỏng Repository khi có thể giúp Widget Kiểm tra nhanh, ổn định và độc lập với dữ liệu bên ngoài state. A, C, D không phù hợp với phương pháp hay nhất được đề xuất."},"PRM-375":{"q":"Trong bảng ánh xạ loại vấn đề đến thử nghiệm: \\| Flutter Vấn đề \\| Kiểm tra được đề xuất \\| \\|---\\|---\\| \\| Lỗi logic \\| Kiểm tra đơn vị \\| \\| UI không cập nhật \\| Widget bài kiểm tra \\| \\| Điều hướng sai \\| Kiểm tra điều hướng \\| \\| Toàn bộ tính năng bị hỏng \\| Kiểm tra tích hợp \\| Nếu xảy ra lỗi do Provider không gọi `notifyListeners()` sau khi cập nhật data (khiến UI không cập nhật ngay cả khi dữ liệu đã thay đổi trong bộ nhớ), loại thử nghiệm nào có thể phát hiện trực tiếp nhất sự cố này?","options":["Bài kiểm tra đơn vị chỉ kiểm tra chức năng cập nhật dữ liệu vì nó không liên quan đến UI","Kiểm tra Widget --- vì nó cần xác minh rằng sau khi hành động xảy ra, UI thực sự hiển thị lại với data mới (điều mà Kiểm tra đơn vị logic thuần túy không thể kiểm tra)","Không có loại thử nghiệm nào có thể phát hiện lỗi này","Chỉ Kiểm tra tích hợp mới có thể phát hiện ra nó, Widget Kiểm tra hoàn toàn không phù hợp"],"exp":"Thử nghiệm Widget là trực tiếp nhất vì nó xác minh UI thực sự hiển thị lại với dữ liệu mới, không giống như Thử nghiệm đơn vị logic thuần túy. A, C, D không phù hợp với phương pháp phát hiện thích hợp."},"PRM-376":{"q":"`expect()` trong flutter_test dùng để làm gì?","options":["Đang khởi tạo cây widget cho bài kiểm tra","So sánh giá trị thực tế với giá trị mong đợi và thất bại nếu chúng không khớp --- đây là bước \"Khẳng định\" trong quá trình thử nghiệm","Đang chờ hoạt ảnh kết thúc","Tạo dữ liệu giả ngẫu nhiên"],"exp":"expect() so sánh giá trị thực tế và giá trị mong đợi, không khớp --- bước Khẳng định. A, C, D mô tả sai chức năng của expect()."},"PRM-377":{"q":"Hãy xem xét lời giải thích của bài giảng: \"Hầu hết các vấn đề UI đều bắt đầu từ logic → các bài kiểm tra đơn vị phát hiện vấn đề sớm.\" Áp dụng điều này trong thực tế: nếu hàm đếm tasks (`getIncompleteCount()`) không đầy đủ trong TaskProvider có logic bug (tính sai), nhưng UI vẫn hiển thị số chính xác do trùng hợp với dữ liệu thử nghiệm nhỏ, thì phương pháp thử nghiệm nào tốt nhất và đáng tin cậy nhất sẽ phát hiện sớm lỗi này, bất kể kích thước dữ liệu?","options":["Chỉ dựa vào quan sát UI thủ công với các tập dữ liệu ngẫu nhiên","Viết Bài kiểm tra đơn vị chuyên dụng cho `getIncompleteCount()` với nhiều datasets khác nhau (trường hợp cạnh: trống, tất cả đã hoàn thành, hỗn hợp), tách biệt và xác minh logic tính toán một cách chính xác mà không phụ thuộc vào việc UI \"có xảy ra\" hiển thị chính xác hay không","Kiểm tra tích hợp là cách duy nhất để bắt lỗi logic này","Không có hình thức kiểm tra tự động nào có thể phát hiện lỗi logic"],"exp":"Bài kiểm tra đơn vị chuyên dụng với các bộ dữ liệu trường hợp biên khác nhau sẽ tách biệt và xác minh logic tính toán một cách đáng tin cậy bất kể hiển thị chính xác ngẫu nhiên. A, C, D không phù hợp với phương pháp phát hiện sớm đáng tin cậy nhất."},"PRM-378":{"q":"Theo Tóm tắt của Học phần 11, kỹ năng nào KHÔNG được liệt kê là mục tiêu học tập của học phần này?","options":["Viết bài kiểm tra đơn vị để kiểm tra logic và hành vi của mô hình","Viết các bài kiểm tra Widget để kiểm tra khả năng hiển thị và tương tác của UI","Xây dựng và ký tệp release APK để xuất bản lên Google Play","Sử dụng DevTools để chẩn đoán các vấn đề về bố cục, xây dựng lại và điều hướng"],"exp":"Xây dựng và ký release APK để xuất bản trên Google Play là chủ đề của Mô-đun 12, KHÔNG phải là mục tiêu học tập của Mô-đun 11. A, B, D đều là mục tiêu học tập chính xác của Mô-đun 11."},"PRM-379":{"q":"Hãy xem xét: một nhóm sinh viên viết RẤT NHIỀU bài kiểm tra tích hợp Tests (phần lớn tất cả các bài kiểm tra) nhưng hầu như không có Bài kiểm tra đơn vị. Theo nguyên tắc \"Kim tự tháp thử nghiệm\" đã học được, hậu quả thực tế nào có thể xảy ra?","options":["Không có hậu quả tiêu cực nào cả, Integration Test nhiều hơn luôn tốt hơn trong mọi trường hợp","Bộ kiểm thử sẽ chạy chậm hơn đáng kể, tốn nhiều thời gian/tài nguyên hơn để duy trì và việc xác định nguyên nhân cốt lõi khi xảy ra lỗi sẽ khó hơn việc có một nền tảng Kiểm thử đơn vị vững chắc để sớm xử lý isolate lỗi logic","Integration Test luôn nhanh hơn Unit Test nên đây là chiến lược tối ưu","Việc phân phối các loại thử nghiệm không ảnh hưởng gì đến tốc độ hoặc chi phí bảo trì"],"exp":"Quá nhiều Kiểm thử tích hợp và quá ít Kiểm thử đơn vị sẽ dẫn đến bộ công cụ chậm hơn, tốn kém hơn để bảo trì và khó tách biệt nguyên nhân gốc rễ hơn. A, C, D mâu thuẫn với nguyên tắc Kim tự tháp Kiểm tra."},"PRM-380":{"q":"Trong \"Danh sách kiểm tra triển khai\" sau khi hoàn thành Demo 12.4, mục nào sau đây được đề cập?","options":["Xóa câu lệnh debug, xóa nội dung không sử dụng, đảm bảo versionCode đã được cập nhật","Nhân đôi số lượng hình ảnh động trong ứng dụng","Xóa toàn bộ tệp cấu hình pubspec.yaml","Chuyển đổi toàn bộ ứng dụng để sử dụng Kiểm tra Widget thay vì Kiểm tra đơn vị"],"exp":"Danh sách kiểm tra đề cập đến việc xóa câu lệnh debug, xóa nội dung không sử dụng và đảm bảo versionCode được cập nhật. B, C, D không phải là những mục hợp lý/được nêu trong danh sách kiểm tra thực tế."},"PRM-381":{"q":"Theo bản tóm tắt của Mô-đun 12, mục tiêu cuối cùng của toàn bộ quá trình tối ưu hóa và đóng gói ứng dụng Taskly là gì?","options":["Đơn giản là giảm số dòng mã của dự án","Để tạo bản dựng Bản phát hành được tối ưu hóa hiệu suất, hãy xác minh kích thước của ứng dụng và sẵn sàng cho thế giới thực deployment (sẵn sàng sản xuất)","Để loại bỏ hoàn toàn nhu cầu viết Unit Test trong các dự án trong tương lai","Để chuyển đổi toàn bộ ứng dụng từ Flutter sang nền tảng gốc"],"exp":"Mục tiêu cuối cùng là bản dựng Bản phát hành được tối ưu hóa hiệu suất, được xác minh kích thước, sẵn sàng sản xuất, theo Tóm tắt của Mô-đun 12. A, C, D không phù hợp với mục tiêu final đã nêu của mô-đun."},"PRM-382":{"q":"Một nhóm sinh viên cố tình bỏ qua việc viết Bài kiểm tra đơn vị và tách riêng architecture (State/Repository) rõ ràng để \"hoàn thành dự án nhanh chóng\", dẫn đến việc sau này rất khó sửa lỗi hoặc thêm tính năng mới mà không làm hỏng các bộ phận đang hoạt động. Điều này minh họa khái niệm nào trong bài giảng và nó liên quan như thế nào đến kiến ​​trúc principles (Repository Mẫu, Kim tự tháp kiểm tra) được dạy trong Mô-đun 3 và Mô-đun 11?","options":["Điều này không liên quan đến bất kỳ khái niệm nào được dạy trong các học phần trước","Đây là một ví dụ về \"Nợ kỹ thuật\" --- bỏ qua mẫu architecture (Repository sạch từ Mô-đun 3) và testing (Kiểm tra kim tự tháp từ Mô-đun 11) giúp tiết kiệm thời gian ngắn hạn nhưng làm tăng chi phí bảo trì/sửa lỗi dài hạn, phù hợp với bản chất \"vay trước, trả lãi sau\" của nợ kỹ thuật","Đây là một ví dụ về Thử nghiệm vàng","Đây là phương pháp được đề xuất để tối ưu hóa hiệu suất cho mỗi Mô-đun 12"],"exp":"Đây là ví dụ về Nợ kỹ thuật: bỏ qua thử nghiệm và kiến trúc sạch giúp tiết kiệm thời gian ngắn hạn nhưng làm tăng chi phí bảo trì dài hạn, phù hợp với bản chất \"mượn trước, trả sau\" của nợ. A, C, D không khớp với khái niệm/mối quan hệ đúng."},"PRM-383":{"q":"Nếu Thử nghiệm vàng được thiết lập để chạy tự động trong quy trình CI/CD trước khi hợp nhất mã, mục đích chính của việc thực hiện việc này là gì?","options":["Tăng tốc độ xây dựng ứng dụng release","Tự động phát hiện sớm các hồi quy hình ảnh ngoài ý muốn do thay đổi mã gây ra, trước khi những thay đổi đó được hợp nhất vào nhánh chính, giúp đảm bảo tính nhất quán UI theo thời gian","Thay thế hoàn toàn Bài kiểm tra đơn vị và Bài kiểm tra Widget","Chỉ có tác dụng kiểm tra tốc độ mạng của ứng dụng"],"exp":"Chạy thử nghiệm vàng trong CI/CD sẽ phát hiện sớm các hồi quy trực quan trước khi hợp nhất, đảm bảo tính nhất quán của UI theo thời gian. A, C, D không phù hợp với mục đích thực tế của việc tích hợp CI/CD này."},"PRM-384":{"q":"Lớp Embedder chủ yếu xử lý những gì?","options":["Lưu trữ dữ liệu với SQLite","Tích hợp nền tảng, đầu vào, lifecycle và quản lý cửa sổ","Xác định loại dữ liệu Dart","Viết bài kiểm tra đơn vị"],"exp":"Tùy chọn B đúng: Tích hợp nền tảng, đầu vào, lifecycle và quản lý cửa sổ. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-385":{"q":"Những phần tử màn hình tiêu chuẩn nào Scaffold có thể cung cấp?","options":["AppBar, phần thân, ngăn kéo, bottomNavigationBar và floatingActionButton","Chỉ trường văn bản","Chỉ kiểm tra đơn vị","Chỉ kết nối cơ sở dữ liệu"],"exp":"Tùy chọn A đúng: AppBar, nội dung, ngăn kéo, bottomNavigationBar và floatingActionButton. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-386":{"q":"Info.plist Loại URL được sử dụng để làm gì?","options":["Lưu trữ mã thông báo truy cập","Xác định một Provider","Chạy thử nghiệm đơn vị","Khai báo lược đồ URL tùy chỉnh cho ứng dụng iOS"],"exp":"Tùy chọn D đúng: Khai báo lược đồ URL tùy chỉnh cho ứng dụng iOS. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-387":{"q":"Xác thực giả phù hợp nhất để làm gì?","options":["Ký Google Play","Di chuyển cơ sở dữ liệu","Trình diễn lớp học và học tập một cách ổn định mà không phụ thuộc vào mạng","Việc triển khai sản xuất final"],"exp":"Phương án C đúng: Minh họa trên lớp và học tập theo một quy trình ổn định mà không phụ thuộc vào mạng. Kiểm tra đơn vị isolate một hàm, phương thức hoặc lớp; mô phỏng giúp kiểm soát và lặp lại các phần phụ thuộc bên ngoài."},"PRM-388":{"q":"Xác thực{0}} thực có những rủi ro gì so với xác thực giả?","options":["Nó không cần mã async","Nó có thể bị lỗi do mạng, máy chủ, TLS hoặc CORS","Nó không cần xử lý lỗi","Nó không bao giờ thất bại"],"exp":"Tùy chọn B đúng: Tùy chọn này có thể không thành công do mạng, máy chủ, TLS hoặc CORS. Kiểm tra đơn vị isolate một hàm, phương thức hoặc lớp; mô phỏng giúp kiểm soát và lặp lại các phần phụ thuộc bên ngoài."},"PRM-389":{"q":"Bài kiểm tra đơn vị xác nhận điều gì?","options":["kích thước APK","Logic mà không yêu cầu UI","Chỉ hoạt ảnh","Luồng người dùng hoàn chỉnh trên một thiết bị"],"exp":"Tùy chọn B đúng: Logic không yêu cầu UI. Kiểm tra đơn vị isolate một hàm, phương thức hoặc lớp; mô phỏng giúp kiểm soát và lặp lại các phần phụ thuộc bên ngoài."},"PRM-390":{"q":"Theo kim tự tháp thử nghiệm, loại thử nghiệm nào sẽ có nhiều nhất?","options":["Kiểm tra đơn vị","Chỉ kiểm tra thủ công","Phát hành thử nghiệm","Kiểm tra tích hợp"],"exp":"Tùy chọn A đúng: Kiểm tra đơn vị. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-391":{"q":"Loại thử nghiệm nào nên được ưu tiên khi xảy ra lỗi logic?","options":["Chỉ kiểm tra tích hợp","Chỉ chụp màn hình thủ công","Kiểm tra đơn vị","Kiểm tra kích thước ứng dụng"],"exp":"Lựa chọn C đúng: Kiểm tra đơn vị. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-392":{"q":"Bước Hành động trong thử nghiệm đơn vị của toggle() là gì?","options":["Chạy flutter build","Tạo nhiệm vụ","Gọi expect()","Gọi task.toggle()"],"exp":"Tùy chọn D đúng: Gọi task.toggle(). Kiểm tra đơn vị isolate một hàm, phương thức hoặc lớp; mô phỏng giúp kiểm soát và lặp lại các phần phụ thuộc bên ngoài."},"PRM-393":{"q":"Phương pháp thử nghiệm nào tốt nhất là chính xác?","options":["Kiểm tra lại hành vi của khung Flutter","Không bao giờ sử dụng chìa khóa","Giữ các bài kiểm tra ở quy mô nhỏ và tập trung, đồng thời mô phỏng các kho lưu trữ khi có thể","Sử dụng các bài kiểm tra tích hợp cho mọi phương pháp"],"exp":"Tùy chọn C đúng: Giữ các bài kiểm tra nhỏ và tập trung, đồng thời mô phỏng các kho lưu trữ khi có thể. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-394":{"q":"package nào thường được sử dụng để mô phỏng trong các bài kiểm tra Dart?","options":["provider","mocktail","skia","sqflite"],"exp":"Tùy chọn B đúng: mocktail. Kiểm tra đơn vị isolate một hàm, phương thức hoặc lớp; mô phỏng giúp kiểm soát và lặp lại các phần phụ thuộc bên ngoài."},"PRM-395":{"q":"Trong Demo 11.4 (Thử nghiệm tích hợp: Luồng CRUD đầy đủ), thử nghiệm tuần tự: thêm tác vụ → mở chi tiết → chỉnh sửa tiêu đề → lưu → kiểm tra danh sách cập nhật. Tại sao loại thử nghiệm này được phân loại là \"Thử nghiệm tích hợp\" thay vì \"Thử nghiệm Widget\" đơn giản?","options":["Bởi vì nó sử dụng nhiều dòng mã hơn một bài kiểm tra Widget thông thường","Bởi vì nó xác thực toàn bộ luồng tương tác trên nhiều ứng dụng layers (UI → Provider → Repository) thông qua các bước liên tiếp, mô phỏng hành trình thực hoàn chỉnh của người dùng, thay vì chỉ kiểm tra một hành vi UI riêng lẻ","Bởi vì nó hoàn toàn không sử dụng bất kỳ widgets nào","Bởi vì Kiểm tra tích hợp và Kiểm tra Widget là cùng một khái niệm, chỉ khác tên"],"exp":"Nó được phân loại là Kiểm tra tích hợp vì nó xác thực toàn bộ luồng trên UI → Provider → Repository, mô phỏng toàn bộ hành trình của người dùng. A, C, D không phù hợp với lý do phân loại."},"PRM-396":{"q":"`find.byKey(const Key('taskTextField'))` được dùng để làm gì trong bài kiểm tra?","options":["Tìm kiếm văn bản hiển thị trên màn hình theo nội dung chuỗi","Tìm chính xác một widget cụ thể thông qua Key được chỉ định của nó, làm cho việc nhận dạng widget trong cây thử nghiệm trở nên đáng tin cậy hơn so với tìm kiếm theo loại hoặc text (có thể trùng lặp hoặc thay đổi)","Tìm tất cả TextFields trên màn hình bất kể Key","Không có tác dụng, chỉ mang tính minh họa"],"exp":"find.byKey() định vị một widget cụ thể một cách đáng tin cậy thông qua Key được chỉ định, đáng tin cậy hơn so với tìm kiếm theo loại/văn bản. A, C, D mô tả sai chức năng của nó."},"PRM-397":{"q":"Tại sao bài giảng lại khuyến nghị \"Sử dụng phím cho widget bài kiểm tra\"?","options":["Bởi vì Khóa là bắt buộc về mặt cú pháp đối với mọi Flutter widget","Bởi vì việc chỉ định Khóa giúp xác định chính xác một widget cụ thể trong thử nghiệm, tránh nhầm lẫn khi tồn tại nhiều widgets cùng loại hoặc nội dung văn bản trên màn hình","Bởi vì Khóa tăng gấp đôi tốc độ thực hiện bài kiểm tra","Khóa chỉ hoạt động với StatelessWidget, không hoạt động với StatefulWidget"],"exp":"Việc chỉ định Khóa hỗ trợ vị trí widget chính xác trong các thử nghiệm, tránh nhầm lẫn giữa các widgets tương tự. A, C, D không khớp với lý do đằng sau khuyến nghị này."},"PRM-398":{"q":"Trong tệp kiểm tra `test/widget/demo_11_3_navigation_to_detail_test.dart`, giả sử xác nhận final là: expect(find.text('Task Detail'), findsOneWidget); but the detail screen actually displays the title as \"Task Details\" (with an extra \"s\"). Kết quả kiểm tra là gì?","options":["test vẫn vượt qua vì Flutter tự động thực hiện đối sánh text mờ","test fails (findsOneWidget lỗi vì không tìm thấy widget with the chính xác text \"Task Detail\"), vì `find.text()` yêu cầu đối sánh chuỗi chính xác an","test tự động bỏ qua xác nhận này","test vượt qua but in cảnh báo, không xử lý lỗi as"],"exp":"find.text() yêu cầu đối sánh chuỗi chính xác an, do đó, \"Task Detail\" không khớp với \"Task Details\" sẽ khiến the test không khớp. A, C, D không khớp với hành vi khớp thực tế của find.text()."},"PRM-399":{"q":"`tester.pumpWidget(createTaskListTestApp())` làm gì trong bước đầu tiên của Bài kiểm tra Widget?","options":["Xóa tất cả dữ liệu kiểm tra trước đó","Pumps\" (hiển thị) cây widget đã cho vào môi trường thử nghiệm ảo, tương đương với việc khởi chạy ứng dụng lần đầu tiên để bắt đầu thử nghiệm","Xây dựng ứng dụng thành tệp APK","Kết nối với máy chủ thực để lấy dữ liệu"],"exp":"pumpWidget() hiển thị cây widget đã cho vào môi trường thử nghiệm, tương đương với việc khởi chạy ứng dụng để bắt đầu thử nghiệm. A, C, D mô tả sai chức năng này."},"PRM-400":{"q":"Theo \"Cách Flutter xây dựng UI (Đường dẫn kết xuất)\", vai trò tương ứng của ba khái niệm cốt lõi Widget, Phần tử, RenderObject là gì?","options":["Widget là một bản thiết kế bất biến mô tả cấu hình, Element quản lý lifecycle & state, RenderObject thực hiện bố cục/vẽ/tổng hợp thực tế","Widget, Element, RenderObject là ba tên khác nhau cho cùng một khái niệm","RenderObject là bất biến, Widget thực hiện vẽ trực tiếp lên màn hình","Phần tử chỉ tồn tại trong Thử nghiệm Widget chứ không tồn tại khi ứng dụng thực sự chạy"],"exp":"Widget = bản thiết kế bất biến, trình quản lý Element = lifecycle/state, RenderObject = thực hiện bố cục/vẽ/kết hợp. B, C, D mô tả sai vai trò của ba thành phần này."},"PRM-401":{"q":"Kiểm tra vàng ở Flutter kiểm tra điều gì?","options":["Xử lý dữ liệu không đồng bộ logic (Future/Stream)","So sánh hình ảnh UI được hiển thị của widget với hình ảnh reference (\"vàng\") đã lưu để phát hiện hiện tượng hồi quy hình ảnh ngoài ý muốn","Đang kiểm tra tốc độ phản hồi API","Kiểm tra tính bảo mật của ứng dụng"],"exp":"Thử nghiệm vàng so sánh UI được kết xuất với hình ảnh tham chiếu vàng đã lưu để phát hiện hồi quy trực quan. A, C, D mô tả sai mục đích của loại bài kiểm tra này."},"PRM-402":{"q":"Trong `flutter_test`, chức năng nào được sử dụng để so sánh widget hiện tại với hình ảnh vàng đã lưu?","options":["`expect(find.text(...), findsOneWidget)`","`matchesGoldenFile('image_label.png')` kết hợp với `expectLater()`","`tester.pumpAndSettle()`","`verify()`"],"exp":"`matchesGoldenFile()` kết hợp với `expectLater()` là flutter_test API tiêu chuẩn để so sánh với hình ảnh vàng. A, C, D không phải là chức năng chính xác cho mục đích này."},"PRM-403":{"q":"Một nhóm học sinh thực hiện Bài kiểm tra vàng trên Windows, nhưng hình ảnh vàng ban đầu được tạo trên macOS, khiến bài kiểm tra liên tục thất bại mặc dù UI trông \"giống hệt\" bằng mắt thường. Nguyên nhân phổ biến nhất của vấn đề này là gì?","options":["Golden Tests không bao giờ hoạt động đáng tin cậy trên bất kỳ hệ điều hành nào","Kết xuất phông chữ và khử răng cưa có thể hơi khác nhau giữa các phiên bản hệ điều hành/Flutter, khiến hình ảnh theo từng pixel không khớp chính xác ngay cả khi khó nhận thấy bằng mắt --- vì vậy, các bài kiểm tra Vàng thường được khuyên nên chạy nhất quán trên cùng một environment (e.g. một CI) cố định để tránh lỗi sai","Vì SliverAppBar không tương thích với Golden Test","Vì Windows không hỗ trợ chạy `flutter test`"],"exp":"Sự khác biệt nhỏ về kết xuất phông chữ/khử răng cưa giữa các nền tảng gây ra pixel không khớp, do đó nên chạy Thử nghiệm vàng trên một environment nhất quán ({1}} cố định). A, C, D không khớp với nguyên nhân kỹ thuật thực tế."},"PRM-404":{"q":"Trong `flutter_bloc`, `BlocListener` widget khác với `BlocBuilder` như thế nào?","options":["Hai widgets hoàn toàn giống nhau, có thể hoán đổi cho nhau trong mọi trường hợp","`BlocBuilder` được sử dụng để xây dựng lại UI dựa trên state mới (trả về widget); `BlocListener` được sử dụng để thực hiện một lần side-effects (e.g. điều hướng, hiển thị SnackBar/Dialog) khi state thay đổi, KHÔNG xây dựng lại UI","`BlocListener` chỉ có thể được sử dụng với Cubit chứ không phải với Bloc","`BlocBuilder` chỉ được sử dụng cho Thử nghiệm vàng"],"exp":"BlocBuilder xây dựng lại UI dựa trên state mới; BlocListener thực hiện tác dụng phụ một lần đối với thay đổi state mà không cần xây dựng lại. A, C, D mô tả sai sự khác biệt giữa hai widgets này."},"PRM-405":{"q":"ChangeNotifier sử dụng phương pháp nào để thông báo cho người nghe?","options":["json.decode()","setString()","notifyListeners()","pumpAndSettle()"],"exp":"Tùy chọn C đúng: notifyListeners(). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-406":{"q":"JSON là gì?","options":["Một công cụ kết xuất","Ngôn ngữ Flutter UI","Một định dạng văn bản nhẹ để trao đổi dữ liệu mảng và khóa-giá trị","Một loại bài kiểm tra widget"],"exp":"Tùy chọn C đúng: Định dạng văn bản nhẹ để trao đổi dữ liệu mảng và khóa-giá trị. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-407":{"q":"package nào được sử dụng trong các trang trình bày cho yêu cầu HTTP?","options":["http","sqflite","chỉ provider","flutter_test"],"exp":"Tùy chọn A đúng: http. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-408":{"q":"package nào giúp định vị thư mục tài liệu của ứng dụng?","options":["provider","flutter_test","path_provider","http"],"exp":"Tùy chọn C đúng: path_provider. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-409":{"q":"Bài kiểm tra widget xác thực điều gì?","options":["Tải lên Google Play","Ký mã thông báo","hiển thị UI và tương tác widget","Chỉ có công cụ cơ sở dữ liệu gốc"],"exp":"Tùy chọn C đúng: hiển thị UI và tương tác widget. Các thử nghiệm Widget xác minh khả năng hiển thị và tương tác của UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-410":{"q":"Tại sao nên có ít bài kiểm tra tích hợp hơn?","options":["Flutter không thể chạy chúng","Họ không thể sử dụng expect()","Chúng chậm hơn và đắt hơn, vì vậy chúng nên tập trung vào các luồng quan trọng","Họ không thể kiểm tra UI"],"exp":"Phương án C đúng: Chúng chậm hơn và đắt hơn, vì vậy chúng nên tập trung vào các luồng quan trọng. Kiểm thử tích hợp thực hiện toàn diện một ứng dụng hoàn chỉnh hoặc một tính năng quan trọng; Patrol thêm hỗ trợ cho các tương tác trên nền tảng gốc."},"PRM-411":{"q":"Bước final của quy trình kiểm tra thường là gì?","options":["Sử dụng expect() để xác minh kết quả","Lưu SharedPreferences","Ký JWT","Tạo một release APK"],"exp":"Tùy chọn A đúng: Sử dụng expect() để xác minh kết quả. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-412":{"q":"Loại thử nghiệm nào sẽ được ưu tiên khi UI không cập nhật?","options":["Ping mạng","bài kiểm tra Widget","bài kiểm tra SQL","Kiểm tra chữ ký"],"exp":"Tùy chọn B đúng: kiểm tra Widget. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-413":{"q":"Nên sử dụng thử nghiệm nào để kiểm tra điều hướng không chính xác?","options":["Bài kiểm tra điều hướng hoặc widget","Kiểm tra bộ đệm hình ảnh","Bài kiểm tra chỉ có SharedPreferences","APK Trình phân tích"],"exp":"Tùy chọn A đúng: Kiểm tra điều hướng hoặc widget. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-414":{"q":"Phương pháp nào được sử dụng cho bước Assert?","options":["expect()","print()","notifyListeners()","setState()"],"exp":"Tùy chọn A đúng: expect(). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-415":{"q":"tester.pumpWidget() làm gì?","options":["Hiển thị cây widget trong môi trường thử nghiệm","Ký tên vào ứng dụng","Gửi yêu cầu HTTP","Mở cơ sở dữ liệu"],"exp":"Tùy chọn A đúng: Hiển thị cây widget trong môi trường thử nghiệm. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-416":{"q":"tester.tap() mô phỏng hành động nào của người dùng?","options":["Nhập văn bản","Đặt lại Provider","Đang chờ hoạt hình","Nhấn vào widget"],"exp":"Tùy chọn D đúng: Nhấn vào widget. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-417":{"q":"Khi nào pumpAndSettle() hữu ích?","options":["Đang chờ hoạt ảnh và điều hướng kết thúc","Tạo một Future chưa hoàn thành","Ngăn chặn việc xây dựng lại UI","Chỉ thử nghiệm một đơn vị mô hình"],"exp":"Tùy chọn A đúng: Đang chờ hoạt ảnh và điều hướng kết thúc. pumpAndSettle nâng cao các khung cho đến khi các khung đã lên lịch ổn định, điều này rất hữu ích cho hoạt ảnh và chuyển tiếp tuyến đường."},"PRM-418":{"q":"findsOneWidget xác minh điều gì?","options":["Tồn tại ít nhất mười widgets","Không có widgets tồn tại","Chính xác một widget khớp với công cụ tìm","Một hàng cơ sở dữ liệu tồn tại"],"exp":"Tùy chọn C đúng: Chính xác một widget khớp với công cụ tìm. Các thử nghiệm Widget xác minh khả năng hiển thị và tương tác của UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-419":{"q":"Khóa giúp ích như thế nào trong bài kiểm tra widget?","options":["Nó trực tiếp tăng FPS","Nó mã hóa một token","Nó làm giảm kích thước ứng dụng","Nó cung cấp một cách ổn định để tìm widget chính xác cho tương tác"],"exp":"Tùy chọn D đúng: Nó cung cấp một cách ổn định để tìm widget chính xác cho tương tác. Các thử nghiệm Widget xác minh khả năng hiển thị và tương tác của UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-420":{"q":"package nào giúp tạo ra các mô hình và mã JSON bất biến?","options":["freezed","lint","flutter_test","path"],"exp":"Tùy chọn A đúng: freezed. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-421":{"q":"Widget bài kiểm tra được sử dụng để?","options":["Kiểm tra UI widgets","Xuất bản ứng dụng","Định cấu hình IDE","Tạo plugin"],"exp":"Lựa chọn A đúng: Kiểm tra UI widgets. Các thử nghiệm Widget xác minh khả năng hiển thị và tương tác của UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-422":{"q":"Tiện ích thử nghiệm widget nào bơm khung/{0}}?","options":["tester.pump","tester.run","tester.click","tester.build"],"exp":"Tùy chọn A đúng: tester.pump. Các thử nghiệm Widget xác minh khả năng hiển thị và tương tác của UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-423":{"q":"package nào cung cấp API thử nghiệm Flutter cốt lõi?","options":["flutter_test","flutter_http","flutter_state","flutter_async"],"exp":"Tùy chọn A đúng: flutter_test. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-424":{"q":"Mục đích chính của Thử nghiệm Widget trong Flutter là gì?","options":["Để xác thực các luồng người dùng hoàn chỉnh từ đầu đến cuối.","Để kiểm tra logic nghiệp vụ hoàn toàn tách biệt với UI.","Để xác thực việc hiển thị UI và các tương tác widget riêng lẻ.","Để kiểm tra xem ứng dụng có thể kết nối với cơ sở dữ liệu từ xa hay không."],"exp":"Tùy chọn C đúng: Để xác thực việc hiển thị UI và các tương tác widget riêng lẻ.. Các thử nghiệm Widget xác minh việc hiển thị và tương tác UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-425":{"q":"Trong thử nghiệm widget, phương pháp nào được sử dụng cụ thể để kích hoạt quá trình xây dựng lại UI sau interaction (chẳng hạn như nhấn nút)?","options":["tester.tap()","tester.pumpAndSettle()","tester.pump()","tester.pumpWidget()"],"exp":"Tùy chọn C đúng: tester.pump(). Các thử nghiệm Widget xác minh khả năng hiển thị và tương tác của UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-426":{"q":"Khi kiểm tra điều hướng giữa các màn hình, tại sao lại sử dụng tester.pumpAndSettle() thay vì tester.pump() tiêu chuẩn?","options":["Để xóa bộ nhớ đệm cục bộ trước khi chuyển sang màn hình mới.","Để chờ tất cả hoạt ảnh và chuyển tiếp hoàn tất.","Để mô phỏng người dùng nhấn nút quay lại vật lý.","Để làm mới việc quản lý Provider state."],"exp":"Tùy chọn B đúng: Để đợi tất cả hoạt ảnh và chuyển tiếp hoàn tất.. pumpAndSettle nâng cao khung hình cho đến khi khung được lên lịch ổn định, điều này rất hữu ích cho hoạt ảnh và chuyển tiếp tuyến đường."},"PRM-427":{"q":"Phương pháp hay nhất được đề xuất để xác định widgets trong bài kiểm tra widget nhằm đảm bảo chúng được tìm thấy dễ dàng là gì?","options":["Luôn tìm kiếm theo màu của widget.","Tìm kiếm theo số dòng trong mã nguồn.","Sử dụng Keys duy nhất (e.g., find.byKey).","Chỉ dựa vào chuỗi văn bản được mã hóa cứng"],"exp":"Tùy chọn C đúng: Sử dụng các thử nghiệm Keys (e.g., find.byKey) duy nhất.. Widget xác minh việc hiển thị và tương tác UI trong môi trường thử nghiệm của Flutter; người tìm kiếm và người so khớp xác nhận những gì hiện có và cách nó hoạt động."},"PRM-428":{"q":"Theo \"Quy trình kiểm tra\", chức năng nào được sử dụng để xác minh rằng kết quả thực tế của kiểm tra phù hợp với hành vi dự kiến?","options":["verify()","check()","expect()","assert()"],"exp":"Tùy chọn C đúng: expect(). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-429":{"q":"Trong kim tự tháp kiểm thử, có bao nhiêu Kiểm thử tích hợp được khuyến nghị và nhằm mục đích gì?","options":["Sử dụng nhiều nhất vì đây là loại bài kiểm tra toàn diện nhất","Sử dụng ít vì chúng chạy chậm và tốn nhiều chi phí hơn --- chỉ nên áp dụng cho các luồng người dùng quan trọng, quan trọng đối với doanh nghiệp","Kiểm tra tích hợp không bao giờ nên được sử dụng trong bất kỳ trường hợp nào","Chỉ dùng để kiểm tra hiệu năng CPU"],"exp":"Kiểm thử tích hợp nên được sử dụng một cách tiết kiệm vì chúng chậm/tốn kém --- dành riêng cho các luồng người dùng quan trọng. A, C, D không phù hợp với nguyên tắc của Kim tự tháp Kiểm tra."},"PRM-430":{"q":"Một sinh viên viết Bài kiểm tra tích hợp nhưng vẫn muốn kiểm tra xem \"màu nền của AppBar có chính xác là Colors.blue theo mặc định của Material Design hay không\" (hành vi khung mặc định, không phải logic ứng dụng tùy chỉnh). Theo \"Các phương pháp hay nhất\" đã học được, tại sao nên tránh phương pháp này?","options":["Vì Integration Test không được phép kiểm tra màu sắc dưới mọi hình thức","Bởi vì điều này kiểm tra behavior mặc định của khung Flutter (không phải logic nghiệp vụ tùy chỉnh của ứng dụng), lãng phí công sức viết kiểm thử mà không thêm bất kỳ giá trị thực nào để đảm bảo chất lượng ứng dụng","Bởi vì AppBar không thể được kiểm tra bằng bất kỳ công cụ nào","Bởi vì màu sắc luôn thay đổi ngẫu nhiên giữa các bản dựng nên không thể kiểm tra được"],"exp":"Việc kiểm tra hành vi của khung mặc định thay vì logic ứng dụng tùy chỉnh sẽ lãng phí công sức mà không thêm giá trị đảm bảo chất lượng thực sự. A, C, D không khớp với lý do tránh điều này."},"PRM-431":{"q":"Mục đích của ThemeData là gì?","options":["Chạy thử nghiệm tích hợp","Gọi REST API","Xác định màu sắc, kiểu chữ và hình dạng chung","Lưu trữ mã thông báo phiên"],"exp":"Tùy chọn C đúng: Xác định màu sắc, kiểu chữ và hình dạng chung. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-432":{"q":"Kiểm tra tích hợp xác nhận điều gì?","options":["Chỉ một người xác thực","Một hàm thuần túy bị cô lập","Văn bản tĩnh widget","Luồng người dùng hoàn chỉnh từ đầu đến cuối"],"exp":"Tùy chọn D đúng: Luồng người dùng hoàn chỉnh từ đầu đến cuối. Kiểm thử tích hợp thực hiện toàn diện một ứng dụng hoàn chỉnh hoặc một tính năng quan trọng; Patrol thêm hỗ trợ cho các tương tác trên nền tảng gốc."},"PRM-433":{"q":"Kiểm tra tích hợp được sử dụng để?","options":["Kiểm tra toàn bộ luồng ứng dụng","Chỉ biên dịch mã","Vẽ UI","Mã định dạng"],"exp":"Tùy chọn A đúng: Kiểm tra toàn bộ luồng ứng dụng. Kiểm thử tích hợp thực hiện toàn diện một ứng dụng hoàn chỉnh hoặc một tính năng quan trọng; Patrol thêm hỗ trợ cho các tương tác trên nền tảng gốc."},"PRM-434":{"q":"Tại sao nên sử dụng các thử nghiệm tích hợp sparingly (\"số ít\" ở trên cùng của kim tự tháp)?","options":["Bởi vì chúng kém tin cậy nhất trong việc bắt lỗi.","Bởi vì họ không thể kiểm tra điều hướng.","Bởi vì chúng chạy chậm và tốn kém so với các thử nghiệm khác.","Bởi vì chúng chỉ hoạt động ở chế độ Gỡ lỗi."],"exp":"Tùy chọn C đúng: Bởi vì chúng chạy chậm và tốn kém so với các thử nghiệm khác.. Thử nghiệm tích hợp thực hiện một ứng dụng hoàn chỉnh hoặc một tính năng quan trọng từ đầu đến cuối; Patrol thêm hỗ trợ cho các tương tác trên nền tảng gốc."},"PRM-435":{"q":"Quy trình hiển thị của Flutter tuân theo thứ tự nào?","options":["Kết xuất GPU → Cây Widget → Cây kết xuất → Cảnh tổng hợp","Widget Cây → Cây kết xuất → Cảnh tổng hợp → Kết xuất GPU","Cây kết xuất → Cây Widget → Kết xuất GPU → Cảnh tổng hợp","Cảnh tổng hợp → Cây Widget → Kết xuất GPU → Cây kết xuất"],"exp":"Quy trình kết xuất: Widget Cây → Cây kết xuất → Cảnh tổng hợp → Kết xuất GPU, khớp chính xác với thứ tự của trang chiếu. Các tùy chọn khác đảo ngược thứ tự không chính xác."},"PRM-436":{"q":"Theo \"Tại sao lại có thông báo sau khi xác thực?\", mục đích chính của việc gửi thông báo ngay sau khi login thành công (e.g. \"Đăng nhập thành công. Chào mừng bạn quay lại!\") là gì?","options":["Thay thế hoàn toàn việc hiển thị SnackBar","Kết nối thông báo với hoạt động kinh doanh thực sự của ứng dụng workflows (như xác nhận một hành động quan trọng vừa xảy ra), tăng mức độ tương tác của người dùng và nhận thức về trạng thái tài khoản của họ","Chỉ nhằm mục đích kiểm tra quyền truy cập Internet của thiết bị","Bắt buộc để JWT có hiệu lực"],"exp":"Mục đích là kết nối thông báo với quy trình công việc kinh doanh thực tế, tăng cường mức độ tương tác và nhận thức về trạng thái tài khoản. A, C, D không phù hợp với mục đích thực tế đã nêu."},"PRM-437":{"q":"Trình tự đường dẫn kết xuất được trình bày trong các trang trình bày là gì?","options":["Mã nguồn -> SQL -> Cây kết xuất -> API","Widget Cây -> HTTP -> JSON -> GPU","Widget Cây -> Cây kết xuất -> Cảnh tổng hợp -> Kết xuất GPU","GPU -> Widget Cây -> Cơ sở dữ liệu -> UI"],"exp":"Tùy chọn C đúng: Widget Cây -> Cây kết xuất -> Cảnh tổng hợp -> Kết xuất GPU. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-438":{"q":"Trình tự nào là quy trình làm việc SharedPreferences chính xác?","options":["Tải phiên bản -> đọc -> cập nhật -> lưu -> làm mới UI","Lưu -> xây dựng APK -> xóa","HTTP -> JSON -> GPU","Tuyến -> bật -> đẩy"],"exp":"Tùy chọn A đúng: Tải phiên bản -> đọc -> cập nhật -> lưu -> làm mới UI. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-439":{"q":"Widget được mô tả như thế nào trong quy trình kết xuất của Flutter?","options":["Đối tượng duy nhất vẽ trực tiếp","Một kế hoạch bất biến","Phản hồi HTTP","Một hàng cơ sở dữ liệu"],"exp":"Lựa chọn B đúng: Một bản thiết kế không thể thay đổi. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-440":{"q":"Trong quy trình làm việc SharedPreferences, bước final sau khi giá trị được lưu vào bộ lưu trữ là gì?","options":["Tải lại phiên bản","Đọc chìa khóa","Làm mới UI để phản ánh dữ liệu đã cập nhật","Đóng tập tin cơ sở dữ liệu"],"exp":"Tùy chọn C đúng: Làm mới UI để phản ánh dữ liệu đã cập nhật. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-441":{"q":"Trong quy trình kiểm tra Flutter tiêu chuẩn, ba steps (\"3 As\") được sử dụng để cấu trúc kiểm tra là gì?","options":["Áp dụng, hành động, khẳng định","Sắp xếp, hành động, khẳng định","Sắp xếp, phân tích, áp dụng","Lắp ráp, hành động, khẳng định"],"exp":"Phương án B đúng: Sắp xếp, Hành động, Khẳng định. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-442":{"q":"Trong quy trình kết xuất Flutter, thành phần cụ thể nào chịu trách nhiệm xử lý lifecycle và state của widgets?","options":["Widgets","Elements","RenderObjects","Skia Động cơ"],"exp":"Tùy chọn B đúng: Elements. Đây là khái niệm quản lý state: các thay đổi state phải thông báo hoặc kích hoạt phần có liên quan của UI để xây dựng lại."},"PRM-443":{"q":"Flutter sử dụng ngôn ngữ lập trình và công cụ kết xuất nào?","options":["Kotlin và Skia","Dart và Skia","Dart và động cơ V8","Swift và Kim loại"],"exp":"Flutter sử dụng Dart với công cụ kết xuất Skia. (A, C, D đều ghép sai ngôn ngữ/động cơ.)"},"PRM-444":{"q":"Trong bảng so sánh khung từ Mô-đun 1, điểm khác biệt cốt lõi giữa Flutter và React Native là gì?","options":["Flutter sử dụng Dart và biên dịch thành UI gốc bằng công cụ riêng của nó, trong khi React Bản địa sử dụng JavaScript và kết nối với các thành phần gốc","Cả hai đều biên dịch trực tiếp thành mã máy gốc mà không cần động cơ","React Bản địa nhanh hơn vì không cần cầu nối","Flutter không thể xây dựng cho iOS, chỉ Android"],"exp":"Bảng so sánh: Flutter (Dart, Gốc UI + Engine) so với React Native (JS, Bridge to Native) so với Native (Kotlin/Swift, Pure Native) --- như được hiển thị trong trang trình bày. B sai vì React Bản địa cần một cầu nối; C và D là những yêu cầu không được hỗ trợ."},"PRM-445":{"q":"Điều gì đặc trưng cho lớp trừu tượng trong Dart?","options":["Nó không thể có bất kỳ phương pháp nào với cơ thể","Nó định nghĩa cấu trúc không có hành vi đầy đủ, buộc các lớp con phải thực hiện các phương thức không có nội dung","Chỉ có thể sử dụng được bên trong Khung Flutter, không sử dụng được ở dạng Dart thuần túy","Có thể được khởi tạo trực tiếp bằng từ khóa `new`"],"exp":"Một lớp trừu tượng định nghĩa cấu trúc không có hành vi đầy đủ, buộc các lớp con phải triển khai cấu trúc đó. A sai vì các lớp trừu tượng có thể có các phương thức có nội dung; C sai vì nó cũng hoạt động ở dạng Dart thuần túy; D sai vì các lớp trừu tượng không thể được khởi tạo trực tiếp."},"PRM-446":{"q":"`SafeArea` trong Flutter giải quyết được vấn đề gì trên các thiết bị hiện đại?","options":["Tăng tốc độ hiển thị của ứng dụng","Tránh nội dung UI bị che khuất bởi các khu vực không sử dụng được như rãnh khía, Đảo động hoặc màn hình cong","Mã hóa dữ liệu người dùng","Tự động dịch ngôn ngữ UI"],"exp":"SafeArea tránh nội dung UI bị che khuất bởi rãnh khía/Đảo động/màn hình cong. A, C, D mô tả sai mục đích của SafeArea."},"PRM-447":{"q":"Flutter nhắm đến tốc độ khung hình nào target (FPS) để đảm bảo trải nghiệm mượt mà trên các thiết bị tiêu chuẩn?","options":["24 khung hình/giây","30 khung hình/giây","60 khung hình/giây","144 khung hình/giây"],"exp":"Flutter nhắm mục tiêu 60 FPS để có trải nghiệm mượt mà trên các thiết bị tiêu chuẩn. A, B, D không trùng với số đã nêu."},"PRM-448":{"q":"Nếu một thiết bị chạy ở tốc độ 60 FPS, thì Flutter phải mất khoảng bao nhiêu mili giây để hoàn thành quá trình xây dựng, bố cục và vẽ cho MỖI khung hình trước khi xảy ra frame (giật)?","options":["Khoảng 16,6 mili giây","Khoảng 100 mili giây","Khoảng 1 mili giây","Khoảng 1000 mili giây"],"exp":"Ở tốc độ 60 FPS, Flutter có khoảng 16,6 mili giây trên mỗi khung hình. B, C, D không đúng với con số tính toán trong bài giảng."},"PRM-449":{"q":"Lớp khung Flutter chủ yếu được viết bằng ngôn ngữ nào?","options":["Dart","C++","Swift","Rust"],"exp":"Tùy chọn A đúng: Dart. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-450":{"q":"Dart được mô tả trong các trang trình bày như thế nào?","options":["Ngôn ngữ hợp ngữ cho Android","Ngôn ngữ đánh dấu web","Ngôn ngữ dựa trên lớp, được tối ưu hóa cho khách hàng do Google phát triển","Một ngôn ngữ chỉ được sử dụng cho cơ sở dữ liệu"],"exp":"Tùy chọn C đúng: Ngôn ngữ dựa trên lớp, được tối ưu hóa cho khách hàng do Google phát triển. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-451":{"q":"Thư viện nào được sử dụng để đọc và ghi đối tượng Tệp trong Dart?","options":["dart:html is always required","dart:io","flutter/rendering","dart:ui only"],"exp":"Tùy chọn B đúng: dart:io. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-452":{"q":"Ở tốc độ 60 FPS, mỗi khung hình có bao nhiêu thời gian?","options":["Khoảng 16,6 mili giây","120 mili giây","8 mili giây","60 mili giây"],"exp":"Lựa chọn A đúng: Khoảng 16,6 mili giây. Hiệu suất Flutter phải được đánh giá ở chế độ profile, tốt nhất là trên thiết bị vật lý vì thời gian ở chế độ debug không mang tính đại diện."},"PRM-453":{"q":"Lợi ích của hàm tạo const là gì?","options":["Tạo bảng cơ sở dữ liệu","Mã hóa mã thông báo","Tăng độ trễ mạng","Giảm công việc xây dựng lại, tiết kiệm bộ nhớ và giúp cây khác biệt"],"exp":"Tùy chọn D đúng: Giảm công việc xây dựng lại, tiết kiệm bộ nhớ và giúp phân biệt cây. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-454":{"q":"Tại sao UniqueKey() có thể gây hại khi sử dụng sai mục đích?","options":["Nó tạo ra một danh tính mới và có thể buộc widgets phải xây dựng lại nhiều lần","Nó không tạo ra một chìa khóa","Nó chỉ được sử dụng cho cơ sở dữ liệu","Nó không biên dịch"],"exp":"Tùy chọn A đúng: Nó tạo ra một danh tính mới và có thể buộc widgets phải xây dựng lại nhiều lần. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-455":{"q":"Kỹ thuật nào tối ưu hóa hình ảnh thu nhỏ một cách chính xác?","options":["Luôn tải hình ảnh lớn nhất","Thay đổi kích thước hoặc nén hình ảnh cho kích thước hiển thị thay vì tải hình ảnh 2000 pixel","Giải mã hình ảnh bên trong build() trên mọi khung hình","Không bao giờ sử dụng trình giữ chỗ"],"exp":"Tùy chọn B đúng: Thay đổi kích thước hoặc nén hình ảnh cho kích thước hiển thị thay vì tải hình ảnh 2000 pixel. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-456":{"q":"Flutter sử dụng công cụ kết xuất nào?","options":["WebKit","Skia","Blink","Metal"],"exp":"Tùy chọn B đúng: Skia. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-457":{"q":"Hàm tạo nào được tối ưu hóa cho lưới lớn?","options":["GridView.count","GridView.builder","GridView.fixed","GridView.simple"],"exp":"Tùy chọn B đúng: GridView.builder. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-458":{"q":"Tại sao nên sử dụng const widgets?","options":["Truy cập mạng nhiều hơn","Tối ưu hóa xây dựng lại tốt hơn","Thêm state","Bật điều hướng"],"exp":"Tùy chọn B đúng: Tối ưu hóa xây dựng lại tốt hơn. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-459":{"q":"Các tính năng biên dịch chính của ngôn ngữ lập trình của Dart, Flutter là gì?","options":["Nó kết hợp quá trình biên dịch trước-Time (AOT) và Just-in-Time (JIT).","Nó thực sự là một ngôn ngữ được giải thích.","Nó chỉ hỗ trợ quản lý bộ nhớ thủ công.","Nó không hỗ trợ an toàn null."],"exp":"Tùy chọn A đúng: Nó kết hợp quá trình biên dịch Ahead-of-Time (AOT) và Just-in-Time (JIT).. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-460":{"q":"Khi công cụ thực thi Dart chạy, công cụ nào sau đây có mức độ ưu tiên cao nhất?","options":["Hàng đợi vi nhiệm","Hàng đợi sự kiện","UI Sự kiện hiển thị","Sự kiện hẹn giờ"],"exp":"Tùy chọn A đúng: Hàng đợi microtask. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-461":{"q":"Tại sao việc tắt nút gửi trong khi yêu cầu mạng đang được thực hiện là UX phương pháp tốt nhất?","options":["Để tiết kiệm pin trên thiết bị.","Để ngăn \"double-gửi\" và hiển thị chỉ báo tải.","Để cho phép công cụ Skia hiển thị nhanh hơn.","Bởi vì Flutter không thể xử lý nhiều yêu cầu POST đồng thời."],"exp":"Tùy chọn B đúng: Để ngăn \"double-gửi\" và hiển thị chỉ báo tải.. Câu trả lời khớp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-462":{"q":"Điều nào sau đây đúng về UI lỗi tràn trong Flutter?","options":["Chúng khiến ứng dụng bị sập ngay lập tức.","Chúng xảy ra khi widget vượt quá giới hạn bố cục nhưng không làm hỏng ứng dụng.","Chúng chỉ có thể được phát hiện bởi một thiết bị vật lý.","Chúng được khung Flutter tự động sửa."],"exp":"Tùy chọn B đúng: Chúng xảy ra khi widget vượt quá giới hạn bố cục nhưng không làm hỏng ứng dụng.. Câu trả lời khớp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-463":{"q":"Cho trước: String? name; print(name ?? \"Guest\"); name = \"Minh\"; print(name!.length); Những gì được in theo thứ tự?","options":["không, 4","Guest, 4","Guest, 5","Lỗi biên dịch vì không thể sử dụng `!` với String? biến"],"exp":"`name` ban đầu có giá trị rỗng nên nó in ra \"Guest\"; sau khi gán \"Minh\" (4 ký tự: M-i-n-h), `name!.length` = 4 → kết quả \"Guest, 4\". A có giá trị đầu tiên sai; C có length sai (phải là 4, không phải 5); D sai vì `!` có giá trị về mặt cú pháp khi biến được đảm bảo không rỗng tại thời điểm đó."},"PRM-464":{"q":"Đối với một ứng dụng chạy trên điện thoại nhỏ, điện thoại lớn, máy tính bảng và máy tính để bàn, tại sao bài giảng lại khuyến nghị \"Tránh các giá trị cố định\"?","options":["Bởi vì Flutter không hỗ trợ các số cố định trong mã","Bởi vì values cố định (e.g. chiều rộng/chiều cao pixel tuyệt đối) không thích ứng với các kích thước màn hình đa dạng, dễ gây tràn hoặc lãng phí dung lượng trên các thiết bị khác","Vì các giá trị cố định làm tăng kích thước tệp APK","Không có lý do kỹ thuật cụ thể"],"exp":"Các giá trị cố định không thích ứng với các kích thước màn hình đa dạng, dễ gây tràn hoặc lãng phí dung lượng. A, C, D không phù hợp với lý do kỹ thuật thực tế."},"PRM-465":{"q":"Tại sao bài giảng khuyến khích thử nghiệm khả năng phản hồi UI trên nhiều thiết bị sizes (e.g. Pixel 2 → Pixel 7 → iPad) thay vì chỉ một emulator duy nhất?","options":["Vì Flutter yêu cầu kiểm tra trên ít nhất 3 thiết bị để gửi bài tập","Bởi vì bố cục behavior (đặc biệt là điểm ngắt, Wrap, GridView) có thể khác nhau đáng kể giữa các kích thước màn hình và lỗi tràn/căn chỉnh sai thường chỉ xuất hiện ở các kích thước cụ thể","Vì mỗi thiết bị chạy một phiên bản Dart khác nhau","Không có lý do thực sự, đó chỉ là một gợi ý tùy chọn"],"exp":"Hành vi bố cục có thể khác nhau đáng kể giữa các kích thước màn hình và lỗi thường chỉ xuất hiện ở các kích thước cụ thể, do đó cần phải thử nghiệm nhiều thiết bị khác nhau. A, C, D không phù hợp với lý do kỹ thuật thực tế."},"PRM-466":{"q":"So sánh ba loại lưu trữ learned (SharedPreferences, JSON File, SQLite) với nguyên tắc ưu tiên ngoại tuyến \"Lưu trữ ngoại tuyến → Sử dụng ngoại tuyến → Đồng bộ hóa trực tuyến\". Khi thiết kế một ứng dụng ghi chú mà sau này sẽ đồng bộ hóa với máy chủ, lựa chọn bộ nhớ cục bộ ban đầu nào giúp việc \"Đồng bộ hóa trực tuyến\" và \"Giải quyết xung đột\" trong tương lai trở nên dễ thực hiện nhất và tại sao?","options":["SharedPreferences, vì đây là cách đơn giản nhất để bắt đầu viết mã","SQLite, vì cấu trúc dữ liệu hàng/cột rõ ràng của nó giúp dễ dàng theo dõi changes (e.g. by id, timestamp) để đồng bộ hóa và giải quyết xung đột với máy chủ, so với việc quản lý một chuỗi blob JSON duy nhất trong SharedPreferences hoặc tệp JSON không có cơ chế truy vấn/theo dõi các thay đổi trên mỗi thành phần","Không cần bộ nhớ cục bộ, luôn gọi API mỗi khi ứng dụng mở để tránh xung đột","Tệp JSON vì tệp tự động đồng bộ hóa trong thời gian thực với máy chủ"],"exp":"Cấu trúc hàng/cột rõ ràng của SQLite giúp việc theo dõi changes (id, dấu thời gian) để đồng bộ hóa/giải quyết xung đột dễ dàng hơn nhiều so với tệp hoặc blob JSON. A, C, D không khớp với lý do kỹ thuật để xử lý xung đột/đồng bộ hóa trong tương lai."},"PRM-467":{"q":"Trong bảng lỗi phổ biến, nếu Đăng nhập bằng Google trả về giá trị rỗng khi kiểm tra trên emulator thì nguyên nhân phổ biến nhất được nêu là gì?","options":["Thiếu quyền sử dụng máy ảnh","emulator thiếu Dịch vụ của Google Play --- thay vào đó hãy sử dụng emulator đã cài đặt Cửa hàng Play hoặc một thiết bị thực","Cấu hình SharedPreferences sai","JWT hết hạn"],"exp":"emulator thiếu Dịch vụ Google Play là nguyên nhân phổ biến; sử dụng một cái với Play Store hoặc thiết bị thực. A, C, D không phù hợp với nguyên nhân đã nêu."},"PRM-468":{"q":"DevTools trong Flutter hỗ trợ những khía cạnh gỡ lỗi nào trong Mô-đun 11?","options":["Chỉ hỗ trợ gỡ lỗi cú pháp","Sự cố về bố cục, cập nhật state không thành công, hiệu suất chậm, việc xây dựng lại không cần thiết và sự cố điều hướng","Chỉ hỗ trợ kiểm tra kết nối mạng","Chỉ được sử dụng để xây dựng ứng dụng release"],"exp":"DevTools hỗ trợ các vấn đề về bố cục, cập nhật state không thành công, hiệu suất, các lần xây dựng lại không cần thiết và các vấn đề điều hướng theo \"Mục tiêu gỡ lỗi trong Flutter\". A, C, D không bao gồm toàn bộ phạm vi của nó."},"PRM-469":{"q":"Tại sao bài giảng khuyên bạn nên chạy Flutter DevTools trong \"Chế độ hồ sơ\" thay vì \"Chế độ gỡ lỗi\" khi đo hiệu suất?","options":["Vì không thể mở DevTools ở Chế độ gỡ lỗi","Bởi vì Chế độ gỡ lỗi có nhiều overhead gỡ lỗi (xác nhận, kiểm tra bổ sung) khiến cho các con số hiệu suất được đo không phản ánh chính xác hiệu suất ở chế độ release thực; Chế độ hồ sơ gần với hiệu suất thực tế hơn","Vì Chế độ Cấu hình chạy chậm hơn Chế độ Gỡ lỗi nên thích hợp cho việc tìm lỗi kỹ lưỡng hơn","Không có sự khác biệt giữa hai chế độ khi đo hiệu năng"],"exp":"Chi phí chung của Chế độ gỡ lỗi làm lệch các con số hiệu suất so với hiệu suất release thực; Profile Mode gần với thực tế hơn. A, C, D không khớp với lý do thực tế của đề xuất này."},"PRM-470":{"q":"Theo \"Kỹ thuật tối ưu hóa 2: Trích xuất tiện ích\" (e.g. trích xuất `TaskTile` thành widget của chính nó), lợi ích chính của việc chia một widget lớn thành các phần nhỏ hơn là gì?","options":["Giảm đáng kể kích thước tệp APK","Khi dữ liệu của một mục thay đổi, chỉ có mục con tương ứng widget (như `TaskTile` cụ thể) cần được xây dựng lại, thay vì xây dựng lại toàn bộ danh sách/màn hình gốc cùng với nó, giảm phạm vi và chi phí xây dựng lại","Một widget được trích xuất sẽ tự động nhận được khóa riêng mà không cần khai báo khóa","Không có lợi ích thực sự, chỉ làm cho mã trông gọn gàng hơn về mặt hình thức"],"exp":"Việc trích xuất widgets thu hẹp phạm vi xây dựng lại chỉ còn mục đã thay đổi, giảm chi phí xây dựng lại tổng thể. A, C, D không phù hợp với lợi ích kỹ thuật thực sự."},"PRM-471":{"q":"Lệnh nào được dùng để phân tích chi tiết kích thước ứng dụng theo mã nguồn, nội dung và gói?","options":["flutter doctor","flutter build apk --analyze-size","flutter test","flutter clean"],"exp":"`flutter build apk --analyze-size` được sử dụng để phân tích chi tiết ứng dụng-size. A, C, D không phải là lệnh đúng cho mục đích này."},"PRM-472":{"q":"Theo \"Mẹo tối ưu hóa kích thước phổ biến\", việc \"Bật biểu tượng tree-shaking\" (xóa các biểu tượng Material không sử dụng) mang lại lợi ích gì cho ứng dụng đã phát hành?","options":["Làm cho các biểu tượng trông đẹp hơn","Xóa các biểu tượng Material Design không thực sự được sử dụng trong ứng dụng khỏi bản dựng final package, làm giảm kích thước của ứng dụng","Rung cây chỉ ảnh hưởng đến tốc độ thời gian chạy ứng dụng chứ không ảnh hưởng đến kích thước","Kỹ thuật này chỉ áp dụng cho hình ảnh, không áp dụng cho biểu tượng"],"exp":"Biểu tượng rung cây sẽ xóa các biểu tượng Material không sử dụng khỏi bản dựng, giảm kích thước ứng dụng. A, C, D không phù hợp với lợi ích thực tế."},"PRM-473":{"q":"Sự khác biệt giữa `flutter build apk --debug` và `flutter build apk --release` là gì?","options":["Không có sự khác biệt nào về hiệu suất hoặc kích thước","debug build chứa thông tin hỗ trợ gỡ lỗi mở rộng, không được tối ưu hóa cho hiệu suất/kích thước; release build được tối ưu hóa, loại bỏ chi phí debug, mang lại hiệu suất và kích thước gần hơn với trải nghiệm thực của người dùng cuối","`--release` chỉ hoạt động trên iOS, `--debug` chỉ hoạt động trên Android","`--debug` luôn tạo ra kích thước tệp nhỏ hơn `--release`"],"exp":"Bản dựng gỡ lỗi mang theo chi phí gỡ lỗi không được tối ưu hóa; Bản dựng release được tối ưu hóa cho hiệu suất và kích thước trong thế giới thực. A, C, D không khớp với sự khác biệt thực sự giữa hai chế độ build."},"PRM-474":{"q":"Google Play require định dạng tệp nào (thay vì APK truyền thống) khi xuất bản ứng dụng lên cửa hàng và lệnh xây dựng tương ứng là gì?","options":["Một .aab file (Android App Bundle), được tạo bằng lệnh `flutter build appbundle --release`","Tệp .ipa, được tạo bằng lệnh `flutter build ios --release`","Tệp .exe, được tạo bằng lệnh `flutter build windows --release`","Google Play chỉ chấp nhận tệp .apk, không có định dạng nào khác"],"exp":"Google Play yêu cầu định dạng .aab, được tạo qua `flutter build appbundle --release`. B, C, D không khớp với định dạng/lệnh chính xác cho Android trên Google Play."},"PRM-475":{"q":"Quy tắc quan trọng nào chi phối `versionCode` trong `android/app/build.gradle` khi xuất bản các bản cập nhật liên tiếp?","options":["Nó phải luôn giữ cùng một giá trị trên mọi release","Nó phải là số nguyên và phải tăng theo mỗi release mới (mọi bản cập nhật được đẩy lên cửa hàng)","Không thành vấn đề, nó có thể là bất kỳ giá trị nào kể cả việc giảm","Chỉ áp dụng cho các ứng dụng chạy trên iOS"],"exp":"versionCode phải là số nguyên và tăng theo mỗi release mới. A, C, D không khớp với quy tắc lập phiên bản bắt buộc này."},"PRM-476":{"q":"Trước khi chạy `flutter build apk --release` cho release chính thức, bài giảng khuyên bạn trước tiên nên dùng thử ứng dụng ở \"Chế độ hồ sơ\" (`flutter run --profile`). Lý do hợp lý nhất cho bước trung gian này là gì?","options":["Bởi vì Chế độ hồ sơ là bước bắt buộc duy nhất để build tệp release thành công","Chế độ cấu hình loại bỏ hầu hết chi phí của Chế độ gỡ lỗi trong khi vẫn cho phép quan sát performance gần như trong thế giới thực (độ mượt/giật, build/tốc độ kết xuất) trước khi tạo release build chính thức, giúp phát hiện sớm các vấn đề về hiệu suất mà không cần phải đợi đến bước đóng gói final","Chế độ hồ sơ và Chế độ phát hành hoàn toàn giống nhau nên bước này không cần thiết","Profile Mode chỉ dùng để kiểm tra lỗi cú pháp, không liên quan tới hiệu năng"],"exp":"Chế độ hồ sơ loại bỏ hầu hết chi phí gỡ lỗi trong khi hiển thị hiệu suất gần như thực tế, phát hiện sớm các sự cố trước final release build. A, C, D không khớp với lý do thực tế của bước này."},"PRM-477":{"q":"Trong Vòng đời phát triển phần mềm chung Cycle (SDLC), vai trò chính của giai đoạn \"Phân tích\" là gì?","options":["Viết mã nguồn chi tiết cho từng tính năng","Thu thập và làm rõ các yêu cầu từ người dùng/khách hàng trước khi bắt đầu thiết kế và mã hóa","Đóng gói và xuất sản phẩm tới cửa hàng","Chạy thử nghiệm tự động final trước release"],"exp":"Giai đoạn Phân tích tập trung vào việc thu thập/làm rõ các yêu cầu trước khi bắt đầu thiết kế và mã hóa. A, C, D là các giai đoạn SDLC khác, không phải Phân tích."},"PRM-478":{"q":"\"Nợ kỹ thuật\" đề cập đến điều gì trong phát triển phần mềm?","options":["Chi phí tài chính trực tiếp được trả cho dịch vụ đám mây provider","Tương lai cost (thời gian sửa lỗi, khó bảo trì, khó mở rộng quy mô) phát sinh từ các quyết định thiết kế/mã hóa vội vàng hoặc không được tối ưu hóa được đưa ra ngay bây giờ, tương tự như một \"nợ\" phải trả dần dần theo thời gian","Số dòng mã tối đa được phép trong một dự án","Một khoản phí bắt buộc phải trả khi xuất bản ứng dụng lên Google Play/App Store"],"exp":"Nợ kỹ thuật là chi phí trong tương lai do các quyết định thiết kế/mã hóa vội vã hiện tại, giống như một khoản nợ được trả dần theo thời gian. A, C, D không phù hợp với khái niệm thực tế."},"PRM-479":{"q":"Trong quá trình phát triển phần mềm lifecycle, giai đoạn \"Thử nghiệm\" thường được đặt ở đâu so với \"Triển khai\" (mã hóa)?","options":["Kiểm tra luôn diễn ra trước khi triển khai trong mọi mô hình phát triển","Việc kiểm tra thường diễn ra after (hoặc liên tục song song, tùy thuộc vào mô hình Agile/TDD) giai đoạn Triển khai, để xác minh mã viết hoạt động theo yêu cầu theo phân tích","Kiểm tra không có mối quan hệ nào với Thực hiện cả","Việc kiểm tra chỉ được thực hiện một lần sau khi ứng dụng được phát hành"],"exp":"Việc kiểm tra thường diễn ra after (hoặc liên tục song song với việc triển khai Agile/TDD), xác minh mã đáp ứng các yêu cầu. A, C, D không khớp với vị trí thông thường của Kiểm tra trong SDLC."},"PRM-480":{"q":"Tính năng nào cho phép nhà phát triển xem các thay đổi mã nhanh chóng mà không cần khởi động lại toàn bộ ứng dụng?","options":["Ký mã","Tải lại nóng","chỉ AOT","Khởi động nguội"],"exp":"Tùy chọn B đúng: Tải lại nóng. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-481":{"q":"Flutter 1.0 được phát hành vào năm nào theo các trang trình bày?","options":["2021","2018","2015","2017"],"exp":"Tùy chọn B đúng: 2018. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-482":{"q":"DartPad phù hợp nhất để làm gì?","options":["Tạo một Android emulator gốc","Chạy mã Dart hoặc Flutter trực tiếp trong trình duyệt mà không cần cài đặt","Quản lý Firebase dự án","Xây dựng tệp AAB đã ký"],"exp":"Tùy chọn B đúng: Chạy mã Dart hoặc Flutter trực tiếp trong trình duyệt mà không cần cài đặt. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-483":{"q":"Lệnh nào thường được sử dụng để kiểm tra môi trường Flutter sau khi cài đặt SDK?","options":["xác minh android","flutter doctor","flutter database","dart publish"],"exp":"Tùy chọn B đúng: flutter doctor. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-484":{"q":"Phương thức lifecycle nào được sử dụng cho bộ điều khiển release hoặc các tài nguyên khác?","options":["runApp()","initState()","createState()","dispose()"],"exp":"Tùy chọn D đúng: dispose(). Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-485":{"q":"Khi nào Material Icons thường được sử dụng?","options":["Lưu trữ dữ liệu quan hệ","Đang biên dịch bản dựng release","Nút điều hướng, nút hành động và chỉ báo trạng thái","Đang phân tích cú pháp JSON"],"exp":"Tùy chọn C đúng: Nút điều hướng, nút hành động và chỉ báo trạng thái. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-486":{"q":"Miền liên kết được thêm vào cho iOS ở đâu?","options":["cài đặt DartPad","AndroidManifest.xml","Ký kết & Khả năng của mục tiêu Á quân","pubspec.yaml"],"exp":"Tùy chọn C đúng: Ký kết & Khả năng của mục tiêu Á quân. Flutter hỗ trợ nhiều mục tiêu triển khai, mặc dù mỗi mục tiêu có thể có SDK, yêu cầu về công cụ và tích hợp nền tảng riêng."},"PRM-487":{"q":"InheritedWidget giúp thực hiện được những gì?","options":["Gửi yêu cầu POST","Ký một APK","Truyền dữ liệu xuống cây widget một cách hiệu quả","Tạo một emulator"],"exp":"Tùy chọn C đúng: Truyền dữ liệu xuống cây widget một cách hiệu quả. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-488":{"q":"Những vấn đề nào có thể xảy ra nếu không có thiết kế đáp ứng?","options":["Cú pháp SQL sai","APK ký không thành công","JWT hết hạn","Tràn, widgets bị căn chỉnh sai, văn bản bị cắt bớt và UX kém"],"exp":"Tùy chọn D đúng: Tràn, widgets bị căn chỉnh sai, văn bản bị cắt bớt và UX kém. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-489":{"q":"Một biểu mẫu được thiết kế tốt có thể giải quyết được những vấn đề gì?","options":["FPS thấp chỉ do hình ảnh lớn","kích thước APK","Ngăn xếp tuyến đường sâu","Dữ liệu không hợp lệ, UX kém và rủi ro về chất lượng dữ liệu"],"exp":"Tùy chọn D đúng: Dữ liệu không hợp lệ, UX kém và rủi ro về chất lượng dữ liệu. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-490":{"q":"GlobalKey`<FormState>` cho phép bạn làm gì?","options":["Truy cập FormState để xác thực, lưu và đặt lại toàn bộ biểu mẫu","Ký tên APK","Mở cơ sở dữ liệu","Tạo một JWT"],"exp":"Tùy chọn A đúng: Truy cập FormState để xác thực, lưu và đặt lại toàn bộ biểu mẫu. Đây là khái niệm quản lý state: các thay đổi state phải thông báo hoặc kích hoạt phần có liên quan của UI để xây dựng lại."},"PRM-491":{"q":"Trình tự nào mô tả quy trình từ biểu mẫu đến chương trình phụ trợ?","options":["UI -> SQLite -> GPU -> Widget","Chỉ biểu mẫu -> Chủ đề -> Navigator","UI Biểu mẫu -> xác thực cục bộ -> Yêu cầu POST -> máy chủ -> phản hồi -> cập nhật UI","Nhập -> ký APK"],"exp":"Tùy chọn C đúng: Biểu mẫu UI -> xác thực cục bộ -> yêu cầu POST -> máy chủ -> phản hồi -> cập nhật UI. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-492":{"q":"Tại sao cuộc gọi API sử dụng async/await?","options":["Để đợi mạng mà không bị treo UI","Để tăng kích thước APK","Để tránh sử dụng các lớp mô hình","Để loại bỏ xử lý lỗi"],"exp":"Tùy chọn A đúng: Chờ mạng mà không đóng băng UI. Dart sử dụng Future cho một kết quả không đồng bộ và Stream cho một chuỗi sự kiện không đồng bộ; async/await làm cho mã dựa trên Future dễ đọc hơn."},"PRM-493":{"q":"Khi nào FutureBuilder thích hợp?","options":["Tạo lược đồ URL tùy chỉnh","Ký đơn","Lưu trữ dữ liệu khóa-giá trị","Kết nối Future một lần với UI và xử lý trạng thái tải, lỗi và dữ liệu"],"exp":"Tùy chọn D đúng: Kết nối Future một lần với UI và xử lý các trạng thái tải, lỗi và dữ liệu. Dart sử dụng Future cho một kết quả không đồng bộ và Stream cho một chuỗi sự kiện không đồng bộ; async/await làm cho mã dựa trên Future dễ đọc hơn."},"PRM-494":{"q":"Tệp JSON cục bộ phù hợp để làm gì?","options":["điều hướng UI","Danh sách, lịch sử hoặc xuất/nhập đơn giản","Mối quan hệ nhiều bảng phức tạp","ký kết JWT"],"exp":"Tùy chọn B đúng: Danh sách, lịch sử hoặc xuất/nhập đơn giản. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-495":{"q":"onCreate trong openDatabase() thường được sử dụng để làm gì?","options":["Đăng nhập bằng Google","Chạy CREATE TABLE khi cơ sở dữ liệu được tạo lần đầu tiên","Gọi một API trên mỗi khung","Hiển thị một ListView"],"exp":"Tùy chọn B đúng: Chạy CREATE TABLE khi cơ sở dữ liệu được tạo lần đầu tiên. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-496":{"q":"Trình tự nào mô tả chính xác luồng xác thực cấp cao?","options":["Nhập thông tin xác thực -> yêu cầu API -> xác minh phụ trợ -> mã thông báo -> mã thông báo lưu trữ -> gửi mã thông báo với các yêu cầu sau","Thông báo -> đăng nhập -> mật khẩu băm trên máy khách","Tuyến đường -> JSON -> SQLite -> mã thông báo","Lưu trữ mã thông báo -> nhập thông tin xác thực -> xây dựng APK"],"exp":"Tùy chọn A đúng: Nhập thông tin xác thực -> yêu cầu API -> xác minh phụ trợ -> mã thông báo -> mã thông báo lưu trữ -> gửi mã thông báo với các yêu cầu sau. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-497":{"q":"Sự khác biệt giữa Thông báo cục bộ và Thông báo đẩy là gì?","options":["Thông báo cục bộ được kích hoạt bởi chính ứng dụng và không cần Internet; Thông báo đẩy được gửi từ máy chủ và cần có Internet cộng với hỗ trợ phụ trợ","Hai loại thông báo hoàn toàn giống nhau về cơ chế","Thông báo đẩy không cần phụ trợ, chỉ có Thông báo cục bộ","Thông báo cục bộ chỉ hoạt động trên iOS"],"exp":"Thông báo cục bộ được kích hoạt bởi ứng dụng, không cần Internet; Thông báo đẩy được gửi từ máy chủ, cần hỗ trợ Internet và phụ trợ. B, C, D mô tả sai/đảo ngược hai loại thông báo này."},"PRM-498":{"q":"Sự khác biệt cơ bản giữa Hoạt ảnh ngầm và Hoạt ảnh rõ ràng trong Flutter là gì?","options":["Hoạt ảnh ngầm cần một AnimationController thủ công, Hoạt ảnh rõ ràng thì không","Hoạt ảnh tiềm ẩn tự động nội suy giữa các giá trị cũ và mới khi thuộc tính thay đổi mà không cần quản lý AnimationController theo cách thủ công; Hoạt ảnh rõ ràng yêu cầu khai báo và kiểm soát rõ ràng AnimationController","Hai loại hoạt hình này hoàn toàn giống nhau, chỉ khác tên thôi","Hoạt ảnh ngầm chỉ hoạt động trên iOS, Hoạt ảnh rõ ràng chỉ hoạt động trên Android"],"exp":"Hoạt hình tiềm ẩn tự động nội suy mà không cần bộ điều khiển thủ công; Hoạt ảnh rõ ràng yêu cầu khai báo/kiểm soát AnimationController rõ ràng. A, C, D không phù hợp với đặc tính kỹ thuật thực tế."},"PRM-499":{"q":"Tệp nào là điểm truy cập chính của ứng dụng Flutter?","options":["web/index.css","lib/main.dart","android/Manifest.xml","kiểm tra/main_test.sql"],"exp":"Tùy chọn B đúng: lib/main.dart. Câu trả lời phù hợp với hành vi loại hệ thống hoặc an toàn vô giá trị của Dart; sử dụng các loại nullable và toán tử nhận biết null một cách có chủ ý để tránh lỗi null."},"PRM-500":{"q":"Ngôn ngữ nào được sử dụng cho logic web Flutter?","options":["Dart","PHP","Ruby","C#"],"exp":"Tùy chọn A đúng: Dart. Flutter hỗ trợ nhiều mục tiêu triển khai, mặc dù mỗi mục tiêu có thể có SDK, yêu cầu về công cụ và tích hợp nền tảng riêng."}};
